local config = {
  ui_story_5088_50880100_1_dialog_content = "<color=#e8d9bb>Por favor, recuerda esa historia largamente olvidada.</color>",
  ui_story_5088_50880100_2_dialog_content = "<color=#e8d9bb>La historia de un antiguo reino al borde del desastre, y la llegada de un grupo de héroes—</color>",
  ui_story_5088_50880100_3_dialog_content = "<color=#e8d9bb>Para salvar su reino de una presencia vil, se sometieron voluntariamente a peligrosas mejoras.</color>",
  ui_story_5088_50880100_4_dialog_content = "<color=#e8d9bb>Pero cuando la paz fue restaurada una vez más, los héroes fueron maldecidos y vilipendiados como monstruos, tanto en cuerpo como en mente.</color>",
  ui_story_5088_50880100_5_dialog_content = "<color=#e8d9bb>Enmarcados por los sacerdotes, abandonados por el rey y temidos por las masas ignorantes a las que juraron proteger.</color>",
  ui_story_5088_50880100_6_dialog_content = "<color=#e8d9bb>En su insondable desesperación, los héroes se buscaban mutuamente para encontrar calor y consuelo, pero no había forma de resistir la corrupción de su maldición.</color>",
  ui_story_5088_50880100_7_dialog_content = "<color=#e8d9bb>Para concederles una última oportunidad de felicidad, su líder y un querido amigo se sacrificaron.</color>",
  ui_story_5088_50880100_8_dialog_content = "<color=#e8d9bb>Sellados más allá del flujo del tiempo, esperaron en silencio—</color>",
  ui_story_5088_50880100_9_dialog_content = "Resoplan...",
  ui_story_5088_50880100_10_dialog_content = "¡Graaaaah!",
  ui_story_5088_50880100_11_dialog_content = "<color=#e8d9bb>Día Uno: Desciende una Gran Calamidad.</color>",
  ui_story_5088_50880100_12_dialog_content = "¡Esto es malo! Se están poniendo al día—",
  ui_story_5088_50880100_13_dialog_content = "¡No en mi reloj!",
  ui_story_5088_50880100_14_dialog_content = "Eres tú... El de la celebración de la capital real...",
  ui_story_5088_50880100_15_dialog_content = "¿Puedes caminar? Aquí, toma mi mano.",
  ui_story_5088_50880100_16_dialog_content = "... Ese héroe.",
  ui_story_5088_50880100_17_dialog_content = "No soy un héroe, puedes llamarme Adras.",
  ui_story_5088_50880100_18_dialog_content = "<color=#e8d9bb>Día dos: Héroes del destino.</color>",
  ui_story_5088_50880100_19_dialog_content = "¿Qué paso?",
  ui_story_5088_50880100_20_dialog_content = "Nada, solo estaba ayudando a este viajero.",
  ui_story_5088_50880100_21_dialog_content = "¿Estás bien?",
  ui_story_5088_50880100_22_dialog_content = "La ciudad está segura y no se han reportado bajas. Podemos descansar allí por ahora.",
  ui_story_5088_50880100_23_dialog_content = "<color=#e8d9bb>Día Tres: Alabando las Estrellas</color>",
  ui_story_5088_50880100_24_dialog_content = "Perdóname, pero...",
  ui_story_5088_50880100_25_dialog_content = "¡Oh! Aún no me he presentado.",
  ui_story_5088_50880100_26_dialog_content = "Mi nombre es—",
  ui_story_5088_50880100_27_dialog_content = "<color=#e8d9bb>Día Cuatro: Paz, Cambio y Tensión.</color>",
  ui_story_5088_50880100_28_dialog_content = "Aquiles... Mi cabeza da vueltas...",
  ui_story_5088_50880100_29_dialog_content = "Lo siento mucho, mi amigo... Pero tengo que mantenerte aquí...",
  ui_story_5088_50880100_30_dialog_content = "Guarda tus fuerzas. Te llevaré a un médico de inmediato.",
  ui_story_5088_50880100_31_dialog_content = "N-No, eso no será necesario. Estoy tan cansado... Y extraño tanto mi casa...",
  ui_story_5088_50880100_32_dialog_content = "Entonces déjame llevarte a casa.",
  ui_story_5088_50880100_33_dialog_content = "¡Ni un paso más, Claymore! ¿No fue suficiente para ti asesinar al Señor Lucius y rebelarte contra el Consejo de Ancianos?! ¡Ríndete, monstruo!",
  ui_story_5088_50880100_34_dialog_content = "... Hazte a un lado. No levantaré mi espada contra los inocentes.",
  ui_story_5088_50880100_35_dialog_content = "¡Entonces pagarás con la sangre que le debes al Sumo Sacerdote!",
  ui_story_5088_50880100_36_dialog_content = "<size=45>¡Dije hazte a un lado!</size>",
  ui_story_5088_50880100_37_dialog_content = "Urgh... No puedo mover mis piernas... ¿Qué es esto...?!",
  ui_story_5088_50880100_38_dialog_content = "¿Qué está pasando, Aquiles...? Ya no puedo ver el color de tu luz...",
  ui_story_5088_50880100_39_dialog_content = "No es nada, Ludweiss. Aquí, dame tu mano. Es hora de regresar.",
  ui_story_5088_50880100_40_dialog_content = "No, espera, ahora recuerdo... Nuestros amigos son mucho más importantes. Todavía están sellados, así que por favor llévatelos y vete...",
  ui_story_5088_50880100_41_dialog_content = "¡Estamos aquí, Señor Aquiles!",
  ui_story_5088_50880100_42_dialog_content = "¿Qué... Qué diablos pasó aquí...?",
  ui_story_5088_50880100_43_dialog_content = "Anthony... ¿Por qué insistes en entrometerte con monstruos como nosotros?",
  ui_story_5088_50880100_44_dialog_content = "No tengo idea de lo que estás hablando, Lord Aquiles. Todo lo que sé es que necesitas mi ayuda.",
  ui_story_5088_50880100_45_dialog_content = "... Cuídate bien de Adras y los demás.",
  ui_story_5088_50880100_46_dialog_content = "Crearé una apertura para escapar.",
  ui_story_5088_50880100_47_dialog_content = "Vamos, Ludweiss.",
  ui_story_5088_50880100_48_dialog_content = "¿Se acabó? ¿El Consejo de Ancianos ha terminado su revuelta? Me pregunto... ¿Los niños sufrirán por esto...?",
  ui_story_5088_50880100_49_dialog_content = "Todo terminará pronto, Ludweiss. Solo sigue hablándome.",
  ui_story_5088_50880100_50_dialog_content = "Cuéntame más sobre tu hogar. Recuerdo que una vez lo describiste como una especie de paraíso.",
  ui_story_5088_50880100_51_dialog_content = "No, mi gente nunca pisó ese lugar... Todos somos solo exiliados perdidos... Intentando desesperadamente regresar al paraíso de nuestros ancestros...",
  ui_story_5088_50880100_52_dialog_content = "En el pasado, solo podía recordar la belleza de Eraveil a través de los recuerdos de mis antepasados... Pero ahora... finalmente la encontré...",
  ui_story_5088_50880100_53_dialog_content = "La voz en mis sueños... Pertenece a un chico de Eraveil.",
  ui_story_5088_50880100_54_dialog_content = "Cómo deseo ver el lugar por mí mismo.",
  ui_story_5088_50880100_55_dialog_content = "Entonces iremos a Eraveil juntos. Tú, yo y el resto de nosotros.",
  ui_story_5088_50880100_56_dialog_content = "Lo siento mucho... Quería salvarte también, pero ahora es demasiado tarde...",
  ui_story_5088_50880100_57_dialog_content = "Tu luz ha sido devorada. No puedes seguir así...",
  ui_story_5088_50880100_58_dialog_content = "No te preocupes por mi causa.",
  ui_story_5088_50880100_59_dialog_content = "Juro que cumpliré tu profecía y te llevaré a ver la belleza de tu hogar en persona.",
  ui_story_5088_50880100_60_dialog_content = "Si así es como te sientes... Entonces estoy poniendo toda mi confianza en ti.",
  ui_story_5088_50880100_61_dialog_content = "Con solo el poder de la Estrella Caída restante, depende de ti hacer que ese milagro se haga realidad.",
  ui_story_5088_50880100_62_dialog_content = "Nunca pierdas tu fe en la esperanza, pues algún día te guiará fuera de esta oscuridad.",
  ui_story_5088_50880100_63_dialog_content = "Todo depende de ti ahora... Aquiles...",
  ui_story_5088_50880100_64_dialog_content = "...",
  ui_story_5088_50880100_65_dialog_content = "...",
  ui_story_5088_50880100_66_dialog_content = "<color=#e8d9bb>Y este es el final de esta historia condenada y trágica. Solo en el mundo, el héroe comienza su viaje interminable...</color>",
  ui_story_5088_50880100_67_dialog_content = "No, no este... Este tampoco es...",
  ui_story_5088_50880100_68_dialog_content = "Sé que tienes prisa, querida, pero por favor, sé un poco más cuidadosa al manejar la mercancía. Después de todo, son antigüedades.",
  ui_story_5088_50880100_69_dialog_content = "¿En serio? Porque recuerdo que usaste ese diario para forrar un cofre del tesoro antes de vendérmelo.",
  ui_story_5088_50880100_70_dialog_content = "Eso es solo porque ya era un artículo defectuoso. La escritura en él era básicamente incomprensible.",
  ui_story_5088_50880100_71_dialog_content = "Y aún así todavía tiene valor para ti, ¿no es así?",
  ui_story_5088_50880100_72_dialog_content = "Otro envío para ti, jefe.",
  ui_story_5088_50880100_73_dialog_content = "Excelente trabajo, Casta. Cualquier lugar servirá, gracias.",
  ui_story_5088_50880100_74_dialog_content = "...",
  ui_story_5088_50880100_75_dialog_content = "¿PlayerName? ¿Buscas algo?",
  ui_story_5088_50880100_76_dialog_content = "Es una larga historia... Verás, dejé que Sheol me convenciera para hurgar en antigüedades porque dijo que podría hacer una fortuna si tengo suerte.",
  ui_story_5088_50880100_77_dialog_content = "Pero cuando comencé a percibir algunos de ellos, me topé con un antiguo cuaderno dejado por uno de mis compatriotas.",
  ui_story_5088_50880100_78_dialog_content = "Estoy realmente interesado en aprender más sobre esto... Y aunque apenas es legible, quiero seguir buscando cosas como esta.",
  ui_story_5088_50880100_79_dialog_content = "Tengo que ayudarlos... Tengo que encontrar aún más recuerdos para mis amigos.",
  ui_story_5088_50880100_80_dialog_content = "¿Así que viniste a Lady Sheol en busca de ayuda?",
  ui_story_5088_50880100_81_dialog_content = "Sí lo hizo, pero el tiempo es dinero, así que por favor continúa buscando.",
  ui_story_5088_50880100_82_dialog_content = "Hay tantas cosas tiradas por aquí. ¿Estás seguro de que no solo le estás dificultando las cosas?",
  ui_story_5088_50880100_83_dialog_content = "Definitivamente puedo sentir algo similar proveniente de una de estas antigüedades... Pero simplemente hay demasiadas.",
  ui_story_5088_50880100_84_dialog_content = "*Tose* Vaya, solo mira todo este polvo... No es que no quiera ayudarte, querida. Estos artículos son simplemente demasiado viejos, y rastrear sus orígenes es casi imposible.",
  ui_story_5088_50880100_85_dialog_content = "Si no los hubiera traído para guardarlos a salvo, es probable que alguien más en Umbraton ya los hubiera roto.",
  ui_story_5088_50880100_86_dialog_content = "Entonces de nuevo, no soy un experto en estas cosas. Ah, si tan solo Vergil estuviera aquí para resolverlas.",
  ui_story_5088_50880100_87_dialog_content = "Aquí, déjame ayudar—Ahí tienes.",
  ui_story_5088_50880100_88_dialog_content = "Uh... ¿No estás simplemente agarrando cosas al azar?",
  ui_story_5088_50880100_89_dialog_content = "Cuando el trabajo duro no puede hacer el trabajo, tienes que confiar en tu suerte e intuición.",
  ui_story_5088_50880100_90_dialog_content = "Confía en mí.",
  ui_story_5088_50880100_91_dialog_content = "Es... Es un...",
  ui_story_5088_50880100_92_dialog_content = "¿Eh? Vaya, en realidad funcionó.",
  ui_story_5088_50880100_93_dialog_content = "No hay duda. ¡Esto es una Cresta de Estrella!",
  ui_story_5088_50880100_94_dialog_content = "¡Es exactamente lo que estaba buscando!",
  ui_story_5088_50880100_95_dialog_content = "Bueno escuchar.",
  ui_story_5088_50880100_96_dialog_content = "Ya que parece tener mucho valor para ti, te dejaré quedártelo sin costo alguno.",
  ui_story_5088_50880100_97_dialog_content = "No tengo uso para esto aquí, así que considéralo un regalo para mi cliente número uno.",
  ui_story_5088_50880100_98_dialog_content = "¡Muchas gracias, Señora Sheol!",
  ui_story_5088_50880100_99_dialog_content = "Tengo que irme ahora. ¡Nos vemos!",
  ui_story_5088_50880100_100_dialog_content = "Ya está oscuro afuera. Permíteme acompañarte de regreso.",
  ui_story_5088_50880100_101_dialog_content = "Ay—",
  ui_story_5088_50880100_102_dialog_content = "¡Ah! Lo siento, no quería... ¿Tweety?",
  ui_story_5088_50880100_103_dialog_content = "¡Hola! ¡Eres tú, Sr. Navegante!",
  ui_story_5088_50880100_104_dialog_content = "Lo siento por eso, tenía demasiada prisa hace un momento.",
  ui_story_5088_50880100_105_dialog_content = "¿Estás bien, señora?",
  ui_story_5088_50880100_106_dialog_content = "Oh bien, ninguna de las cartas se perdió.",
  ui_story_5088_50880100_107_dialog_content = "\"¿Señora\"?",
  ui_story_5088_50880100_108_dialog_content = "¡Permítanme presentarles a nuestra nueva Mensajera! ¡Es bastante talentosa, sabes!",
  ui_story_5088_50880100_109_dialog_content = "Encantado de conocerlos a todos. Mi nombre es Mithra, y he sido asignado a la señorita Tweety como su asistente.",
  ui_story_5088_50880100_110_dialog_content = "Esto se siente completamente fuera de lugar... Eres mucho más alto que ella.",
  ui_story_5088_50880100_111_dialog_content = "Jejeje ...",
  ui_story_5088_50880100_112_dialog_content = "¡Lo siento todos, pero realmente tengo que irme! Me aseguraré de disculparme contigo adecuadamente más tarde, Tweety!",
  ui_story_5088_50880100_113_dialog_content = "¡Nos vemos awound, señor Navegante!",
  ui_story_5088_50880100_114_dialog_content = "¿Estás seguro de que no hay nada más?",
  ui_story_5088_50880100_115_dialog_content = "¿Es esto todo lo que puedes recordar?",
  ui_story_5088_50880100_116_dialog_content = "Por una cierta razón, pasaste la mayor parte de tu tiempo viviendo en la ciudad donde estabas estacionado.",
  ui_story_5088_50880100_117_dialog_content = "Simplemente olvídalo. Recordar estas cosas no te hará ningún bien ahora.",
  ui_story_5088_50880100_118_dialog_content = "No me importa si duele. Tengo que recuperar mis recuerdos.",
  ui_story_5088_50880100_119_dialog_content = "Todavía puedo recordarla... Mi amor... Pero por alguna razón, no puedo recordar su rostro...",
  ui_story_5088_50880100_120_dialog_content = "Solo por ella juré proteger a los justos con mi espada.",
  ui_story_5088_50880100_121_dialog_content = "¡Así que por favor, al menos dime su nombre!",
  ui_story_5088_50880100_122_dialog_content = "¡Ta-daaa! ¿Qué tal? ¿Te sorprendió mi elegante entrada?",
  ui_story_5088_50880100_123_dialog_content = "¡Ey! ¡Ustedes empezaron sin mí!",
  ui_story_5088_50880100_124_dialog_content = "Es tu culpa por ser tan lento.",
  ui_story_5088_50880100_125_dialog_content = "No me perdí nada, ¿verdad?",
  ui_story_5088_50880100_126_dialog_content = "...",
  ui_story_5088_50880100_127_dialog_content = "Lo siento, pero yo tampoco recuerdo nada.",
  ui_story_5088_50880100_128_dialog_content = "Entiendo...",
  ui_story_5088_50880100_129_dialog_content = "¿Y qué hay de ese otro nombre? \"Claymore\"?",
  ui_story_5088_50880100_130_dialog_content = "¡¿?!",
  ui_story_5088_50880100_131_dialog_content = "¡Cómo te atreves a mencionar el nombre de esa persona otra vez!",
  ui_story_5088_50880100_132_dialog_content = "¡Oye, cálmate ya!",
  ui_story_5088_50880100_133_dialog_content = "¡Suéltame—! Acordamos nunca volver a mencionarlo!",
  ui_story_5088_50880100_134_dialog_content = "Tú desmembraste a esa persona tú mismo ese día.",
  ui_story_5088_50880100_135_dialog_content = "¿Es por esto que nos has reunido aquí hoy? ¿Para hacernos recordar el dolor otra vez?!",
  ui_story_5088_50880100_136_dialog_content = "Yo... odiaba a esa persona. De alguna manera lo hice, y no sé por qué...",
  ui_story_5088_50880100_137_dialog_content = "Pero cuando PlayerName me mostró, solo me convenció aún más... Esa persona...",
  ui_story_5088_50880100_138_dialog_content = "Su nombre era Aquiles, y él era nuestro líder.",
  ui_story_5088_50880100_139_dialog_content = "¿Sí? ¿Y qué?",
  ui_story_5088_50880100_140_dialog_content = "Era tu general y el líder de nuestro grupo.",
  ui_story_5088_50880100_141_dialog_content = "Pero él nos traicionó.",
  ui_story_5088_50880100_142_dialog_content = "La verdad es, todos estuvimos de acuerdo en ello, en dejarnos ser destruidos.",
  ui_story_5088_50880100_143_dialog_content = "Pero cuando su espada atravesó mi corazón, sentí... resentimiento.",
  ui_story_5088_50880100_144_dialog_content = "Estaba tan aliviado de poder sentir algo después de todo... Pero pronto me di cuenta... El dolor no desaparecía.",
  ui_story_5088_50880100_145_dialog_content = "El capitán fue una vez un gran héroe y un buen amigo para todos nosotros. Poner fin a su sufrimiento es lo menos que podemos hacer.",
  ui_story_5088_50880100_146_dialog_content = "Es cierto. Él era un héroe... Y le debía mi vida.",
  ui_story_5088_50880100_147_dialog_content = "Por eso... Sentí aún más odio cuando atacó de repente.",
  ui_story_5088_50880100_148_dialog_content = "No debería ser así... Sé que no debería odiarlo...",
  ui_story_5088_50880100_149_dialog_content = "¿Quizás nos estamos olvidando de algo importante?",
  ui_story_5088_50880100_150_dialog_content = "Por ejemplo... ¿Realmente éramos solo cinco en aquel entonces?",
  ui_story_5088_50880100_151_dialog_content = "Quiero recordarlo todo.",
  ui_story_5088_50880100_152_dialog_content = "¿Qué nos pasó en el pasado? ¿Y qué sucedió cuando finalmente despertamos?",
  ui_story_5088_50880100_153_dialog_content = "¿Qué exactamente hemos olvidado? ¿Recordaremos todo alguna vez?",
  ui_story_5088_50880100_154_dialog_content = "<size=30>La persona que no podemos recordar es la que registró todo sobre nosotros. Perdónanos... Nuestro amigo olvidado hace mucho tiempo.</size>",
  ui_story_5088_50880100_155_dialog_content = "Puedo sentir la presencia de Aurorians en lo profundo de esta cueva congelada... ¿Pero cómo? ¿Es por esto que la reina me pidió que investigara?",
  ui_story_5088_50880100_156_dialog_content = "¡Solo espera! Sacaré a ustedes de ahí...",
  ui_story_5088_50880100_157_dialog_content = "Todo está en su lugar ahora. El sello solo se romperá una vez que un Celestita decida liberarlos de este lugar.",
  ui_story_5088_50880100_158_dialog_content = "A cambio, me atrapará aquí y drenará lentamente mi fuerza. Pero incluso si me convierto en un Eclipsite, seguiré velando por ellos.",
  ui_story_5088_50880100_159_dialog_content = "¿Fue eso...?",
  ui_story_5088_50880100_160_dialog_content = "Capitán... ¿Por qué...",
  ui_story_5088_50880100_161_dialog_content = "¿Lo hice...?",
  ui_story_5088_50880100_162_dialog_content = "¿Eh? ¿Todavía estoy vivo?",
  ui_story_5088_50880100_163_dialog_content = "Oye... ¿Qué es esa luz que viene de ahí abajo? ¿El sello ya se ha activado?",
  ui_story_5088_50880100_164_dialog_content = "Esta formación... ¿Es este el lugar de antes? La cueva donde ese hombre...",
  ui_story_5088_50880100_165_dialog_content = "¿A... Un Celestita?",
  ui_story_5088_50880100_166_dialog_content = "Grah!!!",
  ui_story_5088_50880100_167_dialog_content = "¡Argh... Mi cabeza... ¿Qué está pasando? ¿Por qué de repente escucho tantas voces?!",
  ui_story_5088_50880100_168_dialog_content = "¡No—Vete! ¡Déjame en paz!",
  ui_story_5088_50880100_169_dialog_content = "A-¿Estás bien?",
  ui_story_5088_50880100_170_dialog_content = "¡Esa voz... sigue vivo!",
  ui_story_5088_50880100_171_dialog_content = "Claymore... ¡El defensor del reino va a destruirnos a todos!",
  ui_story_5088_50880100_172_dialog_content = "¡Oye! ¡Ahora no es el momento de pensar en eso!",
  ui_story_5088_50880100_173_dialog_content = "Este chico nos salvó, pero parece que está en muy mal estado.",
  ui_story_5088_50880100_174_dialog_content = "Salvar a las personas es lo primero, como siempre. Resolveremos el resto más tarde.",
  ui_story_5088_50880100_175_dialog_content = "... Entonces vamos.",
  ui_story_5088_50880100_176_dialog_content = "Él viene detrás de nosotros.",
  ui_story_5088_50880100_177_dialog_content = "¡Magia del bosque, ocúltanos de los ojos de nuestro perseguidor—¡Vamos!",
  ui_story_5088_50880100_178_dialog_content = "¡N-No hay escapatoria!",
  ui_story_5088_50880100_179_dialog_content = "<size=45>¡¡¡Muerte a todos los enemigos!!!</size>",
  ui_story_5088_50880100_180_dialog_content = "<color=#e8d9bb>Una oleada de poder crudo estalla, desgarrando las densas ramas mágicas.</color>",
  ui_story_5088_50880100_181_dialog_content = "Duele...",
  ui_story_5088_50880100_182_dialog_content = "Un Caelestite... Debo perdonarlo...",
  ui_story_5088_50880100_183_dialog_content = "<color=#e8d9bb>La energía de la espada masiva parte el suelo mientras se dirige hacia el grupo.</color>",
  ui_story_5088_50880100_184_dialog_content = "<color=#e8d9bb>Pero en el último segundo, el Eclipsite desvía su abrumador poder lejos de ellos.</color>",
  ui_story_5088_50880100_185_dialog_content = "<color=#e8d9bb>Silenciosamente, observa cómo su presa escapa.</color>",
  ui_story_5088_50880100_186_dialog_content = "<color=#FFB400>Ludweiss</color>... <color=#FFB400>Czerny</color>...",
  ui_story_5088_50880201_1_dialog_content = "(Este emblema es diferente a los que llevan Adras y los demás. Tiene una imagen única grabada en él.)",
  ui_story_5088_50880201_2_dialog_content = "¿Podría ser de Claymore...?",
  ui_story_5088_50880201_3_dialog_content = "(Definitivamente puedo sentir su poder proveniente de él.)",
  ui_story_5088_50880201_4_option_content = "Escaneo psíquico",
  ui_story_5088_50880201_5_dialog_content = "<color=#e8d9bb>Día cinco: Y el Traidor Dijo, \"Los Héroes Morirán\".</color>",
  ui_story_5088_50880201_6_dialog_content = "¡Fuera de mi camino!",
  ui_story_5088_50880201_7_dialog_content = "Crujir—Crujir—",
  ui_story_5088_50880201_8_dialog_content = "...Ya veo.",
  ui_story_5088_50880201_9_dialog_content = "Son Eclipsites ahora...",
  ui_story_5088_50880201_10_dialog_content = "Eran soldados valientes y leales, pero tú los convertiste en monstruos.",
  ui_story_5088_50880201_11_dialog_content = "Y ahora, solo otro monstruo como yo puede poner fin a su sufrimiento.",
  ui_story_5088_50880201_12_dialog_content = "No había otra opción.",
  ui_story_5088_50880201_13_dialog_content = "¿Todavía puedes llamarte \"rey\" ahora?",
  ui_story_5088_50880201_14_dialog_content = "¿O una persona, para el caso?",
  ui_story_5088_50880201_15_dialog_content = "<size=45>¡¡¡Gaius Agamemnon!!!</size>",
  ui_story_5088_50880201_16_dialog_content = "¡Baja de tu podrido trono y enfréntame!",
  ui_story_5088_50880202_1_dialog_content = "¿Qué... Qué demonios en el mundo...",
  ui_story_5088_50880202_2_dialog_content = "Señor Aquiles... ¿No me digas que tú también has perdido la cabeza?",
  ui_story_5088_50880202_3_dialog_content = "...",
  ui_story_5088_50880202_4_dialog_content = "Más allá de nosotros se encuentra el rey. No podemos permitirte pasar.",
  ui_story_5088_50880202_5_dialog_content = "Si alguno de ustedes todavía me ve como Aquiles, entonces por favor, hazte a un lado.",
  ui_story_5088_50880202_6_dialog_content = "Tengo algo que decirle a ese hombre.",
  ui_story_5088_50880202_7_dialog_content = "Pero...",
  ui_story_5088_50880202_8_dialog_content = "Déjalo pasar.",
  ui_story_5088_50880202_9_dialog_content = "No podrías detenerlo aunque lo intentaras. No hay necesidad de sacrificarse tan inútilmente.",
  ui_story_5088_50880202_10_dialog_content = "¡Muy bien, Su Majestad!",
  ui_story_5088_50880202_11_dialog_content = "Por aquí, Señor Aquiles...",
  ui_story_5088_50880202_12_dialog_content = "... Ninguno de mis camaradas perdió nunca la cabeza. Recuerda eso.",
  ui_story_5088_50880202_13_dialog_content = "Has sufrido tanto solo para sobrevivir hasta ahora, Aquiles. ¿Por qué no dejar que las cosas terminen como deberían?",
  ui_story_5088_50880202_14_dialog_content = "Mis camaradas y yo... no nos importa convertirnos en mártires.",
  ui_story_5088_50880202_15_dialog_content = "Pero sé que merecen un final mucho mejor, y estoy dispuesto a dar mi vida para dárselo.",
  ui_story_5088_50880202_16_dialog_content = "Pero desde el momento en que tus guardias desenfundaron sus espadas contra mí... Me di cuenta de que nunca tuviste la intención de dejarnos vivir.",
  ui_story_5088_50880202_17_dialog_content = "Mi lealtad hacia ti termina hoy.",
  ui_story_5088_50880202_18_dialog_content = "¿Qué te hace decir eso? ¿Podría ser... por la Celestita muerta que llevas en tu espalda?",
  ui_story_5088_50880202_19_dialog_content = "Bueno, puedes quedarte con ella. Además, sabía que este día llegaría eventualmente.",
  ui_story_5088_50880202_20_dialog_content = "Tú y tus camaradas no me deben nada. Si acaso, estoy en deuda contigo.",
  ui_story_5088_50880202_21_dialog_content = "Pero todos sabemos perfectamente bien que tenía razón al hacer las cosas que he hecho.",
  ui_story_5088_50880202_22_dialog_content = "Busco tu erradicación no por deseo personal, sino por el bien de la paz duramente ganada que nuestro reino disfruta ahora.",
  ui_story_5088_50880202_23_dialog_content = "Tú... ¿Cómo puedes decir eso?!",
  ui_story_5088_50880202_24_dialog_content = "Sacrifiqué todo lo que me era querido, y nuestro reino ahora está en paz por ello.",
  ui_story_5088_50880202_25_dialog_content = "Siempre recordaré cada gota de sangre que tú y tus camaradas derramaron por nuestra nación.",
  ui_story_5088_50880202_26_dialog_content = "El Consejo de Ancianos fue forzado a la rebelión, ¡y las llamas de la guerra aún ardían en todo el reino! ¿Es esto a lo que llamas \"paz\"?!",
  ui_story_5088_50880202_27_dialog_content = "Las llamas están bajo mi control. Sé exactamente lo que deben quemar.",
  ui_story_5088_50880202_28_dialog_content = "¡...!",
  ui_story_5088_50880202_29_dialog_content = "¿Quién era tu espía dentro del Consejo de Ancianos?",
  ui_story_5088_50880202_30_dialog_content = "¿Y a quién has enviado para destruirlos?",
  ui_story_5088_50880202_31_dialog_content = "¿¡Por qué me dejaron a oscuras todo este tiempo!?",
  ui_story_5088_50880202_32_dialog_content = "Aquiles, cuando juraste defender la justicia a cualquier costo...",
  ui_story_5088_50880202_33_dialog_content = "Sabía que tenía que distanciarme de ti.",
  ui_story_5088_50880202_34_dialog_content = "Pero aún hay tantas personas en el Consejo de Ancianos que son leales al reino... ¿Cómo podrías tú...",
  ui_story_5088_50880202_35_dialog_content = "Piensa, Aquiles.",
  ui_story_5088_50880202_36_dialog_content = "El norte fue una vez un lugar caótico y azotado por la guerra, pero tú y yo hemos sentado las bases para la paz.",
  ui_story_5088_50880202_37_dialog_content = "Nadie en el Consejo de Ancianos valora la paz, por eso eligieron sembrar animosidad entre nosotros.",
  ui_story_5088_50880202_38_dialog_content = "Cuando mi familia cayó bajo sospecha, ese tirano los desterró a las regiones más frías de la tierra y los dejó morir.",
  ui_story_5088_50880202_39_dialog_content = "El Consejo de Ancianos fue testigo de la destrucción de mi familia, y no hizo nada para ayudarme cuando fui tomado prisionero.",
  ui_story_5088_50880202_40_dialog_content = "He aceptado todo lo que me ha sucedido.",
  ui_story_5088_50880202_41_dialog_content = "Así que decidiste exterminar a toda la familia del antiguo rey.",
  ui_story_5088_50880202_42_dialog_content = "En ese momento... Llegué demasiado tarde para detenerte.",
  ui_story_5088_50880202_43_dialog_content = "Pero incluso entonces, no me di cuenta de que tu odio también se extendía hacia el Consejo de Ancianos...",
  ui_story_5088_50880202_44_dialog_content = "Estás equivocado. Dejé mi rencor hace mucho tiempo, por eso pudimos unir los estados de la ciudad en guerra de Northland en una verdadera nación.",
  ui_story_5088_50880202_45_dialog_content = "¿Qué ha hecho el Consejo de Ancianos para merecer su destino?",
  ui_story_5088_50880202_46_dialog_content = "Me temen, Aquiles. Desean detener mi revolución volviendo a nuestro pueblo contra mí, incluyendo a los sacerdotes.",
  ui_story_5088_50880202_47_dialog_content = "También te han perjudicado para ganar tu favor y tu fuerza militar, ¿no es así?",
  ui_story_5088_50880202_48_dialog_content = "Eso no es de mi preocupación.",
  ui_story_5088_50880202_49_dialog_content = "Hubo un tiempo en que creí que cualquiera de nosotros podría ser rey. Pero siempre has sido demasiado recto para el trono.",
  ui_story_5088_50880202_50_dialog_content = "Alguien como tú nunca podría purgar la corrupción de nuestro reino y traer paz a su gente.",
  ui_story_5088_50880202_51_dialog_content = "Si tan solo hubieras nacido en una era de paz. Tan poderoso e imparcial como eres, podrías haber sido el mariscal más grande en la historia de nuestro reino.",
  ui_story_5088_50880202_52_dialog_content = "Pero ahora mismo, no hay nada que puedas hacer para ayudarme. Apenas eres el mariscal que Northland necesita en este momento.",
  ui_story_5088_50880202_53_dialog_content = "Por eso nunca puedes ser más que un general... O un monstruo a cargo de otros monstruos.",
  ui_story_5088_50880202_54_dialog_content = "Basta de tus parloteos sin sentido, Agamenón! Libera a mis camaradas y detén toda esta matanza sin sentido.",
  ui_story_5088_50880202_55_dialog_content = "¿Y si me niego?",
  ui_story_5088_50880202_56_dialog_content = "La fuente de la amenaza Eclipsite ha sido erradicada, el Consejo de Ancianos está al borde del colapso y el templo ha perdido a su Sumo Sacerdote.",
  ui_story_5088_50880202_57_dialog_content = "Como el indiscutible vencedor, ¿por qué insistes en continuar tu racha asesina?",
  ui_story_5088_50880202_58_dialog_content = "Ahora que has eliminado a dos de los tres cuerpos gobernantes de nuestro reino, podrías convertirte en el emperador de todo Northland.",
  ui_story_5088_50880202_59_dialog_content = "Tú y tus compatriotas son demasiado poderosos para dejarlos vivos. Vuestras mismas existencias representan un gran riesgo para la paz que tanto deseo.",
  ui_story_5088_50880202_60_dialog_content = "Y el hecho sigue siendo que todos ustedes son impotentes para suprimir la corrupción en sus cuerpos.",
  ui_story_5088_50880202_61_dialog_content = "Como mínimo... Debes perdonar a los niños y dejar que mis camaradas abandonen el reino... Para que puedan llevar a nuestra querida amiga de regreso a su lejana patria y darle descanso.",
  ui_story_5088_50880202_62_dialog_content = "Me quedaré aquí y pagaré cualquier precio que me pidas.",
  ui_story_5088_50880202_63_dialog_content = "Nunca pensé que hablarías en nombre del Consejo de Ancianos al final. ¿Estás haciendo esto por justicia? ¿O quizás por lealtad a tu propia gente?",
  ui_story_5088_50880202_64_dialog_content = "Estoy haciendo esto como una persona, Agamenón.",
  ui_story_5088_50880202_65_dialog_content = "... Los otros Guerreros Estelares han caído en la locura. Tú, Aquiles, eres el único cuya voluntad no ha flaqueado.",
  ui_story_5088_50880202_66_dialog_content = "No es de extrañar que esa tonta Caelestite diera su vida para—",
  ui_story_5088_50880202_67_dialog_content = "<color=#e8d9bb>La presión de un poderoso corte lo interrumpe a mitad de la frase.</color>",
  ui_story_5088_50880202_68_dialog_content = "¡Ni una palabra más!",
  ui_story_5088_50880202_69_dialog_content = "¡No permitiré que insultes a mi amigo por más tiempo!",
  ui_story_5088_50880202_70_dialog_content = "... \"Amigo,\" ¿dices tú?",
  ui_story_5088_50880202_71_dialog_content = "¿No era también tu amigo, Aquiles?",
  ui_story_5088_50880202_72_dialog_content = "Durante nuestros días militares, tú eras mi aliado más confiable, tan confiable como mi propio brazo armado. Todavía recuerdo las innumerables veces que salvaste mi vida.",
  ui_story_5088_50880202_73_dialog_content = "Pero el momento más memorable... fue cuando dejé caer mi escudo en la batalla, y tú me protegiste con tu cuerpo. Recuerdo las diecisiete heridas que sufriste ese día.",
  ui_story_5088_50880202_74_dialog_content = "... Y por mi culpa, rompiste filas y derribaste a los lanceros que se acercaban a mí, todo sin tu escudo.",
  ui_story_5088_50880202_75_dialog_content = "Tus heridas eran tan graves como las mías, y te pusieron en grilletes por violar las órdenes. Tu propia hermana murió en prisión por eso también.",
  ui_story_5088_50880202_76_dialog_content = "Aliados...",
  ui_story_5088_50880202_77_dialog_content = "Sé que nunca podrías matarme, Aquiles, porque no hay una persona mejor viva que pueda tomar mi lugar.",
  ui_story_5088_50880202_78_dialog_content = "Ninguno de nosotros quiere sumergir nuestro reino en el caos una vez más.",
  ui_story_5088_50880202_79_dialog_content = "...",
  ui_story_5088_50880202_80_dialog_content = "Ahora vete.",
  ui_story_5088_50880202_81_dialog_content = "¡¿?!",
  ui_story_5088_50880202_82_dialog_content = "No hace ninguna diferencia si dejo ir a uno de ustedes o a todos ustedes.",
  ui_story_5088_50880202_83_dialog_content = "Llévatelos a todos contigo. Tus compañeros de equipo, los guerreros que juran lealtad a ti, los niños del Consejo de Ancianos y tu amigo Celestita...",
  ui_story_5088_50880202_84_dialog_content = "Llévalos a un lugar lejano y nunca vuelvas a pisar nuestras tierras puras e inmaculadas nunca más.",
  ui_story_5088_50880202_85_dialog_content = "Eliminaré cualquier mención de ti y tus camaradas de los anales de nuestra historia. Nadie cantará tus alabanzas ni buscará el poder que posees nunca más.",
  ui_story_5088_50880202_86_dialog_content = "Aseguraré que el arte de crear soldados Eclipsites se pierda con el paso del tiempo.",
  ui_story_5088_50880202_87_dialog_content = "Mírame a los ojos, Gaius Agamemnon, y dime que no estás haciendo esto por beneficio personal, sino por el bien de nuestros ideales.",
  ui_story_5088_50880202_88_dialog_content = "Sí. Incluso mientras desciendo a un río de pecado imperdonable... Siempre anhelaré la paz. Esto será especialmente cierto una vez que tome el trono y mire el caos como rey.",
  ui_story_5088_50880202_89_dialog_content = "Y así, llevaré la inmundicia que tú nunca podrías aceptar. Mientras Northland no esté plagado ni de guerra ni de quienes la buscan, juro solemnemente—",
  ui_story_5088_50880202_90_dialog_content = "Ningún chico tendrá que mendigar pan para sobrevivir. Ninguna santa tendrá que quemarse nunca más. Ningún niño se perderá nunca más en el bosque...",
  ui_story_5088_50880202_91_dialog_content = "Ninguna mujer será temida por sus llamas. Ningún niño nacerá y será dejado en un orfanato. Nadie tendrá que pasar toda su vida en lágrimas...",
  ui_story_5088_50880202_92_dialog_content = "Y ninguna persona recta tendrá que sentir el dolor de la traición nunca más.",
  ui_story_5088_50880202_93_dialog_content = "Devoraré cada rastro de suciedad hasta que todo Northland sea tan puro e inmaculado como la nieve que lo cubre.",
  ui_story_5088_50880202_94_dialog_content = "Por esto, pagaré cualquier precio.",
  ui_story_5088_50880202_95_dialog_content = "Dime, ¿cómo se siente sentarse solo en un trono podrido?",
  ui_story_5088_50880202_96_dialog_content = "...",
  ui_story_5088_50880202_97_dialog_content = "...",
  ui_story_5088_50880202_98_dialog_content = "Adiós, Gaius Agamemnon.",
  ui_story_5088_50880202_99_dialog_content = "Adiós, amigo mío.",
  ui_story_5088_50880202_100_dialog_content = "May todos ustedes encuentren la paz un día.",
  ui_story_5088_50880202_101_dialog_content = "... Es frío.",
  ui_story_5088_50880202_102_dialog_content = "Este trono es más frío de lo que podrías imaginar, mi amigo.",
  ui_story_5088_50880202_103_dialog_content = "<color=#e8d9bb>Día Seis: Los Cazadores—Un Cuento Perdido en el Tiempo.</color>",
  ui_story_5088_50880202_104_dialog_content = "La verdad a men. está ente. bajo las arenas del tiempo.",
  ui_story_5088_50880202_105_dialog_content = "¿Qué más puedo hacer? Incluso si grabo todo... ¿Alguien sabrá alg. vez la verdad?",
  ui_story_5088_50880202_106_dialog_content = "He fallado. No puedo hacer nada para salvarte.",
  ui_story_5088_50880202_107_dialog_content = "Pero también lo he logrado. Nadie en el reino volverá a mencionar sus nombres.",
  ui_story_5088_50880202_108_dialog_content = "Serás olvidado. Sin importar el logro o la deshonra, serás olvidado.",
  ui_story_5088_50880202_109_dialog_content = "Todos ust. son est. que se desvanecen. Una vez que tu luz se apague, nadie te recordará.",
  ui_story_5088_50880202_110_dialog_content = "Y aún sigues escribiendo en tu diario, Lord Aquiles.",
  ui_story_5088_50880202_111_dialog_content = "Incluso si destruimos cada registro de su existencia, nunca puedes olvidarte de ellos.",
  ui_story_5088_50880202_112_dialog_content = "Es porque Freya una vez dijo que no quería que nos olvidaran.",
  ui_story_5088_50880202_113_dialog_content = "El resto del mundo puede olvidarse de nosotros, ya que esa calamidad nunca volverá a aparecer en este mundo.",
  ui_story_5088_50880202_114_dialog_content = "Pero no puedo... No puedo olvidarme de ellos...",
  ui_story_5088_50880202_115_dialog_content = "Las palabras que estoy escribiendo son solo para mí.",
  ui_story_5088_50880202_116_dialog_content = "... ¿Y estás seguro de que este sello es lo suficientemente resistente para resistir la prueba del tiempo?",
  ui_story_5088_50880202_117_dialog_content = "Todo está en su lugar ahora. El sello solo se romperá una vez que un Celestita decida liberarlos de este lugar.",
  ui_story_5088_50880202_118_dialog_content = "Las estrellas están en paz ahora, y los niños han sido escoltados de manera segura fuera de Northland por los demás...",
  ui_story_5088_50880202_119_dialog_content = "Solo hay una última cosa que puedo hacer por ti, Señor Aquiles, y ahora es el momento de hacerlo.",
  ui_story_5088_50880202_120_dialog_content = "¿Qué sería eso?",
  ui_story_5088_50880202_121_dialog_content = "Soy el único mortal en este mundo que sabe sobre este lugar, y tengo que asegurarme de que su existencia permanezca en secreto para siempre.",
  ui_story_5088_50880202_122_dialog_content = "Te debo mi vida, mi señor, ¡y ahora es el momento de pagarte con ella!",
  ui_story_5088_50880202_123_dialog_content = "¿Señor Aquiles? ¿Por qué me detuviste?",
  ui_story_5088_50880202_124_dialog_content = "Eso es suficiente, Anthony. Ya me has dado tu lealtad y amistad. No hay necesidad de darme tu vida.",
  ui_story_5088_50880202_125_dialog_content = "Pero...",
  ui_story_5088_50880202_126_dialog_content = "Esta formación tiene dos propósitos: mantener el sello en mis camaradas y evitar que les haga daño una vez que pierda la cordura.",
  ui_story_5088_50880202_127_dialog_content = "A cambio, me atrapará aquí y drenará lentamente mi fuerza. Pero incluso si me convierto en un Eclipsite, seguiré velando por ellos.",
  ui_story_5088_50880202_128_dialog_content = "No tengo forma de salir de este lugar, Anthony.",
  ui_story_5088_50880202_129_dialog_content = "Por favor, encuentra a Eraveil en mi lugar y ayúdame a poner a Ludweiss a descansar en su tierra natal.",
  ui_story_5088_50880202_130_dialog_content = "Esta fue la promesa que le hice a ella.",
  ui_story_5088_50880202_131_dialog_content = "Ludweiss una vez me dijo que Eraveil aún no estaba abierto al mundo exterior. Puede que te lleve años encontrarlo.",
  ui_story_5088_50880202_132_dialog_content = "Pero hasta entonces, no tienes permiso para morir.",
  ui_story_5088_50880202_133_dialog_content = "Señor Aquiles... Sabías que intentaría quitarme la vida para mantener este lugar en secreto, ¿verdad?",
  ui_story_5088_50880202_134_dialog_content = "...",
  ui_story_5088_50880202_135_dialog_content = "Así que decidiste usar esto como una excusa para impedirme hacerlo.",
  ui_story_5088_50880202_136_dialog_content = "Has dado cada onza de bondad en tu cuerpo a todos menos a ti mismo. No es justo, mi señor.",
  ui_story_5088_50880202_137_dialog_content = "Pero si esta es tu voluntad... Entonces, yo, Anthony Longinus, por la presente te juro:",
  ui_story_5088_50880202_138_dialog_content = "La familia Longinus buscará a Eraveil, así como los medios para salvarte a ti y a tus camaradas. Incluso si nuestra búsqueda se extiende a través de generaciones, no nos detendremos hasta que tengamos éxito.",
  ui_story_5088_50880202_139_dialog_content = "Anthony...",
  ui_story_5088_50880202_140_dialog_content = "A partir de este día, mis descendientes y yo guardaremos tu secreto.",
  ui_story_5088_50880202_141_dialog_content = "Y si no puedo estar contigo al final de tu vigilia eterna, Señor Aquiles...",
  ui_story_5088_50880202_142_dialog_content = "La familia Longinus permanecerá a tu lado a lo largo de los siglos.",
  ui_story_5088_50880202_143_dialog_content = "No hay necesidad de eso.",
  ui_story_5088_50880202_144_dialog_content = "El mundo puede olvidar las estrellas, pero siempre persistiremos en nuestra búsqueda para salvarte. Si tenemos que hacerlo en total oscuridad, que así sea.",
  ui_story_5088_50880202_145_dialog_content = "Tú y los demás lo merecen.",
  ui_story_5088_50880202_146_dialog_content = "...",
  ui_story_5088_50880202_147_dialog_content = "<color=#e8d9bb>Poco después de que Anthony se va, Claymore usa un conjunto simple de herramientas para tallar una serie de nuevos emblemas.</color>",
  ui_story_5088_50880202_148_dialog_content = "<color=#e8d9bb>Después de tallar cuidadosamente la imagen de un pergamino en uno de ellos, lo coloca con cuidado dentro de su cuaderno.</color>",
  ui_story_5088_50880202_149_dialog_content = "Ludweiss, esperemos juntos el deshielo de la nieve y la llegada de la primavera.",
  ui_story_5088_50880301_1_dialog_content = "Entonces este emblema fue hecho para la Srta. Ludweiss...",
  ui_story_5088_50880301_2_dialog_content = "Y al igual que en el sueño de Adras, Claymore, o mejor dicho Aquiles, solía ser una persona amable y recta.",
  ui_story_5088_50880301_3_dialog_content = "Pero el Claymore que acabamos de ver era un ser tan violento. ¿Qué podría haber sucedido entre aquel entonces y ahora?",
  ui_story_5088_50880301_4_dialog_content = "(No solo eso... Adras y sus camaradas fueron quienes mataron a su capitán con sus propias manos.)",
  ui_story_5088_50880301_5_dialog_content = "¿Estás bien?",
  ui_story_5088_50880301_6_dialog_content = "Desde aquel día, tienes una mirada tan preocupada en tu rostro.",
  ui_story_5088_50880301_7_dialog_content = "¿Algo sobre mi sueño te está molestando?",
  ui_story_5088_50880301_8_dialog_content = "Si es así, siempre es buena idea contarle a otras personas al respecto. No guardes todo adentro, ¿de acuerdo?",
  ui_story_5088_50880301_9_dialog_content = "¿Todavía recuerdan cuando volvimos a esa cueva congelada?",
  ui_story_5088_50880301_10_dialog_content = "Todos ustedes estaban tan familiarizados con ese lugar...",
  ui_story_5088_50880301_11_dialog_content = "Eso es porque fuimos allí en una misión hace mucho, mucho tiempo.",
  ui_story_5088_50880301_12_dialog_content = "No podemos recordar ningún detalle específico, aunque. Podría ser un efecto secundario de haber estado sellados durante tanto tiempo...",
  ui_story_5088_50880301_13_dialog_content = "Pero lo que sí recuerdo es que había algo claramente mal con ese hombre durante nuestra misión...",
  ui_story_5088_50880301_14_dialog_content = "Ugh... No sirve, no puedo recordar nada más... Pero muchos años después, ahí fue donde nos encontraste...",
  ui_story_5088_50880301_15_dialog_content = "Demuestra que nos traicionó.",
  ui_story_5088_50880301_16_dialog_content = "Pero cuando nos despertamos, el lugar era totalmente diferente a cuando entramos por primera vez.",
  ui_story_5088_50880301_17_dialog_content = "Supongo que dos mil años realmente pueden cambiar un lugar, ¿verdad?",
  ui_story_5088_50880301_18_dialog_content = "Yo... Yo solo fui a esa cueva bajo la guía de Queen Bethlehem.",
  ui_story_5088_50880301_19_dialog_content = "Hace un tiempo, rescaté a un auroriano que había sido congelado en el hielo. Desde el principio, pensé...",
  ui_story_5088_50880301_20_dialog_content = "Bethlehem...?",
  ui_story_5088_50880301_21_dialog_content = "... ¿Ah?",
  ui_story_5088_50880301_22_dialog_content = "(Estoy completamente sin pistas. ¿Qué debería hacer ahora?)",
  ui_story_5088_50880301_23_dialog_content = "(Si combino todo lo que acabo de ver con lo que vi en el sueño, demuestra que Claymore fue quien selló a todos en la arena antes de llevarlos a la cueva congelada.)",
  ui_story_5088_50880301_24_dialog_content = "(Pero cuando finalmente despertaron, sus recuerdos estaban en total desorden, y terminaron matando a Claymore sin siquiera darse cuenta...)",
  ui_story_5088_50880301_25_dialog_content = "(Si esto es realmente la verdad... Es casi demasiado doloroso para soportar...)",
  ui_story_5088_50880301_26_dialog_content = "Lo siento, pero hay un lugar al que quiero ir.",
  ui_story_5088_50880301_27_dialog_content = "¿No te lo he dicho ya suficientes veces, querido? Es imposible para mí conocer la historia completa de cada uno de estos objetos.",
  ui_story_5088_50880301_28_dialog_content = "Por no mencionar que muchas de estas cosas son ganancias mal habidas de los primeros días del Istvan mayor.",
  ui_story_5088_50880301_29_dialog_content = "En aquel entonces, Umbraton era un pozo negro de crimen y caos. Prácticamente todo en la ciudad provenía de orígenes dudosos en el mejor de los casos.",
  ui_story_5088_50880301_30_dialog_content = "Yo era el único dispuesto a salvaguardar estos objetos también.",
  ui_story_5088_50880301_31_dialog_content = "Pero esto es realmente importante para mí...",
  ui_story_5088_50880301_32_dialog_content = "¡Oh, no frunzas el ceño así, querida! Me parte el corazón verte tan decaída. ¡Ah, si tan solo Vergil estuviera aquí para solucionar las cosas.",
  ui_story_5088_50880301_33_dialog_content = "¿Qué tal esto?",
  ui_story_5088_50880301_34_dialog_content = "Se está haciendo tarde, así que ¿por qué no te vendo todos los pergaminos y notas manuscritas que hay aquí de una vez?",
  ui_story_5088_50880301_35_dialog_content = "De esa manera, puedes llevártelo todo a casa e investigarlo a tu propio ritmo. ¡Incluso incluiré un descuento familiar, solo para ti! ¿Entonces qué dices?",
  ui_story_5088_50880301_36_dialog_content = "E-Está bien entonces...",
  ui_story_5088_50880301_37_dialog_content = "Oye Caelestite... ¿Estás seguro de que quieres pasear por Umbraton solo tan tarde en la noche?",
  ui_story_5088_50880301_38_dialog_content = "Oye, ¿ves eso? El Caelestite acaba de comprar un montón de cosas del Gremio de Explorador Nublar.",
  ui_story_5088_50880301_39_dialog_content = "No lo sé. Robar al último Caelestita podría tener algunas consecuencias bastante graves. ¿Tienes alguna idea de lo aterradores que pueden ser los Lovegators?",
  ui_story_5088_50880301_40_dialog_content = "¡Vamos, es la mitad de la noche! Solo tenemos que maltratarlo un poco y huir con las mercancías antes de que alguien se dé cuenta!",
  ui_story_5088_50880301_41_dialog_content = "Podríamos abandonar la ciudad e ir a un lugar lejano, un lugar donde incluso el Señor de las Sombras no podría encontrarnos.",
  ui_story_5088_50880301_42_dialog_content = "¡Solo mira el tamaño de ese caso! ¡Una vez que hagamos nuestra escapada, podemos vivir como reyes por el resto de nuestras vidas!",
  ui_story_5088_50880301_43_dialog_content = "... Bien, pero esperemos hasta que se aleje un poco más de Umbraton. Ese es el momento en que haremos nuestro movimiento.",
  ui_story_5088_50880301_44_dialog_content = "¡¿Quién está ahí?!",
  ui_story_5088_50880301_45_dialog_content = "¿Oh? Supongo que es cierto que los Caelestitas pueden percibirnos.",
  ui_story_5088_50880301_46_dialog_content = "Si ese es el caso, ¡tendremos que hacer nuestro movimiento ahora!",
  ui_story_5088_50880301_47_dialog_content = "¡E-Espera un minuto! ¡No quieres nada de esto! ¡Son solo un montón de escritos y pergaminos antiguos!",
  ui_story_5088_50880301_48_dialog_content = "¿Escuchas eso? ¡Me suena a un tesoro histórico!",
  ui_story_5088_50880301_49_dialog_content = "(¡No me están escuchando en absoluto!)",
  ui_story_5088_50880301_50_dialog_content = "Pónganse en marcha, idiotas.",
  ui_story_5088_50880301_51_dialog_content = "¿Ah?",
  ui_story_5088_50880301_52_dialog_content = "¡E-Es ella! ¡La Cazadora del Cuervo!",
  ui_story_5088_50880301_53_dialog_content = "¡¿Qué está haciendo ella aquí?!",
  ui_story_5088_50880301_54_dialog_content = "¡Bien, desvergonzados de la vida baja... Es hora de enfrentar su castigo!",
  ui_story_5088_50880302_1_dialog_content = "Uh... Gracias.",
  ui_story_5088_50880302_2_dialog_content = "¡Idiota!",
  ui_story_5088_50880302_3_dialog_content = "¿Ah?",
  ui_story_5088_50880302_4_dialog_content = "Sabes muy bien que eres un Celestita, entonces ¿por qué insistes en andar completamente desprotegido?",
  ui_story_5088_50880302_5_dialog_content = "Incluso si te llevas bien con el Señor de las Sombras y su pandilla, eso no es excusa para subestimar los peligros de Umbraton.",
  ui_story_5088_50880302_6_dialog_content = "No dejes que te pille caminando solo por estas calles nunca más.",
  ui_story_5088_50880302_7_dialog_content = "Increíble. De hecho, te han asaltado.",
  ui_story_5088_50880302_8_dialog_content = "Todo Umbraton está revuelto ahora mismo por ti.",
  ui_story_5088_50880302_9_dialog_content = "Cuando vi que estabas perfectamente bien, pensé que había habido algún error.",
  ui_story_5088_50880302_10_dialog_content = "¿Ah?",
  ui_story_5088_50880302_11_dialog_content = "El Señor de las Sombras y su gente estaban furiosos cuando se enteraron, así que persiguieron a los tipos que intentaron robarte.",
  ui_story_5088_50880302_12_dialog_content = "Pero como estás bien, supongo que fue una buena oportunidad para sacar un poco más de basura de aquí.",
  ui_story_5088_50880302_13_dialog_content = "Aquí, un símbolo de simpatía de Lady Sheol. Insistió mucho en que te lo diera.",
  ui_story_5088_50880302_14_dialog_content = "Gracias... Pero realmente, estoy bien. Alguien vino a rescatarme justo a tiempo.",
  ui_story_5088_50880302_15_dialog_content = "Escuché. Los malhechores que te asaltaron nos dijeron que el Cazador Raven fue quien te salvó.",
  ui_story_5088_50880302_16_dialog_content = "Sí, así es como también la llamaban... El Cazador del Cuervo...",
  ui_story_5088_50880302_17_dialog_content = "Comenzó a aparecer hace unos dos años. De vez en cuando, caza a los criminales en plena noche y los castiga.",
  ui_story_5088_50880302_18_dialog_content = "¿Un vigilante de Umbraton que solo aparece por la noche? Suena mucho a Pittman de aquellos tiempos.",
  ui_story_5088_50880302_19_dialog_content = "Ten cuidado con lo que dices. Los métodos de esa persona son mucho más brutales.",
  ui_story_5088_50880302_20_dialog_content = "Ambos somos cuervos, pero una cosa que no tenemos en común es que ella no deja cabos sueltos.",
  ui_story_5088_50880302_21_dialog_content = "Independientemente de sus crímenes, ella los golpea a todos hasta dejarlos a un paso de la muerte.",
  ui_story_5088_50880302_22_dialog_content = "Mucha gente sospecha que ella podría ser una Justicia Knight pícaro o algo así.",
  ui_story_5088_50880302_23_dialog_content = "Paquete para ti, Sr. Navegante! Por favor firma aquí.",
  ui_story_5088_50880302_24_dialog_content = "Gracias.",
  ui_story_5088_50880302_25_dialog_content = "¿Compraste aún más de estas cosas?",
  ui_story_5088_50880302_26_dialog_content = "¿No estás simplemente tratando de buscar una aguja en un pajar en este punto?",
  ui_story_5088_50880302_27_dialog_content = "Yo sé... Pero esto es todo lo que puedo hacer ahora... Además, buscar en la historia conocimientos perdidos siempre será un desafío.",
  ui_story_5088_50880302_28_dialog_content = "...",
  ui_story_5088_50880302_29_dialog_content = "(¿Eh?)",
  ui_story_5088_50880302_30_dialog_content = "Entonces Tweety, ¿también tienes entregas que hacer aquí?",
  ui_story_5088_50880302_31_dialog_content = "Tal mala memowia, Sr. Navegante. ¡Es casi Windelion, sabes!",
  ui_story_5088_50880302_32_dialog_content = "¡Vine a confirmar el correo de Ewaveil!",
  ui_story_5088_50880302_33_dialog_content = "¡Oye, tienes razón! ¡Me olvidé completamente de eso!",
  ui_story_5088_50880302_34_dialog_content = "Vice y Carleen deberían volver antes de Windelion. Estoy seguro de que a Vice le encantará...",
  ui_story_5088_50880302_35_dialog_content = "Ahora que he entregado el regalo de Lady Sheol y confirmado su seguridad, me despido.",
  ui_story_5088_50880302_36_dialog_content = "¡También deberíamos irnos! ¡Hasta awound, señor Navegante!",
  ui_story_5088_50880302_37_dialog_content = "... Adiós.",
  ui_story_5088_50880302_38_dialog_content = "Bien, ¡los veré a todos más tarde!",
  ui_story_5088_50880302_39_dialog_content = "Espera, Casta—",
  ui_story_5088_50880302_40_dialog_content = "No sé si puedo manejar el hojear cada una de estas notas.",
  ui_story_5088_50880302_41_dialog_content = "¿Crees que puedes usar tu increíble suerte para decirme por dónde empezar?",
  ui_story_5088_50880302_42_dialog_content = "Cuando el trabajo duro no puede salvarte y no tienes a dónde más recurrir, es cuando debes aplaudir y rezar por suerte.",
  ui_story_5088_50880302_43_dialog_content = "Pero no puedes confiar en la suerte cuando el trabajo duro aún es una opción.",
  ui_story_5088_50880302_44_dialog_content = "De nuevo, podría agregarlo a mi lista de servicios prestados... Aquí, comienza con este.",
  ui_story_5088_50880302_45_dialog_content = "¿Ah?",
  ui_story_5088_50880302_46_dialog_content = "Parece que tu técnica secreta falló esta vez. No siento nada de este cuaderno.",
  ui_story_5088_50880302_47_dialog_content = "Confío en mucho más que solo mi suerte, ya sabes.",
  ui_story_5088_50880302_48_dialog_content = "¿Por qué no intentas creer un poco más en ti mismo en su lugar?",
  ui_story_5088_50880302_49_dialog_content = "Supongo que tienes razón... Lo siento, Casta, no debería haber intentado aprovecharme de tu buena suerte de esa manera.",
  ui_story_5088_50880302_50_dialog_content = "¡¿E-Eh?!",
  ui_story_5088_50880302_51_dialog_content = "¡Mira la portada de este cuaderno... Es una Muñeca Windelion!",
  ui_story_5088_50880302_52_dialog_content = "¡Debe... Debe haber pertenecido a un Celestita!",
  ui_story_5088_50880302_53_dialog_content = "(Es tenue, pero este cuaderno está emitiendo una longitud de onda tan familiar como esos emblemas. Este podría ser el cuaderno de la señorita Ludweiss...)",
  ui_story_5088_50880302_54_dialog_content = "Parece que estás en el camino correcto de nuevo. Nos vemos.",
  ui_story_5088_50880302_55_dialog_content = "(Pero la señorita Ludweiss nunca regresó a Eraveil en su vida. ¿Quizás había otros Caelestites viajeros como ella que sabían cómo hacer muñecas Windelion?)",
  ui_story_5088_50880302_56_dialog_content = "Aún así, no se puede negar la sensación familiar que proviene de este cuaderno... Supongo que no lo sabré hasta que lo abra y vea...",
  ui_story_5088_50880401_1_dialog_content = "<color=#e8d9bb>En medio de una fría noche de invierno, un grupo especial de personas se reúne justo fuera de una cueva congelada.</color>",
  ui_story_5088_50880401_2_dialog_content = "<color=#e8d9bb>Desde dentro de la cueva, su venerable y anciano maestro les habla sobre una existencia que deben proteger.</color>",
  ui_story_5088_50880401_3_dialog_content = "... El rey ha cumplido su promesa y se ha restaurado la paz. Ahora, no hay necesidad de que el mundo recuerde a los Soldados Eclipsite, ni las técnicas de aumento que los originaron.",
  ui_story_5088_50880401_4_dialog_content = "Los niños que fueron exiliados de estas tierras encontraron nuevas tribus a las que llamar suyas. De hecho, algunos afirman que incluso descubrieron un paraíso flotando en el cielo.",
  ui_story_5088_50880401_5_dialog_content = "Los parientes de Lady Freya reconstruyeron la ciudad fronteriza en un lugar espléndido y hermoso. La montaña congelada, que ha estado de pie desde tiempos inmemoriales, se ha derretido y formado un lago tan prístino y vidrioso como un espejo.",
  ui_story_5088_50880401_6_dialog_content = "*tose* Y aún así... nunca tuve éxito en encontrar Eraveil.",
  ui_story_5088_50880401_7_dialog_content = "Aunque mi vida ha abarcado muchos años, no logré llevar a nuestra querida amiga Ludweiss de vuelta a su hogar y darle descanso.",
  ui_story_5088_50880401_8_dialog_content = "... No es tu culpa, Anthony.",
  ui_story_5088_50880401_9_dialog_content = "Me he hecho viejo, Señor Aquiles... La muerte amenaza con llevarme en cualquier momento.",
  ui_story_5088_50880401_10_dialog_content = "Pero antes de que lo haga, tengo más que decirte. Por eso pedí a mis hijos que me trajeran aquí hoy.",
  ui_story_5088_50880401_11_dialog_content = "Deseo expresar mi remordimiento, mi señor. Al no poder completar la misión que me has dado, te he fallado como tu guardia... Y aunque soy tu soldado, no tengo forma de morir a tu lado en batalla.",
  ui_story_5088_50880401_12_dialog_content = "Creí ser leal, y sin embargo no he hecho más que decepcionarte... e incluso al final, tendré que cerrar mis ojos ante ti.",
  ui_story_5088_50880401_13_dialog_content = "Levanta la cabeza, Anthony. No te culpo, solo siento el máximo orgullo y gratitud.",
  ui_story_5088_50880401_14_dialog_content = "Ya has hecho más que suficiente por nosotros, mi amigo.",
  ui_story_5088_50880401_15_dialog_content = "No... Tú mereces mucho mejor que esto, mi señor! Ya has perdido a tantas personas... Debes pensar que soy cruel por dejarte verme en mi estado viejo y moribundo.",
  ui_story_5088_50880401_16_dialog_content = "Pero me preocupaba que si no venía, te preocuparías innecesariamente por mí.",
  ui_story_5088_50880401_17_dialog_content = "Como tu guardia... Es justo que muera antes que tú. Si no supiera de tu inmensa carga, soñaría con luchar a tu lado nuevamente algún día.",
  ui_story_5088_50880401_18_dialog_content = "Mi general, el héroe del reino... Tú devoraste la oscuridad, pero yo soy el único que fue testigo de tu luz.",
  ui_story_5088_50880401_19_dialog_content = "Mis descendientes serán los que permanezcan a tu lado de ahora en adelante... Pero pocos recordarán la grandeza de tus logros.",
  ui_story_5088_50880401_20_dialog_content = "Está seguro, Anthony.",
  ui_story_5088_50880401_21_dialog_content = "Incluso si la historia nos olvida, nunca abandonaré mi propósito. Hice una promesa a mis camaradas de que lo soportaría todo.",
  ui_story_5088_50880401_22_dialog_content = "Así que deja tu remordimiento y descansa, mi cansado amigo. Te lo has ganado con creces.",
  ui_story_5088_50880401_23_dialog_content = "Ah... Tu perdón significa más para mí de lo que jamás sabrás, mi señor.",
  ui_story_5088_50880401_24_dialog_content = "¿Pero qué pasa con Ludweiss? Todavía no puedo cerrar los ojos. No puedo...",
  ui_story_5088_50880401_25_dialog_content = "Me salvaste y aún así te fallé, Señor Aquiles. También fallé a Dominic.",
  ui_story_5088_50880401_26_dialog_content = "Mira hacia atrás en tu vida, Anthony.",
  ui_story_5088_50880401_27_dialog_content = "Siempre has protegido a los débiles e indefensos, así como a nuestro honor. Has sembrado las semillas del amor y la lealtad, y has criado a tus hijos y nietos con orgullo.",
  ui_story_5088_50880401_28_dialog_content = "Sacrificaste riqueza y gloria por el bien de mantener tu promesa. Ninguna alma brilla más que la tuya, mi amigo.",
  ui_story_5088_50880401_29_dialog_content = "Ninguna parte de tu vida se gastó en vano. Has honrado los deseos de aquellos que se sacrificaron... Y también mi propio deseo.",
  ui_story_5088_50880401_30_dialog_content = "Pero...",
  ui_story_5088_50880401_31_dialog_content = "Descansa en paz, Anthony. Te has ganado tu lugar en el paraíso de los soldados.",
  ui_story_5088_50880401_32_dialog_content = "Y si debería cerrarte sus puertas, estaré allí para abrirlas con mi espada.",
  ui_story_5088_50880401_33_dialog_content = "Así que no te preocupes... Ludweiss y yo nos quedaremos en este mundo, esperando el amanecer del futuro que ella una vez vio.",
  ui_story_5088_50880401_34_dialog_content = "Así que deja que tus últimos momentos estén llenos de esperanza, mi amigo.",
  ui_story_5088_50880401_35_dialog_content = "Señor Aquiles...",
  ui_story_5088_50880401_36_dialog_content = "¿Quieres saber por qué estoy yendo tan lejos por ellos?",
  ui_story_5088_50880401_37_dialog_content = "Estás haciendo lo mismo, ¿no? En lo que a mí respecta, no hay diferencia entre nosotros.",
  ui_story_5088_50880401_38_dialog_content = "Como fiel guardia del Señor Aquiles, tengo un deber que cumplir.",
  ui_story_5088_50880401_39_dialog_content = "Pero no estoy seguro de si las cosas realmente pueden cambiar...",
  ui_story_5088_50880401_40_dialog_content = "Oye, Anthony... Si me preguntas, eso es exactamente lo que es la esperanza: una antorcha que arde en la noche más oscura.",
  ui_story_5088_50880401_41_dialog_content = "Sé que estaré agotado...",
  ui_story_5088_50880401_42_dialog_content = "Pero el camino que he forjado guiará a otros fuera de la oscuridad.",
  ui_story_5088_50880401_43_dialog_content = "A partir de ahora, aquellos que siguen este camino ya no necesitan temer perderse.",
  ui_story_5088_50880401_44_dialog_content = "Las estrellas brillan sobre todos nosotros. Tú, yo y innumerables otras personas que sufren en nuestro mundo.",
  ui_story_5088_50880401_45_dialog_content = "¿De verdad crees que podrían ver el lado positivo antes de empezar?",
  ui_story_5088_50880401_46_dialog_content = "Estás diciendo...",
  ui_story_5088_50880401_47_dialog_content = "Mira detrás de ti, Anthony.",
  ui_story_5088_50880401_48_dialog_content = "Ya has iluminado el camino para tantas personas.",
  ui_story_5088_50880401_49_dialog_content = "Puede que no sea ahora, pero ese cambio definitivamente sucederá en algún momento en el futuro, y todo gracias a lo que has hecho en la vida.",
  ui_story_5088_50880401_50_dialog_content = "Ten fe en el futuro. Has hecho tanto por todos los demás, pero ahora es tu turno de descansar.",
  ui_story_5088_50880401_51_dialog_content = "¿Yo... realmente merezco esto?",
  ui_story_5088_50880401_52_dialog_content = "Je, ¿realmente tienes que preguntar?",
  ui_story_5088_50880401_53_dialog_content = "Anthony Longinus... Me siento honrado de haber presenciado el momento en el que la llama de tu orgullosa y noble alma fue extinguida. Que te vaya bien en tu viaje al paraíso del soldado, mi amigo.",
  ui_story_5088_50880401_54_dialog_content = "Te lo mereces todo.",
  ui_story_5088_50880401_55_dialog_content = "El abuelo sonrió mientras fallecía.",
  ui_story_5088_50880401_56_dialog_content = "...",
  ui_story_5088_50880401_57_dialog_content = "Como su sucesor, me siento honrado de entrar en esta cueva y servirte, Señor Aquiles.",
  ui_story_5088_50880401_58_dialog_content = "Entonces, toma este emblema y llévalo con orgullo.",
  ui_story_5088_50880401_59_dialog_content = "Se lo presento a él y a ustedes, sus nobles descendientes.",
  ui_story_5088_50880401_60_dialog_content = "P-Pero mi señor, este emblema... Es demasiado precioso para que lo aceptemos.",
  ui_story_5088_50880401_61_dialog_content = "Anthony era mi camarada de armas, así como un verdadero amigo. Se ganó mi respeto, y por lo tanto, te extiendo lo mismo a ti.",
  ui_story_5088_50880401_62_dialog_content = "Solo espero que el poder de este emblema sea útil para tu familia.",
  ui_story_5088_50880401_63_dialog_content = "Llévalo a casa. Tu abuelo vivió una vida plena y significativa, y merece ser despedido con las lágrimas y bendiciones de su familia.",
  ui_story_5088_50880401_64_dialog_content = "E-Entiendo, Señor Aquiles. Si nos disculpa...",
  ui_story_5088_50880401_65_dialog_content = "Mis amigos... También me gustaría descansar mis ojos por un rato...",
  ui_story_5088_50880401_66_dialog_content = "...",
  ui_story_5088_50880401_67_dialog_content = "Por favor... Visítame en mis sueños y hazme compañía una vez más.",
  ui_story_5088_50880401_68_dialog_content = "<color=#e8d9bb>Y así comenzó su sueño solitario e interminable.</color>",
  ui_story_5088_50880401_69_dialog_content = "<color=#e8d9bb>Pero se desviará de su mundo una vez más cuando se despierte de su sueño.</color>",
  ui_story_5088_50880401_70_dialog_content = "Perdón... ¿Pero sabes cómo entrar a Eraveil?",
  ui_story_5088_50880401_71_dialog_content = "Habíamos estado buscando el lugar durante años y nos dijeron que la entrada estaba cerca.",
  ui_story_5088_50880401_72_dialog_content = "¿Eh? ¿Por qué vas a Eraveil?",
  ui_story_5088_50880401_73_dialog_content = "... Tenemos una promesa que cumplir.",
  ui_story_5088_50880401_74_dialog_content = "Perdóname por ser directo, pero te pareces mucho al Caelestite mencionado en las leyendas de nuestra familia.",
  ui_story_5088_50880401_75_dialog_content = "Oh, ¿es eso así? Bueno, tienes suerte porque resulta que yo soy...",
  ui_story_5088_50880401_76_dialog_content = "<color=#FFB400>¡Potencia de fuerza!</color>",
  ui_story_5088_50880401_77_dialog_content = "Bien, ustedes extraños forasteros, veamos qué tipo de pensamientos malvados tienen en sus cabezas...",
  ui_story_5088_50880401_78_dialog_content = "¡Estás despierto, Señor Aquiles!",
  ui_story_5088_50880401_79_dialog_content = "¿Eres... el nieto de Anthony?",
  ui_story_5088_50880401_80_dialog_content = "No, mi señor. Han pasado muchas, muchas eras desde el tiempo de nuestros antepasados.",
  ui_story_5088_50880401_81_dialog_content = "¡¿?!",
  ui_story_5088_50880401_82_dialog_content = "Mis recuerdos se han roto de nuevo... ¿Cuántos de ellos perdí esta vez?",
  ui_story_5088_50880401_83_dialog_content = "... Por favor, no estés triste, Señor Aquiles.",
  ui_story_5088_50880401_84_dialog_content = "Hemos venido con buenas noticias.",
  ui_story_5088_50880401_85_dialog_content = "Oh... Estaban diciendo la verdad después de todo.",
  ui_story_5088_50880401_86_dialog_content = "Entonces eres Claymore, ¿eh?",
  ui_story_5088_50880401_87_dialog_content = "Debo pedirle que se dirija al Lord Aquiles de una manera más adecuada, Sr. Czerny.",
  ui_story_5088_50880401_88_dialog_content = "¿En serio? Porque creo que Claymore suena mucho más genial.",
  ui_story_5088_50880401_89_dialog_content = "¿Estás... estás tú...?",
  ui_story_5088_50880401_90_dialog_content = "Tu ropa... tu cara...",
  ui_story_5088_50880401_91_dialog_content = "¿Eres uno de los de Ludweiss?",
  ui_story_5088_50880401_92_dialog_content = "Lo siento, pero no conozco a ningún Ludweiss. A nuestra gente no le gusta exactamente correr por el mundo exterior, ¿sabes?",
  ui_story_5088_50880401_93_dialog_content = "Ella una vez dijo... Su familia dejó Eraveil hace mucho tiempo, por lo que pasó toda su vida buscándolo de nuevo.",
  ui_story_5088_50880401_94_dialog_content = "¿Podrían ustedes dos... decirme sus nombres?",
  ui_story_5088_50880401_95_dialog_content = "Haré lo mejor que pueda para recordar.",
  ui_story_5088_50880401_96_dialog_content = "Sería un honor, mi señor... Soy Dominic Longinus, y resido en una isla actualmente conocida como Azurite.",
  ui_story_5088_50880401_97_dialog_content = "Dominic... Escuchar ese nombre me llena de nostalgia.",
  ui_story_5088_50880401_98_dialog_content = "El Sr. Anthony deseaba que, en cualquier edad, una presencia familiar estuviera allí para saludarte al despertar.",
  ui_story_5088_50880401_99_dialog_content = "Lo siento si soné grosero justo ahora. Mi nombre es Czerny, y encontré a tu amigo aquí vagando por Eraveil, así que eché un pequeño vistazo a su mente.",
  ui_story_5088_50880401_100_dialog_content = "Vi toda tu historia, y tengo que decir... ¡Fue impresionante!",
  ui_story_5088_50880401_101_dialog_content = "¡Especialmente tu amistad con esa niña Caelestite! ¡Todo el asunto me sacudió hasta el fondo!",
  ui_story_5088_50880401_102_dialog_content = "Entonces, no solo voy a llevar a Ludweiss de vuelta a Eraveil para que descanse, ¡también voy a salvar a todos ustedes!",
  ui_story_5088_50880401_103_dialog_content = "Ahora, ¿dónde está ese sello? ¿Puede algún Caelestita deshacerlo?",
  ui_story_5088_50880401_104_dialog_content = "... Por favor, no los sueltes ahora, Anthony.",
  ui_story_5088_50880401_105_dialog_content = "Aún no es su momento.",
  ui_story_5088_50880401_106_dialog_content = "¿Ah?",
  ui_story_5088_50880401_107_dialog_content = "... Ludweiss los selló para evitar que la corrupción en sus cuerpos se extendiera a sus mentes.",
  ui_story_5088_50880401_108_dialog_content = "Ella quería darles un respiro muy necesario de su sufrimiento.",
  ui_story_5088_50880401_109_dialog_content = "Solo cuando sus cuerpos hayan sido completamente transformados habrá esperanza de preservar su sensibilidad.",
  ui_story_5088_50880401_110_dialog_content = "También he infundido magia incolora en todos sus sellos. Una vez que sus cuerpos hayan sido liberados, quiero liberar también sus emociones bloqueadas.",
  ui_story_5088_50880401_111_dialog_content = "Realmente no lo entiendo... Pero está bien. Después de todo, es tu decisión.",
  ui_story_5088_50880401_112_dialog_content = "Has estado luchando contra la corrupción durante mucho tiempo también, ¿no es así?",
  ui_story_5088_50880401_113_dialog_content = "Te ayudaré a encontrar una salida a este lío... Y si eso no funciona, también puedo sellarte.",
  ui_story_5088_50880401_114_dialog_content = "¿Es eso realmente posible?",
  ui_story_5088_50880401_115_dialog_content = "No puede hacer daño intentarlo, ¿verdad?",
  ui_story_5088_50880401_116_dialog_content = "Podemos averiguar cómo salvarte primero, luego podemos llevar a Ludweiss de regreso y darle descanso.",
  ui_story_5088_50880401_117_dialog_content = "... No puedo ser sellado como los demás. Si entro en un estado similar de inconsciencia, no quedará nadie para mantener su sello.",
  ui_story_5088_50880401_118_dialog_content = "Agradezco tu amable oferta, pero tengo el deber de preservar esta formación y asegurarme de que mis amigos permanezcan sellados.",
  ui_story_5088_50880401_119_dialog_content = "Ah... ¡Eso también está bien! ¡Tenemos mucho tiempo! Voy a quedarme un rato y probar algunas cosas. Siéntete libre de irte a casa cuando quieras, Dominic.",
  ui_story_5088_50880401_120_dialog_content = "Si necesita algo, Sr. Czerny, todo lo que tiene que hacer es preguntar. Nuestra familia está más que dispuesta a ayudarlo.",
  ui_story_5088_50880401_121_dialog_content = "Czerny... ¿De verdad viajaste hasta aquí desde Eraveil simplemente porque nuestra historia te conmovió?",
  ui_story_5088_50880401_122_dialog_content = "¡Por supuesto! Pero también quiero demostrarme algo a mí mismo.",
  ui_story_5088_50880401_123_dialog_content = "Quiero demostrar... que no soy un debilucho.",
  ui_story_5088_50880401_124_dialog_content = "Quiero que todos sepan que soy capaz de lograr grandes cosas también. Cuando todo esto termine, estoy seguro de que todos finalmente me respetarán como un héroe!",
  ui_story_5088_50880401_125_dialog_content = "Y entonces, no tendrán más opción que elegirme como un Coloso'... Ah, pero eso no viene al caso.",
  ui_story_5088_50880401_126_dialog_content = "Cualquiera que rescate a un héroe también puede ser llamado un héroe, ¿verdad?",
  ui_story_5088_50880401_127_dialog_content = "Es bueno tener ambición, Czerny. Independientemente de tus razones para estar aquí, estoy agradecido de que hayas venido.",
  ui_story_5088_50880401_128_dialog_content = "Pero la grandeza de una persona no proviene solo de sus logros.",
  ui_story_5088_50880401_129_dialog_content = "Espero que recuerdes lo que querías en primer lugar.",
  ui_story_5088_50880401_130_dialog_content = "¡Sí, por supuesto, te escucho. ¡Sólo déjamelo a mí!",
  ui_story_5088_50880401_131_dialog_content = "Ahora bien, ¿por dónde debería empezar...?",
  ui_story_5088_50880401_132_dialog_content = "Realmente no necesitas hacer esto, Czerny. Suficientes personas se han sacrificado por nuestro bien.",
  ui_story_5088_50880401_133_dialog_content = "Por favor, solo lleva a Ludweiss de regreso a Eraveil.",
  ui_story_5088_50880401_134_dialog_content = "Estaría eternamente agradecido contigo por hacer eso solo.",
  ui_story_5088_50880401_135_dialog_content = "<color=#FFB400>¡Potencia de fuerza!</color>",
  ui_story_5088_50880402_1_dialog_content = "... Esto va a ser más complicado de lo que pensaba.",
  ui_story_5088_50880402_2_dialog_content = "No tengo duda de eso.",
  ui_story_5088_50880402_3_dialog_content = "¡Pero no te preocupes, encontraré una manera!",
  ui_story_5088_50880402_4_dialog_content = "Además, podrías usar la compañía, ¿no crees?",
  ui_story_5088_50880402_5_dialog_content = "Dominic puede encargarse de toda la comida y agua que necesito, así que no te preocupes por mí.",
  ui_story_5088_50880402_6_dialog_content = "¡Jaja, esta es una nueva y emocionante aventura para mí también, sabes!",
  ui_story_5088_50880402_7_dialog_content = "... En ese caso, puedes quedarte con el resto de mis camaradas.",
  ui_story_5088_50880402_8_dialog_content = "Pero no importa lo que puedas escuchar por la noche, no puedes abandonar ese lugar. ¿Entendido?",
  ui_story_5088_50880402_9_dialog_content = "¡Oh? ¡Esto está empezando a sonar mucho más peligroso ahora!",
  ui_story_5088_50880402_10_dialog_content = "Mi luz hace tiempo que se agotó. No hay forma de saber cuánto tiempo más puedo aguantar.",
  ui_story_5088_50880402_11_dialog_content = "¿Ves esas marcas en la pared? Esos fueron mi obra.",
  ui_story_5088_50880402_12_dialog_content = "Pero si te quedas cerca de ellos, no me acercaré a ti.",
  ui_story_5088_50880402_13_dialog_content = "...",
  ui_story_5088_50880402_14_dialog_content = "Humph, buen intento, pero no me vas a asustar. Ya que ya acepté esta tarea, voy a hacer un buen trabajo. ¡Solo espera y verás!",
  ui_story_5088_50880402_15_dialog_content = "Me quedé sin pistas de nuevo... ¿Me pregunto qué pasará después? ¿Y quién es este tipo Czerny, de todos modos?",
  ui_story_5088_50880402_16_dialog_content = "(No parece muy confiable. ¿Está realmente bien?)",
  ui_story_5088_50880402_17_dialog_content = "Suspiro... Debería escribir a Jeriah.",
  ui_story_5088_50880402_18_dialog_content = "(Es una experta en historia. ¿Quizás sabe más sobre los Guerreros Estelares?)",
  ui_story_5088_50880402_19_dialog_content = "¿Qué... Mi nariz está sangrando?",
  ui_story_5088_50880402_20_dialog_content = "(¿He estado abusando de mis poderes últimamente?)",
  ui_story_5088_50880402_21_dialog_content = "Esto no está bien... No puedo dejar que nadie me vea así...",
  ui_story_5088_50880402_22_dialog_content = "Entonces, ¿esto tampoco funcionará, eh? Me pregunto qué salió mal esta vez...",
  ui_story_5088_50880402_23_dialog_content = "No pretendo culparte, Czerny, pero... por favor, deja de perder más tiempo en esto.",
  ui_story_5088_50880402_24_dialog_content = "No vale la pena el tiempo, todavía eres joven.",
  ui_story_5088_50880402_25_dialog_content = "¡De ninguna manera! De hecho, eso es precisamente por lo que no puedo rendirme ahora!",
  ui_story_5088_50880402_26_dialog_content = "Es posible que no lo sepas, pero mi gente se ha vuelto complaciente desde que Eraveil decidió retirarse de la guerra.",
  ui_story_5088_50880402_27_dialog_content = "Encontrar paz y tranquilidad al retirarnos del mundo... O eso decimos. La verdad es que solo nos estamos escondiendo en nuestra propia pequeña burbuja.",
  ui_story_5088_50880402_28_dialog_content = "Pero incluso así, todavía estamos atrapados en todo tipo de conflictos.",
  ui_story_5088_50880402_29_dialog_content = "Voy a demostrarles a todos que puedo hacerlo. Tengo lo que se necesita.",
  ui_story_5088_50880402_30_dialog_content = "...",
  ui_story_5088_50880402_31_dialog_content = "No llegaré a ninguna parte quedándome en casa. En lugar de estar atrapado en el suelo para siempre, preferiría arriesgarme y ver qué tan alto puedo volar.",
  ui_story_5088_50880402_32_dialog_content = "Todavía hay tiempo, ¡así que por favor confía en mí! Prometo que encontraré una manera de sellarte o evitar que la corrupción se apodere de tu mente.",
  ui_story_5088_50880402_33_dialog_content = "Solo necesito unos días para descansar... Solo unos pocos serán suficientes...",
  ui_story_5088_50880402_34_dialog_content = "... Lo siento, Czerny, pero se me acaba el tiempo.",
  ui_story_5088_50880402_35_dialog_content = "Ya he revisado cada uno de los diarios de Ludweiss.",
  ui_story_5088_50880402_36_dialog_content = "Pero aparte de las historias y las partituras, nada puede ayudarme.",
  ui_story_5088_50880402_37_dialog_content = "He estado ausente durante tanto tiempo... Me pregunto cuántas veces podría haber sido elegido como piloto hasta ahora...",
  ui_story_5088_50880402_38_dialog_content = "¡Diablos!",
  ui_story_5088_50880402_39_dialog_content = "No creo que las hojas de música sean inútiles.",
  ui_story_5088_50880402_40_dialog_content = "Entonces escuchaste, ¿eh? Pero estoy aquí fuera.",
  ui_story_5088_50880402_41_dialog_content = "Czerny, en mi mundo cruel e implacable, las palabras de odio se pronuncian fácilmente, pero pocos pueden mantener su bondad ante el dolor.",
  ui_story_5088_50880402_42_dialog_content = "Esa música, que proviene del corazón, es un testimonio de la gloria de la gente de este mundo.",
  ui_story_5088_50880402_43_dialog_content = "Hace muchos años, tuve el privilegio de escuchar una de las canciones de Ludweiss. Era una melodía elegante y compasiva, tan suave y gentil como la luz de la luna.",
  ui_story_5088_50880402_44_dialog_content = "¿Podrías... entrar en mis sueños y ayudarme a recordar su música una vez más?",
  ui_story_5088_50880402_45_dialog_content = "La noche es oscura y este lugar es muy frío. Creo que ambos podríamos usar el tranquilo resplandor de la luna.",
  ui_story_5088_50880402_46_dialog_content = "... Ahora que tu luz ha sido devorada, lo único que queda es la oscuridad que continúa corrompiéndote desde dentro.",
  ui_story_5088_50880402_47_dialog_content = "Incluso como Caelestite, no puedo discernir su color. Lo siento, pero tu mente es demasiado peligrosa para que entre ahora.",
  ui_story_5088_50880402_48_dialog_content = "No tengo forma de buscar de manera segura en tu conciencia una forma de separarte de esa oscuridad. Es la razón por la que esto me está llevando tanto tiempo.",
  ui_story_5088_50880402_49_dialog_content = "Pero por favor, solo dame un poco más de tiempo...",
  ui_story_5088_50880402_50_dialog_content = "Está bien... Después de tomar un día para descansar, debería poder continuar buscando en esos recuerdos...",
  ui_story_5088_50880402_51_dialog_content = "(Creo que mi corazonada es correcta. Alguien deliberadamente esparció estas notas por todo Astra.)",
  ui_story_5088_50880402_52_dialog_content = "(Aunque la escritura es casi completamente ilegible, las páginas aún están tan llenas de historia. Es casi como si quien hizo esto no pudiera soportar destruir estas notas.)",
  ui_story_5088_50880402_53_dialog_content = "(Como si... Estuvieran esperando que algún día un Caelestite los sintiera.)",
  ui_story_5088_50880402_54_dialog_content = "... De todos modos, es hora de ponerse a trabajar.",
  ui_story_5088_50880402_55_dialog_content = "¿Cómo puede estar pasando esto? Entrené durante más de una década solo para poder pilotar un Colossus.",
  ui_story_5088_50880402_56_dialog_content = "Entonces, ¿por qué soy tan inútil cuando se trata de ayudar a Claymore?",
  ui_story_5088_50880402_57_dialog_content = "No debería ser así... No debería...",
  ui_story_5088_50880402_58_dialog_content = "He estado aquí tanto tiempo. No puedo irme a casa con las manos vacías.",
  ui_story_5088_50880402_59_dialog_content = "Czerny...",
  ui_story_5088_50880402_60_dialog_content = "Solo dame un segundo para descansar. He estado usando mis poderes psíquicos durante tanto tiempo que siento que mi cabeza va a partirse.",
  ui_story_5088_50880402_61_dialog_content = "¡Corre, Czerny!",
  ui_story_5088_50880402_62_dialog_content = "¿Ah?",
  ui_story_5088_50880402_63_dialog_content = "No pude deshacerme de ellos—",
  ui_story_5088_50880402_64_dialog_content = "La oscuridad dentro de mí está aumentando.",
  ui_story_5088_50880402_65_dialog_content = "¡Tienes que irte, ahora! De lo contrario...",
  ui_story_5088_50880402_66_dialog_content = "¡Voy a matarte!",
  ui_story_5088_50880402_67_dialog_content = "¡N-De ninguna manera!",
  ui_story_5088_50880402_68_dialog_content = "Oh, no, él es serio... no durará mucho más.",
  ui_story_5088_50880402_69_dialog_content = "¿Cómo pudo pasar esto? ¿Qué me estoy perdiendo aquí?!",
  ui_story_5088_50880402_70_dialog_content = "¡Así es, los diarios! Necesito buscar en cada detalle de su mente y encontrar la respuesta...",
  ui_story_5088_50880402_71_dialog_content = "PlayerName! ¡Despierta! ¿Por qué estás durmiendo en el suelo?",
  ui_story_5088_50880402_72_dialog_content = "¡Y mírate! Tienes sangre seca corriendo desde tu nariz hasta tu pecho.",
  ui_story_5088_50880402_73_dialog_content = "¿Justo qué es lo que nos estás ocultando? ¡Dilo ya!",
  ui_story_5088_50880402_74_dialog_content = "Lo-lo siento, pero aún no puedo decírtelo!",
  ui_story_5088_50880402_75_dialog_content = "Por favor, solo dame unos días más y te contaré todo. ¡Nos vemos!",
  ui_story_5088_50880402_76_dialog_content = "¡Oye, espera!",
  ui_story_5088_50880402_77_dialog_content = "(No puedo decirles nada si Claymore fue salvado. Simplemente no puedo...)",
  ui_story_5088_50880402_78_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5088_50880402_79_dialog_content = "No... Esto no puede ser posible...",
  ui_story_5088_50880402_80_dialog_content = "Ella hizo su <color=#FFB400>elección</color> hace mucho tiempo. Incluso lo <color=#FFB400>predijo</color>...",
  ui_story_5088_50880402_81_dialog_content = "La persona que va a salvarlos no soy yo, sino otro Caelestite en el futuro lejano.",
  ui_story_5088_50880402_82_dialog_content = "<color=#e8d9bb>En la lluvia intensa, el rugido del trueno rasga el cielo. Profundo dentro de la cueva congelada, se puede escuchar otro rugido...</color>",
  ui_story_5088_50880402_83_dialog_content = "¡¡¡Graaaaaaah—!!!",
  ui_story_5088_50880402_84_dialog_content = "<color=#e8d9bb>Con un poderoso corte, una ola de pura energía surge de la cueva y desgarra el suelo.</color>",
  ui_story_5088_50880402_85_dialog_content = "<color=#e8d9bb>Aunque el corte apenas falla a Czerny, su espíritu está completamente abrumado por su intención asesina.</color>",
  ui_story_5088_50880402_86_dialog_content = "<color=#e8d9bb>En ese momento, finalmente se da cuenta de lo peligroso que puede ser su compañero.</color>",
  ui_story_5088_50880402_87_dialog_content = "¿Por qué...? ¿Por qué tiene que ser así...?",
  ui_story_5088_50880402_88_dialog_content = "<color=#e8d9bb>Tembloroso violentamente, Czerny intenta ponerse de pie, pero sus piernas le fallan poco después.</color>",
  ui_story_5088_50880402_89_dialog_content = "<color=#e8d9bb>Deja caer los diarios de Ludweiss, y la tormenta aullante dispersa rápidamente las páginas.</color>",
  ui_story_5088_50880402_90_dialog_content = "¡No! ¡Noooo-!!!",
  ui_story_5088_50880402_91_dialog_content = "<color=#e8d9bb> Czerny agarra desesperadamente las páginas, pero solo logra recuperar un puñado de ellas.</color>",
  ui_story_5088_50880402_92_dialog_content = "<color=#e8d9bb>Él ha fallado.</color>",
  ui_story_5088_50880402_93_dialog_content = "Yo... Yo fallé... A todos ellos.",
  ui_story_5088_50880402_94_dialog_content = "Desperdicié los últimos esfuerzos de Ludweiss...",
  ui_story_5088_50880402_95_dialog_content = "Y fallé a Aquiles.",
  ui_story_5088_50880402_96_dialog_content = "<color=#e8d9bb>La lluvia finalmente disminuye después de un tiempo desconocido, junto con los terribles sonidos dentro de la cueva.</color>",
  ui_story_5088_50880402_97_dialog_content = "<color=#e8d9bb>Czerny entra una vez más a la cueva, agarrando las pocas páginas del cuaderno que pudo recuperar.</color>",
  ui_story_5088_50880402_98_dialog_content = "¿Realmente no hay nada que podamos hacer para ayudarte? Aquiles...",
  ui_story_5088_50880402_99_dialog_content = "...",
  ui_story_5088_50880402_100_dialog_content = "No pude hacer nada por ti más que desperdiciar tu tiempo. Nunca valí nada, ¿verdad?",
  ui_story_5088_50880402_101_dialog_content = "¡Dime, Aquiles! ¡Dime qué tonto soy!",
  ui_story_5088_50880402_102_dialog_content = "Vete, Czerny. Con mis últimos momentos de lucidez, quiero agradecerte por estar conmigo todo este tiempo.",
  ui_story_5088_50880402_103_dialog_content = "Tener a alguien con quien hablar fue suficiente para aplacar a los monstruos en mi corazón.",
  ui_story_5088_50880402_104_dialog_content = "Abandona este lugar y no se lo cuentes a nadie... No quiero que más personas de buen corazón... sacrifiquen algo por mi causa.",
  ui_story_5088_50880402_105_dialog_content = "¡¡¡Ahhhhhh—!!!",
  ui_story_5088_50880402_106_dialog_content = "Adiós... Czerny.",
  ui_story_5088_50880402_107_dialog_content = "¡No fallaste, Czerny, todavía puedo ayudarte!",
  ui_story_5088_50880402_108_dialog_content = "No, mi voz no puede alcanzarlo...",
  ui_story_5088_50880402_109_dialog_content = "¡Argh, por qué está pasando esto ahora mismo?!",
  ui_story_5088_50880402_110_dialog_content = "¡Déjame ayudarte, Czerny! Puedo—",
  ui_story_5088_50880402_111_dialog_content = "¡Espera, no lo dejes solo!!!",
  ui_story_5088_50880402_112_dialog_content = "¡Todavía puedo ayudarte!!!",
  ui_story_5088_50880501_1_dialog_content = "Estás cubierto de sangre de nuevo. Incluso los Celestitas tienen un límite para sus poderes, ¿no es así?",
  ui_story_5088_50880501_2_dialog_content = "¿A quién... estás hablando?",
  ui_story_5088_50880501_3_dialog_content = "Czerny... ¿Dónde está Czerny?!",
  ui_story_5088_50880501_4_dialog_content = "No hay nadie más aquí que nosotros.",
  ui_story_5088_50880501_5_dialog_content = "Espera, ¿quién es Czerny?",
  ui_story_5088_50880501_6_dialog_content = "No... ¡No, no! ¡Acaba de estar allí! También estaba llorando... Tengo que ayudarlo a salvar a Aquiles—",
  ui_story_5088_50880501_7_dialog_content = "¡Fuera de mi camino! Usaré mi magia curativa para-",
  ui_story_5088_50880501_8_dialog_content = "Eso no será necesario. Puedo manejar las cosas desde aquí.",
  ui_story_5088_50880501_9_dialog_content = "Urgh...",
  ui_story_5088_50880501_10_dialog_content = "¡Solo mira toda esta sangre! ¿Qué has estado haciendo estos últimos días?!",
  ui_story_5088_50880501_11_dialog_content = "Este mensajero tuvo la amabilidad de hacerte un medicamento para detener el sangrado. Deberías agradecerle por sus problemas.",
  ui_story_5088_50880501_12_dialog_content = "G-Gracias.",
  ui_story_5088_50880501_13_dialog_content = "No es nada. Solo vine a recoger tu correo.",
  ui_story_5088_50880501_14_dialog_content = "No somos idiotas... Lo que sea que estés haciendo, tiene algo que ver con nosotros.",
  ui_story_5088_50880501_15_dialog_content = "Y mira dónde te has metido. Si no nos vas a decir nada, tendré que contarle a alguien más tu secreto, como tal vez—",
  ui_story_5088_50880501_16_dialog_content = "¡No le digas a Vice o Carleen sobre esto! ¡Por favor!",
  ui_story_5088_50880501_17_dialog_content = "¿Entonces vas a hablar?",
  ui_story_5088_50880501_18_dialog_content = "Yo... Estoy tratando de aprender la verdad sobre algo. Lo siento... Pero eso es todo lo que puedo decirte ahora mismo.",
  ui_story_5088_50880501_19_dialog_content = "Cuando llegue el momento, te lo diré todo.",
  ui_story_5088_50880501_20_dialog_content = "¿Te estás conteniendo porque te preocupa cómo nos sentiremos?",
  ui_story_5088_50880501_21_dialog_content = "Es por mi sueño que ahora estás atrapado en todo esto.",
  ui_story_5088_50880501_22_dialog_content = "Lo siento... Pero tengo que aprender la verdad sobre lo que le sucedió a Aquiles... Quiero decir, Claymore.",
  ui_story_5088_50880501_23_dialog_content = "Pero no puedo alcanzarlos después de que dejé tu sueño...",
  ui_story_5088_50880501_24_dialog_content = "Debe haber alguna otra forma de impartir mis pensamientos... Victoria una vez dijo que todos los pensamientos de los Celestitas llegarían...",
  ui_story_5088_50880501_25_dialog_content = "Yo... Yo tengo que ayudarlos...",
  ui_story_5088_50880501_26_dialog_content = "Hay un Celestita a su lado. Aún no se ha rendido...",
  ui_story_5088_50880501_27_dialog_content = "Pareces que apenas te queda sangre en el cuerpo. Si sigues esforzándote así, morirás.",
  ui_story_5088_50880501_28_dialog_content = "¿Por qué vas tan lejos por un grupo de forasteros como nosotros?",
  ui_story_5088_50880501_29_dialog_content = "No hay extraños en Soroz. Eres familia.",
  ui_story_5088_50880501_30_dialog_content = "¡¿?!",
  ui_story_5088_50880501_31_dialog_content = "Mmm...",
  ui_story_5088_50880501_32_dialog_content = "(Y además... Soy igual que Czerny. No puedo quedarme de brazos cruzados y no hacer nada, no después de ver su historia.)",
  ui_story_5088_50880501_33_dialog_content = "(Me niego a dejar que estas estrellas se desvanezcan tan trágicamente.)",
  ui_story_5088_50880501_34_dialog_content = "Por favor, solo necesito un poco más de tiempo...",
  ui_story_5088_50880501_35_dialog_content = "... ¿Todavía te duele la cabeza?",
  ui_story_5088_50880501_36_dialog_content = "Estoy bien, solo necesito un poco de aire fresco.",
  ui_story_5088_50880501_37_dialog_content = "Casi lo olvido, pero ¿podrías entregar esto a Jeriah? Ella está estacionada en el puesto del Desierto de Rediesel.",
  ui_story_5088_50880501_38_dialog_content = "... Tratas a tus amigos increíblemente bien. Estabas buscando en esos libros antiguos para tus amigos, ¿no?",
  ui_story_5088_50880501_39_dialog_content = "Perdóname si estoy siendo intrusivo, pero esta es una carta pidiendo la ayuda de Lady Jeriah, ¿no es así?",
  ui_story_5088_50880501_40_dialog_content = "Sí...",
  ui_story_5088_50880501_41_dialog_content = "Quiero ayudarlos sin importar qué.",
  ui_story_5088_50880501_42_dialog_content = "Solo quiero descubrir la verdad... Incluso si es muy atrasada.",
  ui_story_5088_50880501_43_dialog_content = "(Quiero ver qué le pasó a Aquiles y entender cómo terminó así...)",
  ui_story_5088_50880501_44_dialog_content = "(Todavía tengo esperanza de que pueda encontrar una forma de ayudarlo.)",
  ui_story_5088_50880501_45_dialog_content = "(También, aún necesito encontrar los restos de Ludweiss.)",
  ui_story_5088_50880501_46_dialog_content = "Lo siento por darte respuestas tan extrañas.",
  ui_story_5088_50880501_47_dialog_content = "No lo seas. Yo soy el que te hizo una pregunta extraña para empezar.",
  ui_story_5088_50880501_48_dialog_content = "Me aseguraré de que esta carta llegue a salvo a Lady Jeriah.",
  ui_story_5088_50880501_49_dialog_content = "Gracias por tu ayuda, y por la medicina también. Es escalofriante, pero definitivamente detuvo el sangrado.",
  ui_story_5088_50880501_50_dialog_content = "Soy un mensajero, y los mensajeros siempre tienen algunos trucos bajo la manga.",
  ui_story_5088_50880501_51_dialog_content = "Bueno, me iré ahora.",
  ui_story_5088_50880501_52_dialog_content = "Propongo que terminemos con esto aquí y ahora.",
  ui_story_5088_50880501_53_dialog_content = "Estoy de acuerdo con Friegson. Recuperar nuestras memorias no debería ser a costa de tu salud, así que pongamos fin a esto.",
  ui_story_5088_50880501_54_dialog_content = "¿Incluso si eso significa que nunca volverás a recordar tu amor?",
  ui_story_5088_50880501_55_dialog_content = "... Tengo todo el tiempo del mundo para seguir buscándola.",
  ui_story_5088_50880501_56_dialog_content = "¿Qué dices, Freya?",
  ui_story_5088_50880501_57_dialog_content = "\"No hay extraños en Soroz, eres familia\". Esas fueron sus palabras.",
  ui_story_5088_50880501_58_dialog_content = "Siempre he depositado mi confianza en mis amigos, y él no es diferente. Respeto su decisión.",
  ui_story_5088_50880501_59_dialog_content = "¿Todavía tienes esperanza, incluso aunque fuiste traicionado en el pasado?",
  ui_story_5088_50880501_60_dialog_content = "Soy un caballero, liderar la carga en la batalla siempre ha sido mi deber. Unas pocas heridas de puñal nunca podrían desanimarme de eso.",
  ui_story_5088_50880501_61_dialog_content = "Entonces yo también quiero creer en él.",
  ui_story_5088_50880501_62_dialog_content = "No somos perfectos de ninguna manera, así que tal vez no deberíamos ser tan rápidos en descartar a PlayerName.",
  ui_story_5088_50880501_63_dialog_content = "En el pasado, sin importar qué tipo de dolor o debilidad enfrentáramos, siempre y cuando nos tuviéramos el uno al otro...",
  ui_story_5088_50880501_64_dialog_content = "Podríamos superar cualquier cosa y seguir avanzando.",
  ui_story_5088_50880501_65_dialog_content = "Wow... Eso fue hermoso, Cynthia. No has dicho nada tan serio en mucho tiempo. Realmente no es típico de ti en absoluto.",
  ui_story_5088_50880501_66_dialog_content = "Quiero que los Cazadores Silenciosos estén juntos de nuevo. ¿Qué piensa todos de eso?",
  ui_story_5088_50880501_67_dialog_content = "...",
  ui_story_5088_50880501_68_dialog_content = "Incluso después de todo lo que le dije, todavía tuvo suerte y encontró esto con otro de los jefes.",
  ui_story_5088_50880501_69_dialog_content = "Creo que se llama Cresta de estrella?",
  ui_story_5088_50880501_70_dialog_content = "...",
  ui_story_5088_50880501_71_dialog_content = "Está indagando en el secreto de los Guerreros Estelares...",
  ui_story_5088_50880501_72_dialog_content = "Yo... tengo que llevar a cabo mi misión... Y detenerlo...",
  ui_story_5088_50880501_73_dialog_content = "Pero...",
  ui_story_5088_50880501_74_dialog_content = "Cuando se trata de ayudar a mis amigos, haré lo que sea necesario.",
  ui_story_5088_50880501_75_dialog_content = "Debería dárselo mañana.",
  ui_story_5088_50880501_76_dialog_content = "Sal y enfréntame, cobardes.",
  ui_story_5088_50880501_77_dialog_content = "¿¡El Cazador de Cuervos?! ¡No de nuevo!",
  ui_story_5088_50880501_78_dialog_content = "¿Por qué no nos dejas en paz?! ¡Solo estamos tratando de sacudirla un poco para obtener algo de dinero, eso es todo!",
  ui_story_5088_50880501_79_dialog_content = "¿Qué te hace pensar que ella tiene algo que valga la pena robar?",
  ui_story_5088_50880501_80_dialog_content = "¿Por qué no lo haría? Ha estado trabajando para el Gremio Cloudrover e incluso es amiga de ese tipo Caelestite.",
  ui_story_5088_50880501_81_dialog_content = "Lamento decepcionarte, idiotas avariciosos, pero esa cosa no tiene valor alguno.",
  ui_story_5088_50880501_82_dialog_content = "Pero intentar robar un objeto sin valor sigue siendo un delito. ¡Prepárate para ser castigado!",
  ui_story_5088_50880502_1_dialog_content = "¿Oh? Parece que llego muy tarde para unirme a la diversión.",
  ui_story_5088_50880502_2_dialog_content = "Aun así, sabía que te encontraría aquí.",
  ui_story_5088_50880502_3_dialog_content = "...",
  ui_story_5088_50880502_4_dialog_content = "¿Qué pasa? Has estado actuando diferente últimamente.",
  ui_story_5088_50880502_5_dialog_content = "Y también estás siendo mucho más duro con los chicos malos.",
  ui_story_5088_50880502_6_dialog_content = "No es nada. ¿Por qué estás fuera tan tarde, de todos modos? ¿No tienes trabajo durante el día?",
  ui_story_5088_50880502_7_dialog_content = "Lo hago... Pero eso está bien.",
  ui_story_5088_50880502_8_dialog_content = "Siempre es más importante escuchar a mis amigos.",
  ui_story_5088_50880502_9_dialog_content = "No tengo nada que decir. Solo nos conocemos desde hace dos años, y solo nos encontramos a veces por la noche. ¿Realmente llamarías eso \"amistad\"?",
  ui_story_5088_50880502_10_dialog_content = "¡Dos años es un largo tiempo, ya sabes!",
  ui_story_5088_50880502_11_dialog_content = "Además, nos conocimos gracias a nuestros esfuerzos para combatir el crimen. ¡Eso nos convierte en compañeros de batalla!",
  ui_story_5088_50880502_12_dialog_content = "¿Compañeros de batalla? Por favor. Ni siquiera sabes mi nombre.",
  ui_story_5088_50880502_13_dialog_content = "Tienes razón, por eso me encantaría conocerte también durante el día. Apuesto a que eres igual de genial cuando no estás luchando contra los malos!",
  ui_story_5088_50880502_14_dialog_content = "Lamento decepcionarte, pero no hay nada interesante sobre mí o mi vida diaria.",
  ui_story_5088_50880502_15_dialog_content = "Especialmente no para alguien como tú... Que brilla tanto todo el tiempo...",
  ui_story_5088_50880502_16_dialog_content = "¿Eh? ¿Estás intentando decir que eres solo una persona común durante el día?",
  ui_story_5088_50880502_17_dialog_content = "¡Porque creo que eres demasiado poderoso para ser algo menos que extraordinario!",
  ui_story_5088_50880502_18_dialog_content = "De hecho, ¡apuesto a que puedes inspirar a otros tal como lo hacen algunos de los mejores ídolos!",
  ui_story_5088_50880502_19_dialog_content = "... No seas absurdo.",
  ui_story_5088_50880502_20_dialog_content = "Sabes... Hay algo de lo que me gustaría hablar. Es trivial, pero ¿estarías dispuesto a escuchar?",
  ui_story_5088_50880502_21_dialog_content = "¡Por supuesto! Y no te preocupes, no importa cuán importante o trivial sea, prometo mantenerlo en secreto.",
  ui_story_5088_50880502_22_dialog_content = "¿Un secreto, eh? Jeje...",
  ui_story_5088_50880502_23_dialog_content = "La verdad es que nací en un clan único, y toda mi vida, se me ha confiado llevar a cabo una cierta misión.",
  ui_story_5088_50880502_24_dialog_content = "Con ese fin, me enseñaron a siempre observar las cosas desde la distancia y a nunca involucrarme.",
  ui_story_5088_50880502_25_dialog_content = "La nuestra es una familia de sombras que opera más allá del flujo del tiempo. Por eso debemos mantenernos ocultos durante el día.",
  ui_story_5088_50880502_26_dialog_content = "Pero ahora... Los que juramos proteger... No quedan muchos de ellos.",
  ui_story_5088_50880502_27_dialog_content = "¡Vaya! ¡Parece que tu familia está protegiendo algún tipo de criatura rara!",
  ui_story_5088_50880502_28_dialog_content = "¿Cómo podrías pensar que eso no es importante? Proteger algo como tu misión en vida requiere mucho enfoque y precaución.",
  ui_story_5088_50880502_29_dialog_content = "Creo que es increíble que puedas mantener tu luz oculta por el bien de tu misión.",
  ui_story_5088_50880502_30_dialog_content = "Una \"criatura rara\"... Supongo que no está del todo mal. En cualquier caso, si no logro llevar a cabo mi misión, entonces más o menos terminará conmigo.",
  ui_story_5088_50880502_31_dialog_content = "Porque esa persona... No estoy seguro de que esa persona sea capaz de cumplir la profecía.",
  ui_story_5088_50880502_32_dialog_content = "Y entonces mi clan estará unido por el resto del tiempo.",
  ui_story_5088_50880502_33_dialog_content = "Pero más allá de eso, yo... yo solo quiero ayudar a ese cierto grupo de personas.",
  ui_story_5088_50880502_34_dialog_content = "Pero hice un voto para proteger sus secretos, así que solo puedo vigilarlos en silencio. No puedo traicionar mi voto.",
  ui_story_5088_50880502_35_dialog_content = "¿Eso es lo que te ha estado molestando?",
  ui_story_5088_50880502_36_dialog_content = "¿Has estado descargando tu frustración en los chicos malos por eso?",
  ui_story_5088_50880502_37_dialog_content = "Por varias razones que no puedo discutir, mis antepasados pudieron imbuir algunos de sus recuerdos en nuestra reliquia familiar, que ha sido transmitida por generaciones.",
  ui_story_5088_50880502_38_dialog_content = "A través de ello, puedo oír su ira y arrepentimientos.",
  ui_story_5088_50880502_39_dialog_content = "Pero el señor una vez nos dijo que no involucráramos a nadie más por su bien.",
  ui_story_5088_50880502_40_dialog_content = "Desde entonces, nos hemos mantenido ocultos y observado en silencio, esperando que el profetizado cumpla nuestra misión y nos libere a todos.",
  ui_story_5088_50880502_41_dialog_content = "Pero el pueblo del profetizado... Todos ellos eran...",
  ui_story_5088_50880502_42_dialog_content = "No puedo decir que entienda mucho de lo que estás diciendo.",
  ui_story_5088_50880502_43_dialog_content = "Pero parece que llevas una vida muy importante... Y una solitaria, a eso.",
  ui_story_5088_50880502_44_dialog_content = "Tu clan fue encargado de su misión hace mucho tiempo, ¿verdad? Es impresionante que hayas permanecido fiel a ella después de todos estos años.",
  ui_story_5088_50880502_45_dialog_content = "Y eso solo puede ser el resultado de una fe y determinación inquebrantables.",
  ui_story_5088_50880502_46_dialog_content = "Algo me dice que tu ancestro, el que hizo ese voto, sintió un increíble sentido de amor y compasión por aquellos a los que juró proteger.",
  ui_story_5088_50880502_47_dialog_content = "Lo que me hace suponer que no querrían que fueras tan pasivo acerca de tu misión.",
  ui_story_5088_50880502_48_dialog_content = "¿Ah?",
  ui_story_5088_50880502_49_dialog_content = "Si tomas medidas para ayudar a aquellos a los que has jurado proteger, creo que cumplirías mejor los deseos de tus antepasados. ¿No estás de acuerdo?",
  ui_story_5088_50880502_50_dialog_content = "Además, en nuestros dos años de lucha contra el crimen juntos, nunca te he conocido muy pasivo en nada.",
  ui_story_5088_50880502_51_dialog_content = "Esperar a que alguien más te salve como una damisela en apuros... Eso no es propio de ti.",
  ui_story_5088_50880502_52_dialog_content = "Creo que todavía hay mucho que puedes hacer para cumplir tu misión.",
  ui_story_5088_50880502_53_dialog_content = "No tienes que romper tu juramento, pero con unos pocos empujones en la dirección correcta... Podrías ser capaz de realizar los objetivos de tu antepasado.",
  ui_story_5088_50880502_54_dialog_content = "¿De verdad lo crees?",
  ui_story_5088_50880502_55_dialog_content = "¡Por supuesto que sí!",
  ui_story_5088_50880502_56_dialog_content = "...Gracias.",
  ui_story_5088_50880502_57_dialog_content = "Tienes toda la razón. Mis antepasados no pudieron llegar al día profetizado, pero yo sí...",
  ui_story_5088_50880502_58_dialog_content = "Por lo menos, debería intentar hacer algo.",
  ui_story_5088_50880502_59_dialog_content = "Pero ya lo sabías, ¿no es así?",
  ui_story_5088_50880502_60_dialog_content = "... Sí. Es solo que siempre he tenido miedo de empeorar las cosas.",
  ui_story_5088_50880502_61_dialog_content = "Pero odio quedarme de brazos cruzados mientras aún necesitan mi ayuda.",
  ui_story_5088_50880502_62_dialog_content = "Cuando se trata de profecías, siempre tiene que haber alguien para hacerlas realidad.",
  ui_story_5088_50880502_63_dialog_content = "Por eso no puedes confiar en otras personas para que las cosas sucedan. Tienes que hacerlo tú mismo.",
  ui_story_5088_50880502_64_dialog_content = "Ese es uno de los principios básicos de ser un ídolo... Eh, quiero decir un héroe!",
  ui_story_5088_50880502_65_dialog_content = "Gracias, Goldie.",
  ui_story_5088_50880502_66_dialog_content = "Encontraré una manera de ayudarlos sin romper mi juramento.",
  ui_story_5088_50880502_67_dialog_content = "No es gran cosa... Espera, ¿sabes quién soy?!?",
  ui_story_5088_50880502_68_dialog_content = "¡O-Oye, vuelve aquí! ¡Tienes algo que explicar!",
  ui_story_5088_50880502_69_dialog_content = "¡No es justo si yo también no llego a conocer tu identidad! ¡Regresa!",
  ui_story_5088_50880601_1_dialog_content = "(Casta me trajo otro emblema. Al igual que el otro, no reconozco el diseño grabado en él.)",
  ui_story_5088_50880601_2_dialog_content = "(¿Son estas... notas musicales?)",
  ui_story_5088_50880601_3_dialog_content = "Solo para que lo sepas, si notamos algo malo en ti, te detendremos de inmediato.",
  ui_story_5088_50880601_4_dialog_content = "Esa es nuestra condición.",
  ui_story_5088_50880601_5_dialog_content = "No te preocupes, no me esforzaré demasiado.",
  ui_story_5088_50880601_6_dialog_content = "... Haré algo especial para que lo pruebes una vez que regreses de nuestro tiempo.",
  ui_story_5088_50880601_7_dialog_content = "Intenta no perderte en el sueño.",
  ui_story_5088_50880601_8_dialog_content = "... ¿Cuánto tiempo ha pasado desde entonces? ¿Pudo Czerny regresar a salvo a Eraveil?",
  ui_story_5088_50880601_9_dialog_content = "Rezo por su paz y espero que algún día nos olvide y viva una vida larga y feliz.",
  ui_story_5088_50880601_10_dialog_content = "Lo siento, Ludweiss, pero tendrás que esperar con nosotros un poco más...",
  ui_story_5088_50880601_11_dialog_content = "Ya no puedo seguir el rastro del tiempo. Muchas cosas están empezando a confundirse.",
  ui_story_5088_50880601_12_dialog_content = "Creo que estoy casi en mi límite... Necesito escribir una última advertencia para los descendientes del clan Longinus...",
  ui_story_5088_50880601_13_dialog_content = "\"Mantente alejado de las profundidades de la cueva.\"",
  ui_story_5088_50880601_14_dialog_content = "Ugh... Incluso hacer algo tan simple como esto me deja completamente exhausto...",
  ui_story_5088_50880601_15_dialog_content = "Debería haber sido completamente corrompido hasta ahora, pero aún no han parado.",
  ui_story_5088_50880601_16_dialog_content = "¿Cuánto tiempo más puedo mantener el control? ¿Es... realmente más allá de mí ahora?",
  ui_story_5088_50880601_17_dialog_content = "Me mentiste, Ludweiss.",
  ui_story_5088_50880601_18_dialog_content = "No... ¡¿Qué acaba de suceder?! ¿Cómo podría culpar a Ludweiss por esto?",
  ui_story_5088_50880601_19_dialog_content = "Mis amigos... También les he fallado...",
  ui_story_5088_50880601_20_dialog_content = "¿Es realmente imposible usar mis recuerdos para resistir el paso del tiempo?",
  ui_story_5088_50880601_21_dialog_content = "Por favor... Ayúdame...",
  ui_story_5088_50880601_22_dialog_content = "<color=#e8d9bb>El aire se llena de vítores fuertes y emocionados—</color>",
  ui_story_5088_50880601_23_dialog_content = "¿...?",
  ui_story_5088_50880601_24_dialog_content = "¡Alaba a los Guerreros Estelares, los héroes que erradicaron a los Eclipsites!",
  ui_story_5088_50880601_25_dialog_content = "Como tu rey, es un honor distinto presentarte estos premios.",
  ui_story_5088_50880601_26_dialog_content = "¡Héroes! ¡Héroes! ¡Héroes! ¡Héroes!",
  ui_story_5088_50880601_27_dialog_content = "Ah... El momento de nuestra mayor gloria...",
  ui_story_5088_50880601_28_dialog_content = "Haz tus votos ante los dioses y recibe el honor que has ganado con justicia.",
  ui_story_5088_50880601_29_dialog_content = "Adelante.",
  ui_story_5088_50880601_30_dialog_content = "Mientras quede una sola persona justa en este mundo, siempre estaré dispuesto a sacrificar mi vida por ella.",
  ui_story_5088_50880601_31_dialog_content = "Eres el noble escudo del reino, firme y dispuesto a defender a los débiles e inocentes. ¡Con los dioses como testigos, te otorgo el título de \"Regal\"!",
  ui_story_5088_50880601_32_dialog_content = "Juro convertirme en un río de fuego castigador, y purgar el mundo de maldad con mis llamas.",
  ui_story_5088_50880601_33_dialog_content = "Tus llamas arden más brillantes mientras lideras la carga en la batalla. Con los dioses como mis testigos, ¡te otorgo el título de \"Frostfire\"!",
  ui_story_5088_50880601_34_dialog_content = "¡Prometo preservar la esperanza y convertirme en la luz que guía a los que sufren y a los desesperados!",
  ui_story_5088_50880601_35_dialog_content = "Con tu brillante lanza, desgarras la oscuridad y anuncias el amanecer que se avecina. ¡Con los dioses como testigos, te otorgo el título de \"Requiem\"!",
  ui_story_5088_50880601_36_dialog_content = "Juro proteger cada momento de paz y aferrarme a mi bastón incluso si mi cuerpo perece.",
  ui_story_5088_50880601_37_dialog_content = "Tu luz tranquila calma la agitación de nuestro mundo en nombre de la paz. ¡Con los dioses como testigos, te otorgo el título de \"Mythos\"!",
  ui_story_5088_50880601_38_dialog_content = "¡¡¡Guau-hoo—!!!",
  ui_story_5088_50880601_39_dialog_content = "Es tu turno ahora, Capitán.",
  ui_story_5088_50880601_40_dialog_content = "Adelante y haz tu juramento, Aquiles.",
  ui_story_5088_50880601_41_dialog_content = "May ¡los dioses son testigos de mi juramento! Por el bien de mis seres queridos, prometo sacrificar todo hasta que el tiempo me reduzca a polvo!",
  ui_story_5088_50880601_42_dialog_content = "No tengo remordimientos—",
  ui_story_5088_50880601_43_dialog_content = "Ah... Solo fue un sueño... Uno raro y placentero, sin duda.",
  ui_story_5088_50880601_44_dialog_content = "¿Alguna vez podré ver cómo esas personas viven sus vidas pacíficas? ¿El reino todavía necesita que otros se sacrifiquen por él?",
  ui_story_5088_50880601_45_dialog_content = "<color=#e8d9bb>Grieta-</color>",
  ui_story_5088_50880601_46_dialog_content = "?",
  ui_story_5088_50880601_47_dialog_content = "¿Hay alguien ahí...?",
  ui_story_5088_50880601_48_dialog_content = "¿Eh? ¡Argh, no otra vez! ¿¡Cómo pudo cortarse justo ahí?!",
  ui_story_5088_50880601_49_dialog_content = "Bien PlayerName, eso es suficiente por el día. Hiciste un buen trabajo, ¡ahora ven a comer con nosotros!",
  ui_story_5088_50880601_50_dialog_content = "Puede que no lo parezca, pero Adras es un cocinero bastante decente!",
  ui_story_5088_50880601_51_dialog_content = "Tengo que serlo si quiero alimentar a esos niños correctamente... ¿Hmm?",
  ui_story_5088_50880601_52_dialog_content = "Yo...",
  ui_story_5088_50880601_53_dialog_content = "No te esfuerces demasiado. Está bien si no puedes recordar por ahora.",
  ui_story_5088_50880601_54_dialog_content = "...",
  ui_story_5088_50880601_55_dialog_content = "Vamos Adras, vamos a comer.",
  ui_story_5088_50880601_56_dialog_content = "Seguro.",
  ui_story_5088_50880601_57_dialog_content = "¡Eres el mejor, Adras! Ah, ¡me moría por comer esto durante los últimos dos mil años!",
  ui_story_5088_50880601_58_dialog_content = "¿Eh? ¡¿Quién está ahí?!",
  ui_story_5088_50880601_59_dialog_content = "¡Alto ahí mismo! Este lugar pertenece a los Wolverines Azules.",
  ui_story_5088_50880601_60_dialog_content = "Soy muy consciente de eso.",
  ui_story_5088_50880601_61_dialog_content = "Mi clan dejó algo en tu posesión. Estoy aquí para recuperarlo.",
  ui_story_5088_50880601_62_dialog_content = "¿Ah?",
  ui_story_5088_50880601_63_dialog_content = "¡Piérdete!",
  ui_story_5088_50880601_64_dialog_content = "Entonces supongo que tendré que mostrarte.",
  ui_story_5088_50880601_65_dialog_content = "Obsérvame—Porque yo soy la muerte.",
  ui_story_5088_50880602_1_dialog_content = "¡Vaya, seguro que llegaste temprano!",
  ui_story_5088_50880602_2_dialog_content = "La señora Jeriah me pidió que te entregara esto personalmente. Debe ser muy urgente.",
  ui_story_5088_50880602_3_dialog_content = "Hasta la próxima.",
  ui_story_5088_50880602_4_dialog_content = "Eh... señorita Mithra?",
  ui_story_5088_50880602_5_dialog_content = "¿Si?",
  ui_story_5088_50880602_6_dialog_content = "Estoy seguro de que este diario es realmente importante, pero... No necesito usar mis poderes en él para saber que pertenecía al clan Longinus.",
  ui_story_5088_50880602_7_dialog_content = "Ya estoy familiarizado con su longitud de onda.",
  ui_story_5088_50880602_8_dialog_content = "...",
  ui_story_5088_50880602_9_dialog_content = "Como Caelestita, discernir a diferentes personas es algo que me viene naturalmente.",
  ui_story_5088_50880602_10_dialog_content = "No siento a Jeriah en absoluto en este diario, pero sí siento una presencia muy familiar en él... La tuya.",
  ui_story_5088_50880602_11_dialog_content = "... No estaba completamente seguro ese día, ya que solo nos habíamos encontrado una vez antes de entonces.",
  ui_story_5088_50880602_12_dialog_content = "Pero cuando apareciste con Tweety al día siguiente, supe que eras tú.",
  ui_story_5088_50880602_13_dialog_content = "...",
  ui_story_5088_50880602_14_dialog_content = "Independientemente de las circunstancias, me salvaste y estoy agradecido por ello. Debe haber una razón para mantener tu identidad oculta, ¿verdad?",
  ui_story_5088_50880602_15_dialog_content = "En cuanto a este cuaderno... ¿Por qué usarías el nombre de Lady Jeriah para traérmelo?",
  ui_story_5088_50880602_16_dialog_content = "¿No es... importante para tu familia?",
  ui_story_5088_50880602_17_dialog_content = "Bien, hagamos un recuento rápido: ¿Cuántos de nosotros somos unos ingratos? Adelante, levanten la mano.",
  ui_story_5088_50880602_18_dialog_content = "...",
  ui_story_5088_50880602_19_dialog_content = "¡Bien! Parece que ninguno de nosotros es un ingrato egoísta.",
  ui_story_5088_50880602_20_dialog_content = "Ahora bien, ¡invitemos a Cynthia a decir unas palabras!",
  ui_story_5088_50880602_21_dialog_content = "... Vamos.",
  ui_story_5088_50880602_22_dialog_content = "Como se esperaba de un Caelestite.",
  ui_story_5088_50880602_23_dialog_content = "En este punto, puede que sepas incluso más de lo que yo sé. Parece que ya no hay razón para mantener esta farsa...",
  ui_story_5088_50880602_24_dialog_content = "Es tal como dijiste. Mi nombre es Mithra Longinus.",
  ui_story_5088_50880602_25_dialog_content = "Mi familia, el Clan Longinus, ha esperado pacientemente la llegada de un Celestita profetizado durante más de dos mil años.",
  ui_story_5088_50880602_26_dialog_content = "¿Dos mil años...?",
  ui_story_5088_50880602_27_dialog_content = "Jeje, dudo que incluso Lady Ludweiss supiera que su profecía tardaría tanto.",
  ui_story_5088_50880602_28_dialog_content = "Durante siglos, nuestro clan ha observado los cambios del mundo desde las sombras.",
  ui_story_5088_50880602_29_dialog_content = "Incluso después de todos estos años, ni una sola vez hemos olvidado nuestro propósito: evitar que alguien descubra los secretos de las estrellas.",
  ui_story_5088_50880602_30_dialog_content = "Y aún así, nunca has intentado detenerme de escarbar. ¿Es porque soy un Caelestite?",
  ui_story_5088_50880602_31_dialog_content = "Correcto. Y no solo eso, eres el Celestita de la profecía de Lady Ludweiss.",
  ui_story_5088_50880602_32_dialog_content = "Nuestro clan siempre ha permitido que los Caelestites investiguen nuestro secreto durante siglos, pero nunca hemos pedido explícitamente su ayuda. Estoy seguro de que sabes la razón por qué—",
  ui_story_5088_50880602_33_dialog_content = "El señor Aquiles no puede ser sellado, pero su corrupción tampoco puede ser revertida.",
  ui_story_5088_50880602_34_dialog_content = "Su cuerpo está infundido con el poder de la oscuridad. Los Caelestites ordinarios, limitados por sus grilletes innatos, nunca podrían esperar controlar ese tipo de poder.",
  ui_story_5088_50880602_35_dialog_content = "Intentar percibir su mente podría hacer que pierdas la tuya en el mejor de los casos, pero en el peor... El contragolpe de los susurros de la estrella caída podría matarte.",
  ui_story_5088_50880602_36_dialog_content = "... Los Caelestites en Eraveil son incomparables en su bondad y compasión. Por eso, pedirles ayuda sería lo mismo que poner sus vidas en juego.",
  ui_story_5088_50880602_37_dialog_content = "Sus posibilidades de salvación son escasas, y el Señor Aquiles se niega a permitir que más personas se sacrifiquen por su bien.",
  ui_story_5088_50880602_38_dialog_content = "¿Así que guardaste todo esto para ti en lugar de decírselo a los Celestitas?",
  ui_story_5088_50880602_39_dialog_content = "... Hay más razones que esa, pero sí. Al final, decidimos que esperar en silencio era la mejor opción.",
  ui_story_5088_50880602_40_dialog_content = "Antes de que Lady Ludweiss falleciera, afirmó haber visto a un Caelestite de miles de años en el futuro.",
  ui_story_5088_50880602_41_dialog_content = "Y al lado de ese Celestita estaba el Señor Adras, que había sido liberado de su sello.",
  ui_story_5088_50880602_42_dialog_content = "Desde entonces, hemos estado esperando pacientemente la realización de esta profecía.",
  ui_story_5088_50880602_43_dialog_content = "Pero incluso después de dos milenios y el trastorno de todo nuestro mundo... El día que hemos estado esperando aún no ha llegado.",
  ui_story_5088_50880602_44_dialog_content = "... Y ahora soy el único Caelestite que queda en el mundo. Durante los últimos diecisiete años o así, el mundo pensó que nuestro pueblo había sido completamente aniquilado... Pero entonces aparecí yo.",
  ui_story_5088_50880602_45_dialog_content = "Pero incluso después de eso, tu familia todavía se mantuvo fuerte y esperó.",
  ui_story_5088_50880602_46_dialog_content = "Yo... No hay nada fuerte en mí. De hecho, mi corazón aún está lleno de dudas...",
  ui_story_5088_50880602_47_dialog_content = "No creo que este supuesto \"salvador\" sea el único que puede liberarnos a nosotros y al Señor Aquiles de nuestro destino.",
  ui_story_5088_50880602_48_dialog_content = "A través de mis esfuerzos, finalmente me di cuenta de que mis antepasados ​​sentían lo mismo que yo y que enfrentamos obstáculos similares en nuestras vidas.",
  ui_story_5088_50880602_49_dialog_content = "Sin un Caelestite, incluso solo romper el sello en los Guerreros Estelares se volvería imposible.",
  ui_story_5088_50880602_50_dialog_content = "Pero aún así, tiene que haber algo que pueda hacer...",
  ui_story_5088_50880602_51_dialog_content = "Así que por eso me trajiste esto...",
  ui_story_5088_50880602_52_dialog_content = "Ese diario contiene los deseos y experiencias más profundos de Longinus a lo largo de los siglos.",
  ui_story_5088_50880602_53_dialog_content = "Como Caelestite, deberías poder obtener mucha orientación de él.",
  ui_story_5088_50880602_54_dialog_content = "Hacer esto tampoco es una violación de mi voto.",
  ui_story_5088_50880602_55_dialog_content = "Gracias. Cuidaré bien de ello y aprenderé todo lo que pueda.",
  ui_story_5088_50880602_56_dialog_content = "Ellos cuentan contigo... Y yo también.",
  ui_story_5088_50880602_57_dialog_content = "(Parece que ella piensa que todavía hay una oportunidad para salvar a Aquiles...)",
  ui_story_5088_50880602_58_dialog_content = "(No, eso no puede ser correcto. Si Aquiles realmente está muerto y los otros Guerreros Estelares fueron despertados por mí, entonces no hay razón para que ella se preocupe por eso.)",
  ui_story_5088_50880602_59_dialog_content = "(Pero como ella todavía está cumpliendo con sus deberes, entonces eso debe significar... Aquiles podría estar todavía vivo en algún lugar, lo que significa que todavía hay una posibilidad...)",
  ui_story_5088_50880602_60_dialog_content = "¡Tengo que volver a esa cueva!",
  ui_story_5088_50880602_61_dialog_content = "No está mal, PlayerName! ¿Cómo sabías que volveríamos a ese lugar?",
  ui_story_5088_50880602_62_dialog_content = "¿Eh? ¿Qué están haciendo ustedes?",
  ui_story_5088_50880602_63_dialog_content = "Nunca hemos sido personas malagradecidas.",
  ui_story_5088_50880602_64_dialog_content = "Alguien usó sus poderosas emociones para sellarnos.",
  ui_story_5088_50880602_65_dialog_content = "Y queremos saber quién era esa persona.",
  ui_story_5088_50880602_66_dialog_content = "Eso es correcto, y también queremos saber exactamente qué nos hizo.",
  ui_story_5088_50880602_67_dialog_content = "Si solo fue un simple acto de traición, no había necesidad de sellar también nuestras emociones.",
  ui_story_5088_50880602_68_dialog_content = "Pero... Somos nosotros quienes lo matamos... Si aprendes la historia detrás de esto...",
  ui_story_5088_50880602_69_dialog_content = "Él fue quien me enseñó que mis llamas pueden ser utilizadas para ayudar a la gente.",
  ui_story_5088_50880602_70_dialog_content = "Detuvo a los Eclipsites de destruir mi bosque, y me mostró cómo usar mis poderes para proteger este mundo.",
  ui_story_5088_50880602_71_dialog_content = "Me ayudó a derrotar a los que me hicieron daño y me dio una razón para seguir viviendo.",
  ui_story_5088_50880602_72_dialog_content = "Jeje, me sacó de la oscuridad y me dio un nuevo objetivo en la vida.",
  ui_story_5088_50880602_73_dialog_content = "Ustedes...",
  ui_story_5088_50880602_74_dialog_content = "Por lo que a nosotros respecta, ese tipo no es Claymore ni algún monstruo. Su nombre es Aquiles.",
  ui_story_5088_50880602_75_dialog_content = "No podemos permitirte hacer esto solo, y ciertamente no podemos fingir que él es malvado y dar por terminado el día.",
  ui_story_5088_50880602_76_dialog_content = "Aunque ahora lo recuerdo... Todavía no puedo evitar sentirme enojado...",
  ui_story_5088_50880602_77_dialog_content = "Pero aún necesitamos saber la verdad.",
  ui_story_5088_50880602_78_dialog_content = "Estos sentimientos son reales. Estamos seguros de ello.",
  ui_story_5088_50880602_79_dialog_content = "Je, debemos haberlo odiado mucho antes, ya que queríamos matarnos tan pronto como nos miramos a los ojos.",
  ui_story_5088_50880602_80_dialog_content = "Es cierto... A veces lo hacemos sonar trivial, pero la verdad del asunto es que nos atravesó con su espada sin decir una palabra.",
  ui_story_5088_50880602_81_dialog_content = "Era más fuerte que todos nosotros, e intentó matarnos sin decir nada... Luchar contra él era inevitable.",
  ui_story_5088_50880602_82_dialog_content = "Pero recuerda, nuestra razón para ir allí es aprender la verdad y confirmar si él aún está vivo o no. La única diferencia ahora es que nuestras mentes están más tranquilas y claras que antes.",
  ui_story_5088_50880602_83_dialog_content = "... Esos son nuestros pensamientos sobre el asunto, PlayerName.",
  ui_story_5088_50880602_84_dialog_content = "No importa cuán doloroso o cruel pueda ser, aún queremos saber la verdad.",
  ui_story_5088_50880602_85_dialog_content = "Por nuestras memorias, y por su honor.",
  ui_story_5088_50880602_86_dialog_content = "No podemos simplemente olvidarnos de todo así.",
  ui_story_5088_50880602_87_dialog_content = "Y debido a nuestros cuerpos inmortales, aún hay esperanza...",
  ui_story_5088_50880602_88_dialog_content = "Incluso si solo hay una pequeña posibilidad de salvarlo...",
  ui_story_5088_50880602_89_dialog_content = "Haremos todo lo posible para que suceda, incluso si él realmente nos traicionó en el pasado.",
  ui_story_5088_50880602_90_dialog_content = "¡Así que vamos todos juntos!",
  ui_story_5088_50880602_91_dialog_content = "...",
  ui_story_5088_50880602_92_dialog_content = "¡Está bien!",
  ui_story_5088_50880701_1_dialog_content = "<color=#e8d9bb>Según el cuaderno, el Clan Longinus finalmente tuvo éxito en descubrir el paradero de Czerny.</color>",
  ui_story_5088_50880701_2_dialog_content = "<color=#e8d9bb>Después de regresar a Eraveil, no mencionó a los Guerreros Estelares a nadie.</color>",
  ui_story_5088_50880701_3_dialog_content = "<color=#e8d9bb>Los padres de Czerny, quienes estaban aliviados de que su hijo finalmente había regresado a casa, lo recibieron con los brazos abiertos, y retomaron sus felices vidas juntos.</color>",
  ui_story_5088_50880701_4_dialog_content = "<color=#e8d9bb>Pero para entonces, la arrogancia que definía la personalidad de Czerny había sido reemplazada por un comportamiento tranquilo y gentil.</color>",
  ui_story_5088_50880701_5_dialog_content = "<color=#e8d9bb>Nunca participó en otra competencia, y en cambio dedicó sus esfuerzos a enseñar música.</color>",
  ui_story_5088_50880701_6_dialog_content = "<color=#e8d9bb>Sus obras más famosas eran tanto trágicas como solemnes, y pronto se convirtieron en las melodías emblemáticas de la festividad Celestita de Windelion.</color>",
  ui_story_5088_50880701_7_dialog_content = "<color=#e8d9bb>Más tarde en su vida, erigió una lápida sin nombre en el lugar donde todos los Caelestites fueron enterrados. Cada año en Windelion, visitaría la lápida y rendiría sus respetos.</color>",
  ui_story_5088_50880701_8_dialog_content = "<color=#e8d9bb>La mayoría de las personas no tenían idea de quién estaba de luto. Por respeto a este maestro de música, nadie se atrevió a preguntar o incluso a especular sobre quién podría ser.</color>",
  ui_story_5088_50880701_9_dialog_content = "<color=#e8d9bb>Después de la muerte de sus padres, Czerny se dedicó a la adopción y educación de los huérfanos de Eraveil, hijos e hijas de aquellos que habían sido exiliados. Con el tiempo, se convirtió en uno de los maestros más venerados y queridos de Eraveil.</color>",
  ui_story_5088_50880701_10_dialog_content = "Gracias al mapa de Queen Bethlehem, pudimos regresar a este lugar bastante rápido.",
  ui_story_5088_50880701_11_dialog_content = "Me pregunto cuál es su conexión con todo esto... No me lo dijo cuando pregunté...",
  ui_story_5088_50880701_12_dialog_content = "¡Oye Freya, acabo de recordar algo! Ese nombre, \"Bethlehem\"... ¿No lo tenía alguien en tu familia...?",
  ui_story_5088_50880701_13_dialog_content = "¡Guau! ¿Alguien salió de la cueva desde aquí? ¿Por qué nunca hemos notado esta apertura antes?",
  ui_story_5088_50880701_14_dialog_content = "Todo aquí está congelado sólidamente sin esperanza de descongelarse nunca...",
  ui_story_5088_50880701_15_dialog_content = "...",
  ui_story_5088_50880701_16_dialog_content = "?",
  ui_story_5088_50880701_17_dialog_content = "Nadie más está en la cueva, pero tampoco puedo sentir su presencia.",
  ui_story_5088_50880701_18_dialog_content = "... ¿Eso significa que realmente lo matamos la última vez?",
  ui_story_5088_50880701_19_dialog_content = "No seamos precipitados. Encontré algunos pergaminos desgastados en la otra entrada de la cueva.",
  ui_story_5088_50880701_20_dialog_content = "Esa debería haber sido la única entrada o salida, lo que significa que esta apertura debe haberse hecho después.",
  ui_story_5088_50880701_21_dialog_content = "¿Podría ser que él rompió las paredes de la cueva desde aquí y escapó?",
  ui_story_5088_50880701_22_dialog_content = "La formación mágica lo mantenía en su lugar, no a nosotros. Debería haber sido imposible para él abandonar este lugar.",
  ui_story_5088_50880701_23_dialog_content = "Entonces, tal vez un día estaba de muy mal humor, así que descargó su ira en la pared de la cueva y dejó este enorme agujero!",
  ui_story_5088_50880701_24_dialog_content = "Solo déjame intentar sentir estos fragmentos de pergamino primero.",
  ui_story_5088_50880701_25_dialog_content = "Está bien, pero solo porque pueda curarte con mi magia no significa que puedas esforzarte demasiado. ¿Entendido?",
  ui_story_5088_50880701_26_dialog_content = "Lo se.",
  ui_story_5088_50880701_27_option_content = "Escaneo psíquico",
  ui_story_5088_50880701_28_dialog_content = "Cuando la oscuridad pasa, las personas ya no necesitan las estrellas para guiar su camino.",
  ui_story_5088_50880701_29_dialog_content = "Ya no son soldados de ese reino.",
  ui_story_5088_50880701_30_dialog_content = "Día Siete: May Vivirás Libremente a Partir de Ahora.",
  ui_story_5088_50880701_31_dialog_content = "¿Quién está ahí? ¡Manténgase fuera de esta cueva!",
  ui_story_5088_50880701_32_dialog_content = "<color=#e8d9bb>Pat, pat, pat—</color>",
  ui_story_5088_50880701_33_dialog_content = "<color=#e8d9bb>Una joven niña Celestita limpia el polvo de la lápida sin nombre y coloca flores frescas ante ella.</color>",
  ui_story_5088_50880701_34_dialog_content = "...",
  ui_story_5088_50880701_35_dialog_content = "Maestro Czerny, limpié a la Lady Ludweiss de nuevo, tal como me pidió.",
  ui_story_5088_50880701_36_dialog_content = "Bien hecho, pequeño. Gracias.",
  ui_story_5088_50880701_37_dialog_content = "Pero... May ¿Por qué aún te ves tan triste, Maestro?",
  ui_story_5088_50880701_38_dialog_content = "Todos dicen que Windelion es un día para recordar a los queridos difuntos y ofrecerles nuestros pensamientos y oraciones.",
  ui_story_5088_50880701_39_dialog_content = "Así que tenemos que ser fuertes y mostrarles que estamos felices.",
  ui_story_5088_50880701_40_dialog_content = "...",
  ui_story_5088_50880701_41_dialog_content = "Eso es lo que nos enseñaste, Maestro Czerny...",
  ui_story_5088_50880701_42_dialog_content = "Pero cada Windelion, pareces estar en tanto dolor.",
  ui_story_5088_50880701_43_dialog_content = "Lo siento, pequeño... Pero aquellos por quienes lloro nunca escucharán mis pensamientos. El destino se ha encargado de eso.",
  ui_story_5088_50880701_44_dialog_content = "Eres un alma bondadosa. A pesar de tu corta edad, ya puedes sentir el dolor en el corazón de otras personas.",
  ui_story_5088_50880701_45_dialog_content = "Pero deberías saber que los bondadosos siempre sufrirán más que cualquier otro.",
  ui_story_5088_50880701_46_dialog_content = "Me acogiste y me criaste, Maestro Czerny. Por eso quiero ser justo como tú.",
  ui_story_5088_50880701_47_dialog_content = "Además, no te sentirás tan mal si puedo ayudarte, ¿verdad?",
  ui_story_5088_50880701_48_dialog_content = "¡¿?!",
  ui_story_5088_50880701_49_dialog_content = "Si me esfuerzo un poco más, tal vez algún día podrás vivir más felizmente...",
  ui_story_5088_50880701_50_dialog_content = "Y cuando llegue ese día... Quizás finalmente puedas decir adiós a Lady Ludweiss en Windelion. ¿Verdad, Maestro Czerny?",
  ui_story_5088_50880701_51_dialog_content = "Ah...",
  ui_story_5088_50880701_52_dialog_content = "<color=#e8d9bb>A medida que comienza a sonar la canción lúgubre de Windelion, Czerny cae de rodillas de dolor.</color>",
  ui_story_5088_50880701_53_dialog_content = "¿Por qué lloras, Maestro Czerny?",
  ui_story_5088_50880701_54_dialog_content = "¿Dije algo malo? Lo siento... Por favor, no llores.",
  ui_story_5088_50880701_55_dialog_content = "Yo... ¿Qué he estado haciendo todo este tiempo...?",
  ui_story_5088_50880701_56_dialog_content = "¿Qué pasa, Maestro Czerny? No has hecho nada malo, todos te aman!",
  ui_story_5088_50880701_57_dialog_content = "La música que tocas para nosotros es simplemente maravillosa, y tus lecciones son tan interesantes...",
  ui_story_5088_50880701_58_dialog_content = "Por favor, no llores más...",
  ui_story_5088_50880701_59_dialog_content = "En este punto, ¿puedo aún enfrentarme a todos ustedes con el corazón abierto? La sinfonía que les di...",
  ui_story_5088_50880701_60_dialog_content = "¿Quién está ahí? ¡A nadie se le permite entrar en la cueva!",
  ui_story_5088_50880701_61_dialog_content = "Wah... la estrella a la que todos vivimos para servir. Eres real...",
  ui_story_5088_50880701_62_dialog_content = "Longinus...?",
  ui_story_5088_50880701_63_dialog_content = "Levántate, ahora. ¿Por qué te ves tan... decaído?",
  ui_story_5088_50880701_64_dialog_content = "¿Te pasó algo terrible?",
  ui_story_5088_50880701_65_dialog_content = "Lumopolis está en un estado de gran tumulto, y nuestra familia ha sido implicada en medio del caos.",
  ui_story_5088_50880701_66_dialog_content = "Ahora, nos hemos convertido en nada más que las sombras tristes de la Baja Lumopolis.",
  ui_story_5088_50880701_67_dialog_content = "Nuestra familia enfrenta una agitación sin precedentes, y muchos han perdido su fe.",
  ui_story_5088_50880701_68_dialog_content = "Como el nuevo jefe de la familia, yo... debo llevar el peso de nuestro futuro.",
  ui_story_5088_50880701_69_dialog_content = "¿Necesitas alguna ayuda?",
  ui_story_5088_50880701_70_dialog_content = "No, no necesito nada, mi señor.",
  ui_story_5088_50880701_71_dialog_content = "En esta noche más oscura, solo deseo rendir mis respetos...",
  ui_story_5088_50880701_72_dialog_content = "Por tu orden, dos generaciones de jefes de familia han venido y se han ido sin ser agraciados por tu presencia. Es por eso que muchos creen que eres solo una leyenda de nuestro linaje.",
  ui_story_5088_50880701_73_dialog_content = "Especialmente en tiempos tan sombríos, nadie cree en la grandeza que una vez servimos... Han comenzado a perder la esperanza.",
  ui_story_5088_50880701_74_dialog_content = "Incluso yo... siento una vergonzosa duda en mi corazón.",
  ui_story_5088_50880701_75_dialog_content = "Por el bien del clan, deberías rendirte. No te culparé.",
  ui_story_5088_50880701_76_dialog_content = "Pero ahora, te he visto.",
  ui_story_5088_50880701_77_dialog_content = "Terminaré con todas las disputas. La sombra sobre Longinus no está sin una estrella guía.",
  ui_story_5088_50880701_78_dialog_content = "Tú...",
  ui_story_5088_50880701_79_dialog_content = "Regresaré a Lumopolis, liderando a mi clan en las sombras, continuando desafiando ese destino insondable.",
  ui_story_5088_50880701_80_dialog_content = "... ¿Quién eres tú para Dominic?",
  ui_story_5088_50880701_81_dialog_content = "¿Czerny?",
  ui_story_5088_50880701_82_dialog_content = "El Guerrero Estelar te reconoce... ¿Eres el Celestita que una vez nos echó una mano? Dominic es mi tío.",
  ui_story_5088_50880701_83_dialog_content = "¿Presté una mano? ¿Yo?",
  ui_story_5088_50880701_84_dialog_content = "¡Jajajaja!",
  ui_story_5088_50880701_85_dialog_content = "¿En qué locura me he involucrado? Claramente, soy el Caelestite, el que ayudaría a Aquiles, sin embargo, no he logrado nada.",
  ui_story_5088_50880701_86_dialog_content = "¿Por qué has vuelto...?",
  ui_story_5088_50880701_87_dialog_content = "Quería visitarte, Aquiles.",
  ui_story_5088_50880701_88_dialog_content = "No puedo soltarme, ni puedo enfrentar la verdad.",
  ui_story_5088_50880701_89_dialog_content = "Pero cuando escuché todo esto en la entrada de la cueva... Yo... no pude evitar conmoverme por la convicción de este.",
  ui_story_5088_50880701_90_dialog_content = "Debería continuar atendiendo a este asunto pendiente.",
  ui_story_5088_50880702_1_dialog_content = "<color=#e8d9bb>Si ves esto, gente del futuro, por favor presencia mi registro final.</color>",
  ui_story_5088_50880702_2_dialog_content = "<color=#e8d9bb>Debido al empeoramiento de la condición de Aquiles, debo distanciarme un poco y continuar con el trabajo de años pasados.</color>",
  ui_story_5088_50880702_3_dialog_content = "<color=#e8d9bb>Ahora estoy más tranquilo, lo suficientemente tranquilo para dejar sistemáticamente esta información.</color>",
  ui_story_5088_50880702_4_dialog_content = "<color=#e8d9bb>Después de esta página, debería haber cuatrocientas cuarenta y tres páginas de registros de investigación.</color>",
  ui_story_5088_50880702_5_dialog_content = "<color=#e8d9bb>Pero incluso con todos estos pergaminos, apenas he comenzado a progresar.</color>",
  ui_story_5088_50880702_6_dialog_content = "<color=#e8d9bb>Ay, ahora me quedo sin tiempo...</color>",
  ui_story_5088_50880702_7_dialog_content = "Tos, tos... Tos, tos, tos...",
  ui_story_5088_50880702_8_dialog_content = "Has estado tosiendo más de lo normal últimamente.",
  ui_story_5088_50880702_9_dialog_content = "Hace demasiado frío aquí. Deberías irte y ver a un médico.",
  ui_story_5088_50880702_10_dialog_content = "Esto no es una enfermedad, Aquiles. Esto es... tos, tos... vejez.",
  ui_story_5088_50880702_11_dialog_content = "...",
  ui_story_5088_50880702_12_dialog_content = "El tiempo es verdaderamente despiadado.",
  ui_story_5088_50880702_13_dialog_content = "Pensé que me quedaba mucho tiempo...",
  ui_story_5088_50880702_14_dialog_content = "A esta edad, les envidio a todos. Si tan solo pudiera vivir para siempre...",
  ui_story_5088_50880702_15_dialog_content = "...",
  ui_story_5088_50880702_16_dialog_content = "Aquiles, ¿sigues despierto?",
  ui_story_5088_50880702_17_dialog_content = "...Sí.",
  ui_story_5088_50880702_18_dialog_content = "Si oigo al monstruo en mi corazón acercándose, rugiré al instante, Czerny.",
  ui_story_5088_50880702_19_dialog_content = "Solo estaba reflexionando.",
  ui_story_5088_50880702_20_dialog_content = "Podría ser tan impotente como tú, y mi cerebro se está ralentizando. Si no doy todo lo que tengo, bueno, ni siquiera puedo pensar.",
  ui_story_5088_50880702_21_dialog_content = "Solo somos un par de viejos fósiles.",
  ui_story_5088_50880702_22_dialog_content = "Jajaja... Es raro escucharte bromear.",
  ui_story_5088_50880702_23_dialog_content = "Pero no he logrado nada, y ahora soy viejo y estoy muriendo... Al final, parece que no era el Caelestite de la profecía.",
  ui_story_5088_50880702_24_dialog_content = "Czerny, no necesitas desesperarte. El tiempo puede traer el crepúsculo, pero tú has rugido contra él.",
  ui_story_5088_50880702_25_dialog_content = "Sin ti, podría haberme rendido hace mucho tiempo.",
  ui_story_5088_50880702_26_dialog_content = "¿Quieres decir que mi parpadeo fugaz te ayudó a resistir la abrumadora oscuridad?",
  ui_story_5088_50880702_27_dialog_content = "En efecto. Incluso yo poseo mi justa parte de debilidades. Sin el apoyo de un amigo como tú, no podría haber permanecido lúcido durante tanto tiempo.",
  ui_story_5088_50880702_28_dialog_content = "Entiendo tu determinación, así que ya no te instaré a irte. Espero que entiendas que ya has trabajado verdaderos milagros para mí.",
  ui_story_5088_50880702_29_dialog_content = "Me diste esperanza, ¿no es suficiente para alejar la oscuridad?",
  ui_story_5088_50880702_30_dialog_content = "Esperanza...",
  ui_story_5088_50880702_31_dialog_content = "Justo como Ludweiss me dio esperanza con la profecía, infundiéndome el coraje para seguir adelante.",
  ui_story_5088_50880702_32_dialog_content = "Has hecho lo mismo.",
  ui_story_5088_50880702_33_dialog_content = "... ¡Ah!",
  ui_story_5088_50880702_34_dialog_content = "Sí... eso debe ser...",
  ui_story_5088_50880702_35_dialog_content = "¡Todo este tiempo, mi investigación estaba enfocada en la dirección equivocada!",
  ui_story_5088_50880702_36_dialog_content = "¿Qué quieres decir?",
  ui_story_5088_50880702_37_dialog_content = "Estaba tan obsesionado con lograr un final perfecto que pasé por alto el hecho de que todavía tenemos una forma de llegar a un compromiso!",
  ui_story_5088_50880702_38_dialog_content = "¡Lo más importante es tu conciencia! ¡Mientras preserve tu conciencia, sé que será suficiente!",
  ui_story_5088_50880702_39_dialog_content = "He estado investigando cómo detener tu erosión y restaurarte a tu antiguo yo, pero me detuvo el problema de tu poder.",
  ui_story_5088_50880702_40_dialog_content = "¡Pero la verdad es que no necesitamos tu cuerpo, solo necesitamos encontrar una manera de preservar tu conciencia!",
  ui_story_5088_50880702_41_dialog_content = "¿Qué significa eso?",
  ui_story_5088_50880702_42_dialog_content = "Tú, como los demás, has pasado por extensas mejoras, tu cuerpo lleno del poder de la oscuridad.",
  ui_story_5088_50880702_43_dialog_content = "Fueron afectados por la erosión hasta cierto punto, pero después de ser sellados, esa oscuridad fue mantenida a raya por sus emociones más fuertes.",
  ui_story_5088_50880702_44_dialog_content = "Sus cuerpos, aunque habían sufrido la transformación de Eclipsite, se estabilizaron gradualmente. ¡Con la ayuda de tu formación mágica, esa erosión por rechazo no volverá a suceder!",
  ui_story_5088_50880702_45_dialog_content = "¡Tú también! Incluso si no puedo sellarte, ¿qué tal si extraigo tu conciencia de tu cuerpo? ¡Tu cuerpo puede permanecer en la formación mágica!",
  ui_story_5088_50880702_46_dialog_content = "Tal vez un día, tu cuerpo se adaptará a la erosión y se estabilizará, y ese oscuro poder no te volverá loco.",
  ui_story_5088_50880702_47_dialog_content = "¿Quieres decir que tienes una forma de extraer y preservar mi conciencia?",
  ui_story_5088_50880702_48_dialog_content = "Investigar esto será más fácil que curarte directamente.",
  ui_story_5088_50880702_49_dialog_content = "La parte más difícil será encontrar un recipiente que pueda contener temporalmente a \"tú\" sin ningún tipo de rechazo.",
  ui_story_5088_50880702_50_dialog_content = "¡Jajaja! ¡Esto realmente es un rayo de esperanza!",
  ui_story_5088_50880702_51_dialog_content = "Aquiles, lo que Ludweiss nos dejó no fue una <color=#FFB400>profecía</color>, ¡sino <color=#FFB400>esperanza</color>!",
  ui_story_5088_50880702_52_dialog_content = "<color=#FFB400>Esperanza</color>...",
  ui_story_5088_50880702_53_dialog_content = "De lo contrario, ¿por qué se sacrificaría sabiendo que ella no sería la que resolvería este problema?",
  ui_story_5088_50880702_54_dialog_content = "Además, su método no era perfecto.",
  ui_story_5088_50880702_55_dialog_content = "Pero porque creía en el futuro, creía en la esperanza, se sacrificó voluntariamente para allanar el camino para el que la seguiría.",
  ui_story_5088_50880702_56_dialog_content = "¡Soy yo quien ahora la sigue!",
  ui_story_5088_50880702_57_dialog_content = "¡Jajaja! Aquiles, ¡soy yo quien ahora la sigue!",
  ui_story_5088_50880702_58_dialog_content = "Puede que no sea yo de quien se habla en la profecía, ¡pero aún puedo ser de quien se habla en la profecía!",
  ui_story_5088_50880702_59_dialog_content = "Parece que finalmente te has dado cuenta de la luz que sostienes dentro.",
  ui_story_5088_50880702_60_dialog_content = "¡Y mi fe será transmitida al próximo Caelestite!",
  ui_story_5088_50880702_61_dialog_content = "Pasaremos una llama en la oscuridad del desierto hasta que nuestra luz ilumine esta tierra de desesperación!",
  ui_story_5088_50880702_62_dialog_content = "Ludweiss, por fin entiendo tus últimas palabras... ¡¡¡Por fin entiendo tus últimas palabras!!!",
  ui_story_5088_50880702_63_dialog_content = "No necesito completar todo yo mismo, solo necesito hacer lo que pueda y luego pasarlo al siguiente Caelestite.",
  ui_story_5088_50880702_64_dialog_content = "¡También registraré mis percepciones, convirtiéndome en un mensajero para las futuras generaciones!",
  ui_story_5088_50880702_65_dialog_content = "¡Cien años, mil años, dos mil años a partir de ahora! Un día, cuando tu cuerpo se estabilice, un Celestita traerá tu conciencia de vuelta!",
  ui_story_5088_50880702_66_dialog_content = "Confío en ti, mi amigo. ¿Qué necesitas que haga?",
  ui_story_5088_50880702_67_dialog_content = "<color=#e8d9bb>Entonces, a ti que estás leyendo esto, mi sucesor, por favor, presta atención a mis palabras.</color>",
  ui_story_5088_50880702_68_dialog_content = "<color=#e8d9bb>Una vez fui demasiado ambicioso, creyendo que yo era el salvador elegido, y por eso fracasé en aquel entonces...</color>",
  ui_story_5088_50880702_69_dialog_content = "<color=#e8d9bb>Pero también tuve éxito, ya que hice todo lo que pude y te pasé la antorcha.</color>",
  ui_story_5088_50880702_70_dialog_content = "<color=#e8d9bb>Ahora, si estás dispuesto, no importa cuánto o cuán poco puedas hacer, espero sinceramente que puedas ayudar a mantener viva esta llama.</color>",
  ui_story_5088_50880702_71_dialog_content = "<color=#e8d9bb>Nosotros, los que vinimos antes que tú, siempre estaremos agradecidos por tu ayuda.</color>",
  ui_story_5088_50880702_72_dialog_content = "<color=#e8d9bb>Y si el hielo y la nieve se derriten, y la primavera llega a esta tierra de desesperación, por favor ven aquí.</color>",
  ui_story_5088_50880702_73_dialog_content = "<color=#e8d9bb>Claymore espera. Por favor dile, \"La primavera ha llegado.\"</color>",
  ui_story_5088_50880801_1_dialog_content = "Muéstrate.",
  ui_story_5088_50880801_2_dialog_content = "... ¿Cuándo notaste que estaba aquí?",
  ui_story_5088_50880801_3_dialog_content = "Desde el principio.",
  ui_story_5088_50880801_4_dialog_content = "No te dejes engañar por el bastón y la apariencia perpetuamente desconcertada de Cynthia.",
  ui_story_5088_50880801_5_dialog_content = "Ella es la mejor exploradora en nuestro equipo.",
  ui_story_5088_50880801_6_dialog_content = "Solía disfrazar su bastón como un arco para evitar molestar a los magos. Al igual que tú, le gusta permanecer oculta.",
  ui_story_5088_50880801_7_dialog_content = "... Lo siento por seguirte. Prometo, mis intenciones son buenas. Mi nombre es Mithra Longinus, y tengo una misión.",
  ui_story_5088_50880801_8_dialog_content = "¿Una chica Longinus? ¿Un descendiente de Anthony, supongo?",
  ui_story_5088_50880801_9_dialog_content = "¿Recuerdas a mi antepasado?",
  ui_story_5088_50880801_10_dialog_content = "Jaja, siempre estaba dispuesto a pasar tiempo con nosotros, las criaturas. Pensamos que simplemente buscaba comida gratis. Déjame decirte, nos dejó una gran impresión.",
  ui_story_5088_50880801_11_dialog_content = "Ahora, después de dos mil años, nos encontramos con otro Longinus.",
  ui_story_5088_50880801_12_dialog_content = "Anthony... ¿vivió una vida feliz?",
  ui_story_5088_50880801_13_dialog_content = "... Estaba muy feliz. Después de recibir la bendición del Señor Aquiles, sonrió y falleció. Fue enterrado cerca con honor.",
  ui_story_5088_50880801_14_dialog_content = "Para lograr grandes hazañas y dejar este mundo en el abrazo de sus seres queridos... él fue bendecido.",
  ui_story_5088_50880801_15_dialog_content = "Han pasado dos mil años, pero finalmente hemos recibido buenas noticias.",
  ui_story_5088_50880801_16_dialog_content = "... Longinus, podemos adivinar cuál es esa misión que te ata.",
  ui_story_5088_50880801_17_dialog_content = "En este punto, solo tú conoces el destino de esa persona...",
  ui_story_5088_50880801_18_dialog_content = "Pero parece que tú, como yo, abrazas voluntariamente estos grilletes.",
  ui_story_5088_50880801_19_dialog_content = "¿Si lo solicitamos, puedes decirnos?",
  ui_story_5088_50880801_20_dialog_content = "La misión de nuestra familia es proteger los secretos de las estrellas y no dejar que nadie se acerque a ellas.",
  ui_story_5088_50880801_21_dialog_content = "Pero si este es el mandato de los Guerreros Estelares, hablaré de mi misión.",
  ui_story_5088_50880801_22_dialog_content = "Pero antes de eso, solo quiero decir... ya me has ayudado.",
  ui_story_5088_50880801_23_dialog_content = "¡Vaya, estás despierto!",
  ui_story_5088_50880801_24_dialog_content = "Esos eran solo los registros más triviales de nuestro clan. Cuánto has visto se debe a tu propia convicción.",
  ui_story_5088_50880801_25_dialog_content = "Correcto... Vi la perseverancia del clan Longinus a través de las generaciones.",
  ui_story_5088_50880801_26_dialog_content = "... Creo que la mejor manera de describirlo sería \"inflexible hasta el final.\"",
  ui_story_5088_50880801_27_dialog_content = "Y no estoy hablando solo de una persona, esta cosa de \"inflexible hasta el final\" se aplica a todo el clan Longinus.",
  ui_story_5088_50880801_28_dialog_content = "Así que creo que la razón por la que todos tienen una fe tan fuerte es incluso la razón por la que sigues adelante hasta el día de hoy...",
  ui_story_5088_50880801_29_dialog_content = "Debe ser porque Aquiles todavía está por aquí en algún lugar.",
  ui_story_5088_50880801_30_dialog_content = "¿Así que volviste aquí para buscar pistas?",
  ui_story_5088_50880801_31_dialog_content = "Correcto, y ya he visto la ubicación final. Quiero ver lo que dejó el Sr. Czerny.",
  ui_story_5088_50880801_32_dialog_content = "Entonces, ¿qué estamos esperando?",
  ui_story_5088_50880801_33_dialog_content = "¡Vaya! ¡Friegson está tan ansioso de repente! ¿Ansioso por un duelo con Aquiles, eh?",
  ui_story_5088_50880801_34_dialog_content = "... Basta de parloteo. Vamos.",
  ui_story_5088_50880801_35_dialog_content = "Ya estamos acá.",
  ui_story_5088_50880801_36_dialog_content = "Hmm, a primera vista, nada resalta. Y al observar más de cerca... aún nada.",
  ui_story_5088_50880801_37_dialog_content = "Sin embargo, a través de la lente de la magia, se reúne aquí un intrigante poder incoloro.",
  ui_story_5088_50880801_38_dialog_content = "En efecto. Esta es la formación mágica de Aquiles.",
  ui_story_5088_50880801_39_dialog_content = "¿Podemos forzarlo a abrir con nuestra magia?",
  ui_story_5088_50880801_40_dialog_content = "Vale la pena intentarlo.",
  ui_story_5088_50880801_41_dialog_content = "No... No hay necesidad de ir a tales extremos.",
  ui_story_5088_50880801_42_dialog_content = "Señorita Mithra, por favor abra el sello.",
  ui_story_5088_50880801_43_dialog_content = "Tienes la llave, ¿verdad?",
  ui_story_5088_50880801_44_dialog_content = "...",
  ui_story_5088_50880801_45_dialog_content = "Cuando mi antepasado falleció, el Señor Aquiles le dio a nuestra familia un amuleto.",
  ui_story_5088_50880801_46_dialog_content = "La Cresta de Estrella...",
  ui_story_5088_50880801_47_dialog_content = "Una formación mágica autosuficiente del material más delicado, el mayor honor que el Señor Aquiles otorgó a nuestro clan.",
  ui_story_5088_50880801_48_dialog_content = "Probablemente pretendía que usáramos este poder para protegernos, pero los jefes de la familia Longinus siempre han sido reacios a usarlo.",
  ui_story_5088_50880801_49_dialog_content = "Así se convirtió en un símbolo de nuestro voto, una reliquia familiar.",
  ui_story_5088_50880801_50_dialog_content = "Nunca pensé que algún día se pondría en uso.",
  ui_story_5088_50880801_51_dialog_content = "¿Esto violará tu juramento?",
  ui_story_5088_50880801_52_dialog_content = "No, porque este es tu deseo y la intención original del clan Longinus.",
  ui_story_5088_50880801_53_dialog_content = "...Gracias.",
  ui_story_5088_50880801_54_dialog_content = "No, Lady Friegson, por favor no me agradezcas...",
  ui_story_5088_50880801_55_dialog_content = "Nunca soñé que alguien nos protegería durante dos milenios.",
  ui_story_5088_50880801_56_dialog_content = "Mithra, por todo esto, por favor acepta mi gratitud.",
  ui_story_5088_50880801_57_dialog_content = "De lo contrario, Friegson puede sentirse algo incómodo.",
  ui_story_5088_50880801_58_dialog_content = "Entiendo... Entonces, romperé el sello.",
  ui_story_5088_50880801_59_dialog_content = "<color=#e8d9bb>Mithra se quita su collar, revelando su verdadera forma—un Cresta de Estrella.</color>",
  ui_story_5088_50880801_60_dialog_content = "<color=#e8d9bb>Entonces, ella invoca la punta de una lanza del Cresta Estrella.</color>",
  ui_story_5088_50880801_61_dialog_content = "Esto es-!",
  ui_story_5088_50880801_62_dialog_content = "¿Eraveil?",
  ui_story_5088_50880801_63_dialog_content = "¿C-Cómo es esto posible?",
  ui_story_5088_50880801_64_dialog_content = "Vaya, qué hermosas llanuras... Mira, dientes de león de Eraveil.",
  ui_story_5088_50880801_65_dialog_content = "Incluso la Torre Blanca se mantiene, restaurada en todo su esplendor.",
  ui_story_5088_50880801_66_dialog_content = "Parece que debemos aventurarnos allí para entender todo.",
  ui_story_5088_50880801_67_dialog_content = "Sin embargo, no parece ser tan sereno como Eraveil lo fue una vez.",
  ui_story_5088_50880801_68_dialog_content = "¿Eh? Son estos...",
  ui_story_5088_50880802_1_dialog_content = "¿Podrían ser estas las defensas de Aquiles?",
  ui_story_5088_50880802_2_dialog_content = "Quizás deberíamos dirigirnos primero al Obelisco del Retorno.",
  ui_story_5088_50880802_3_dialog_content = "Cuanto más nos acercamos, más extraña se vuelve esta sensación en mi corazón.",
  ui_story_5088_50880802_4_dialog_content = "Cynthia, Freya, ¿tú también lo sientes?",
  ui_story_5088_50880802_5_dialog_content = "¿Podría ser aún la influencia persistente de la formación mágica?",
  ui_story_5088_50880802_6_dialog_content = "No, se siente como si la cresta estuviera resonando.",
  ui_story_5088_50880802_7_dialog_content = "Mi espada... parece estar hablándome de... recuerdos...",
  ui_story_5088_50880802_8_dialog_content = "¡¿?!",
  ui_story_5088_50880802_9_dialog_content = "Parece que lo hemos encontrado.",
  ui_story_5088_50880802_10_dialog_content = "Verificando información biológica, espere por favor.",
  ui_story_5088_50880802_11_dialog_content = "Esto es exactamente lo que vi una vez antes...",
  ui_story_5088_50880802_12_dialog_content = "Caelestita detectada, bienvenida a Wonderland.",
  ui_story_5088_50880802_13_dialog_content = "Parece que nuestro anfitrión está listo para darnos la bienvenida.",
  ui_story_5088_50880802_14_dialog_content = "Ahora se reproducen las últimas palabras de Czerny. Por favor, escucha durante tu ascenso.",
  ui_story_5088_50880802_15_dialog_content = "Si estás escuchando esto, significa que tuve éxito, y un Celestita de una nueva era ha sido guiado aquí.",
  ui_story_5088_50880802_16_dialog_content = "Bien hecho, héroe del futuro.",
  ui_story_5088_50880802_17_dialog_content = "Para conservar la energía restante de esta estructura, seré breve... En resumen, hay un Colossus dañado detrás de esta torre.",
  ui_story_5088_50880802_18_dialog_content = "Fue el vehículo que Aquiles y yo usamos para venir aquí...",
  ui_story_5088_50880802_19_dialog_content = "Nunca pensé que llegaría aquí en mis años crepusculares... el Coloso...",
  ui_story_5088_50880802_20_dialog_content = "Lo siento, Maestro Czerny, por favor elige un Coloso rápidamente... No puedo aguantar mucho más, todos podrían descubrir pronto que estás aquí.",
  ui_story_5088_50880802_21_dialog_content = "Mantiz o 6#S%—puedes elegir cualquiera.",
  ui_story_5088_50880802_22_dialog_content = "¡No, elijo ese—Fortez!",
  ui_story_5088_50880802_23_dialog_content = "Pero ese es el <color=#FFB400>Coloso de Guerra</color> sellado.",
  ui_story_5088_50880802_24_dialog_content = "Sí, eso es exactamente lo que necesito.",
  ui_story_5088_50880802_25_dialog_content = "Investigué durante mucho tiempo para descubrir por qué estaba sellado. Puede... generar Eclipsites. Quizás nuestro clan cometió grandes pecados en el pasado.",
  ui_story_5088_50880802_26_dialog_content = "Pero los Celestitas ya no necesitan un Colossus de Guerra, así que bien podría ayudar a destruir el último dispositivo generador de Eclipsites.",
  ui_story_5088_50880802_27_dialog_content = "Entonces por favor, Maestro, llévatelo.",
  ui_story_5088_50880802_28_dialog_content = "Fortez, atiende mi llamado, acepta mi orden, déjame navegarte... ¿Hmm?",
  ui_story_5088_50880802_29_dialog_content = "¿Está desprovisto de conciencia?",
  ui_story_5088_50880802_30_dialog_content = "¿Cómo puede ser eso? ¿Será que cuando fue sellado, su conciencia fue borrada deliberadamente?",
  ui_story_5088_50880802_31_dialog_content = "Es muy probable. Los Colosos de Guerra no nos obedecerían, los traidores que le dimos la espalda a la guerra. Quizás ahora es simplemente nuestro prisionero.",
  ui_story_5088_50880802_32_dialog_content = "¡Entonces, seré yo quien te navegue!",
  ui_story_5088_50880802_33_dialog_content = "Maestro Czerny... ¿volverás?",
  ui_story_5088_50880802_34_dialog_content = "¡Jajaja, sí! Un día, volveré para enfrentar mi castigo.",
  ui_story_5088_50880802_35_dialog_content = "No importa cuánto tiempo tome, me esforzaré por regresar.",
  ui_story_5088_50880802_36_dialog_content = "Si no puedes esperar por mí, toca mi música en Windelion para guiarme de regreso.",
  ui_story_5088_50880802_37_dialog_content = "Maestro Czerny...",
  ui_story_5088_50880802_38_dialog_content = "\"No vayas suavemente a esa buena noche.\"",
  ui_story_5088_50880802_39_dialog_content = "\"La vejez debería arder y desvariar al final del día.\"",
  ui_story_5088_50880802_40_dialog_content = "\"Rabia, rabia contra el morir de la luz...\"",
  ui_story_5088_50880802_41_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_5088_50880802_42_dialog_content = "¡¿?!",
  ui_story_5088_50880802_43_dialog_content = "He vuelto, Aquiles... Accidentalmente hice un agujero bastante grande. Lo siento...",
  ui_story_5088_50880802_44_dialog_content = "Tú... ¿Qué está pasando aquí?",
  ui_story_5088_50880802_45_dialog_content = "Este Colossus puede usar tu información genética para crear un nuevo cuerpo.",
  ui_story_5088_50880802_46_dialog_content = "Digo crear, pero es solo copiar o usar el término designado por el dispositivo de control—\"clonación.\"",
  ui_story_5088_50880802_47_dialog_content = "De esta manera, tu conciencia no será rechazada.",
  ui_story_5088_50880802_48_dialog_content = "Sin embargo, crear un cuerpo nuevo lleva tiempo, y no puedo asegurar que el nuevo cuerpo no enfrentará erosión. Puede que se requiera una observación adicional.",
  ui_story_5088_50880802_49_dialog_content = "El Colossus es demasiado conspicuo para permanecer aquí. Primero debo reunir tu conciencia usando la Plantilla de Eco que traje para alojarte.",
  ui_story_5088_50880802_50_dialog_content = "Si te preguntara si eres capaz de tener éxito en todo esto, podría parecer que no confío en ti.",
  ui_story_5088_50880802_51_dialog_content = "Pero... ¿has confirmado nuestras dudas?",
  ui_story_5088_50880802_52_dialog_content = "¿La conciencia de uno equivale a su alma?",
  ui_story_5088_50880802_53_dialog_content = "Memoria, pensamiento, naturaleza, juntos, forman mi ser.",
  ui_story_5088_50880802_54_dialog_content = "¿Es esta conciencia mi alma?",
  ui_story_5088_50880802_55_dialog_content = "He probado la teoría.",
  ui_story_5088_50880802_56_dialog_content = "¡Tú... Czerny, qué has hecho?!",
  ui_story_5088_50880802_57_dialog_content = "He abandonado mi cuerpo y almacenado mi conciencia aquí.",
  ui_story_5088_50880802_58_dialog_content = "En Fortez.",
  ui_story_5088_50880802_59_dialog_content = "¡¿?!",
  ui_story_5088_50880802_60_dialog_content = "Para confirmar todas las especulaciones que teníamos, realicé este experimento, después de todo, no soy más que un anciano.",
  ui_story_5088_50880802_61_dialog_content = "La respuesta es, mi alma permanece firme, aún ansiosa por ayudarte.",
  ui_story_5088_50880802_62_dialog_content = "Czerny...",
  ui_story_5088_50880802_63_dialog_content = "Ahora ya no soy un Caelestite y no puedo utilizar plenamente mis habilidades psíquicas.",
  ui_story_5088_50880802_64_dialog_content = "Pero afortunadamente, eres hábil en sellar y conjurar formaciones mágicas.",
  ui_story_5088_50880802_65_dialog_content = "Te ayudaré a transferir tu conciencia al Eco Plantilla del Coloso.",
  ui_story_5088_50880802_66_dialog_content = "¡Entonces... volaremos a Eraveil!",
  ui_story_5088_50880802_67_dialog_content = "Incluso si nuestras voces no pueden alcanzarlos, algún día, alguien será guiado hacia nosotros y nos desatará.",
  ui_story_5088_50880802_68_dialog_content = "... Ahora entiendo tu determinación.",
  ui_story_5088_50880802_69_dialog_content = "En este último momento, me siento obligado a dejar algo atrás.",
  ui_story_5088_50880901_1_dialog_content = "<color=#e8d9bb>¡Click! El flujo de energía dentro de la Torre Blanca se corta de repente, y las palabras de Czerny se desvanecen.</color>",
  ui_story_5088_50880901_2_dialog_content = "Iré al centro y echaré un vistazo.",
  ui_story_5088_50880901_3_dialog_content = "¿Cómo planeas llegar allí? Es muy peligroso.",
  ui_story_5088_50880901_4_dialog_content = "<color=#e8d9bb>Mithra no responde y simplemente extiende sus alas. Sus alas han estado esperando todo este tiempo, ocultas bajo su modesta capa.</color>",
  ui_story_5088_50880901_5_dialog_content = "Entonces, todo lo que necesitamos hacer es volar... Oh, casi lo olvido, ella es de la Unión de Mensajeros.",
  ui_story_5088_50880901_6_dialog_content = "Aquellos que se esconden más a menudo que no necesitan reprimirse sin compromiso. Sus alas parecen ser prueba de este hecho.",
  ui_story_5088_50880901_7_dialog_content = "¿Puedes manejarlo por tu cuenta? ¿Necesitas mi ayuda? Soy bueno con los rayos...",
  ui_story_5088_50880901_8_dialog_content = "He encontrado la línea defectuosa. Solo espera ahí abajo.",
  ui_story_5088_50880901_9_dialog_content = "He hecho innumerables trabajos como este antes, así que no hay nada de qué preocuparse.",
  ui_story_5088_50880901_10_dialog_content = "Si no la vigilas, es como si desapareciera por completo de la historia.",
  ui_story_5088_50880901_11_dialog_content = "¿Deberíamos hacer lo mismo?",
  ui_story_5088_50880901_12_dialog_content = "No, eso no será necesario. Estoy acostumbrado a esconderme en los márgenes de una historia, cuanto menos notable, mejor.",
  ui_story_5088_50880901_13_dialog_content = "Nuestro clan ha vivido de esta manera durante generaciones. No nos quedamos en un lugar y no hacemos amigos.",
  ui_story_5088_50880901_14_dialog_content = "Solo deseamos convertirnos en la noche que guarda las estrellas.",
  ui_story_5088_50880901_15_dialog_content = "Quizás estés acostumbrado a deslizarte en las sombras, mezclándote con el follaje...",
  ui_story_5088_50880901_16_dialog_content = "Pero, señorita Mithra... No creo que nacieras solo para cumplir la felicidad de otras personas. También mereces tu propia felicidad.",
  ui_story_5088_50880901_17_dialog_content = "...",
  ui_story_5088_50880901_18_dialog_content = "El pueblo de tu clan se ha sacrificado silenciosamente durante dos mil años. Te debemos más de lo que las palabras pueden expresar.",
  ui_story_5088_50880901_19_dialog_content = "Por favor, no digas eso... No soy nada comparado con mis antepasados...",
  ui_story_5088_50880901_20_dialog_content = "He estado asustado, enojado, confundido, e incluso pensé en rendirme...",
  ui_story_5088_50880901_21_dialog_content = "Pasé más de una década buscando Celestitas, pero no quedaba nadie. El dolor era insoportable.",
  ui_story_5088_50880901_22_dialog_content = "Estaba tan aterrorizado, temiendo que fracasaría por completo...",
  ui_story_5088_50880901_23_dialog_content = "Pero, un héroe es alguien que conoce el miedo y aún así se mantiene firme.",
  ui_story_5088_50880901_24_dialog_content = "¡¿Eh?!",
  ui_story_5088_50880901_25_dialog_content = "Esta es la lección más valiosa que aprendí de mi querido Marcela.",
  ui_story_5088_50880901_26_dialog_content = "Mithra Longinus, levanta la cabeza. No tienes motivo para sentirte avergonzado. Nunca fue justo que tu clan tuviera que soportar una carga tan pesada durante dos mil años.",
  ui_story_5088_50880901_27_dialog_content = "Recuerda, tú eres digno de nuestro respeto, al igual que tu gran antepasado.",
  ui_story_5088_50880901_28_dialog_content = "Adras...?",
  ui_story_5088_50880901_29_dialog_content = "Todos somos iguales, ¿no es así? Perdidos durante demasiado tiempo...",
  ui_story_5088_50880901_30_dialog_content = "Uh-oh, ¿el vice-capitán está viendo cosas otra vez?",
  ui_story_5088_50880901_31_dialog_content = "¿Eh? ¿Por qué de repente recordé eso?",
  ui_story_5088_50880901_32_dialog_content = "Parece que el capítulo final de la historia está listo para ser revelado.",
  ui_story_5088_50880901_33_dialog_content = "¿Es por estos crestas? Han estado resonando como locos desde que llegamos aquí.",
  ui_story_5088_50880901_34_dialog_content = "El deshielo en nuestros corazones está comenzando a desaparecer...",
  ui_story_5088_50880901_35_dialog_content = "La línea está arreglada.",
  ui_story_5088_50880901_36_dialog_content = "Parece que todos hemos encontrado nuestro camino.",
  ui_story_5088_50880901_37_dialog_content = "No hay necesidad de preocuparse, todos.",
  ui_story_5088_50880901_38_dialog_content = "Yo... sí... Todavía no puedo aceptar la partida de Marcela, así que ella permanece a mi lado, protegiéndome.",
  ui_story_5088_50880901_39_dialog_content = "Si un día pudiera descansar con ella hasta el fin de los tiempos, eso sería verdaderamente maravilloso, pero hasta entonces, deseo proteger este mundo y viajar con todos ustedes una vez más.",
  ui_story_5088_50880901_40_dialog_content = "¿Continuarás caminando este camino conmigo?",
  ui_story_5088_50880901_41_dialog_content = "... ¿Necesitas preguntar?",
  ui_story_5088_50880901_42_dialog_content = "¡Adelante!",
  ui_story_5088_50880901_43_dialog_content = "Gracias, Mithra.",
  ui_story_5088_50880901_44_dialog_content = "No tienes que agradecerme... Debería ser yo quien te agradezca.",
  ui_story_5088_50880901_45_dialog_content = "Es gracias a tus esfuerzos que los Guerreros Estrella brillarán de nuevo, y finalmente puedo ver alguna esperanza para el futuro.",
  ui_story_5088_50880901_46_dialog_content = "Estás interpretando un tipo de papel menor en este momento. Si fueras tan valiente como yo y tuvieras más líneas, ¡tu presencia general podría comenzar a despegar!",
  ui_story_5088_50880901_47_dialog_content = "... Tu alegría es un poco exagerada.",
  ui_story_5088_50880901_48_dialog_content = "En dos mil años, solo hemos visto a dos Celestitas.",
  ui_story_5088_50880901_49_dialog_content = "Tanto ella como PlayerName son nuestros benefactores, compartiendo nada más que buena voluntad.",
  ui_story_5088_50880901_50_dialog_content = "Es una lástima...",
  ui_story_5088_50880901_51_dialog_content = "...",
  ui_story_5088_50880901_52_dialog_content = "<size=30>Suspiro, qué buen conversador...</size> ¡Vaya, mira esa roca! Es una roca y es tan... rocosa... ¡y hay enemigos!",
  ui_story_5088_50880901_53_dialog_content = "<size=45>¡En serio! ¡Aviso, los enemigos vienen!</size>",
  ui_story_5088_50880902_1_dialog_content = "¿Eso es todo?",
  ui_story_5088_50880902_2_dialog_content = "He dejado mi última obsesión con la formación mágica de auto-circulación en este cuerpo.",
  ui_story_5088_50880902_3_dialog_content = "Mientras exista mi carne, la formación persistirá. Velaré por este lugar para siempre.",
  ui_story_5088_50880902_4_dialog_content = "Dame eso. Permíteme subir la conciencia.",
  ui_story_5088_50880902_5_dialog_content = "¡¡¡Rugido!!!",
  ui_story_5088_50880902_6_dialog_content = "¡Magia del bosque, ocúltanos de los ojos de nuestro perseguidor—¡Vamos!",
  ui_story_5088_50880902_7_dialog_content = "¡No! ¡No te dejaré irte!",
  ui_story_5088_50880902_8_dialog_content = "<size=45>¡¡¡Muerte a todos los enemigos!!!</size>",
  ui_story_5088_50880902_9_dialog_content = "Un Caelestite... Debo perdonarlo...",
  ui_story_5088_50880902_10_dialog_content = "<color=#e8d9bb>Silenciosamente, observa cómo su presa escapa.</color>",
  ui_story_5088_50880902_11_dialog_content = "<color=#FFB400>Ludweiss</color>... <color=#FFB400>Czerny</color>...",
  ui_story_5088_50881000_1_dialog_content = "... Pero nuestro viaje no está completo.",
  ui_story_5088_50881000_2_dialog_content = "¿Qué pasó? ¿Por qué se detuvo aquí?",
  ui_story_5088_50881000_3_dialog_content = "PlayerName, sabes que esto es solo un mensaje, ¿verdad?",
  ui_story_5088_50881000_4_dialog_content = "Oh...",
  ui_story_5088_50881000_5_dialog_content = "Fui descuidado.",
  ui_story_5088_50881000_6_dialog_content = "No sabía que una vez activado el dispositivo de generación, la fuerte señal que emitía atraería...",
  ui_story_5088_50881000_7_dialog_content = "A ellos.",
  ui_story_5088_50881000_8_dialog_content = "Aquí, por aquí, por aquí, por aquí...",
  ui_story_5088_50881000_9_dialog_content = "¿Cómo es que tantos Eclipsites nos alcanzaron?",
  ui_story_5088_50881000_10_dialog_content = "¿Podría ser que rastrearon la señal de la \"sustancia X\" desde el dispositivo? ¡Maldito sea su oscuro poder!",
  ui_story_5088_50881000_11_dialog_content = "...",
  ui_story_5088_50881000_12_dialog_content = "Oh no, la conciencia de Aquiles aún no se ha fusionado con el nuevo cuerpo. No puede luchar.",
  ui_story_5088_50881000_13_dialog_content = "<size=45>¡Alas golpeadas...! ¡Estamos acabados!</size>",
  ui_story_5088_50881000_14_dialog_content = "<color=#FFB400>¡Luz de estrella oscura! ¡Erupción!</color>",
  ui_story_5088_50881000_15_dialog_content = "¿Qué está pasando?",
  ui_story_5088_50881000_16_dialog_content = "Una cantidad masiva de poder esencial... \"Sustancia N\" convergió...",
  ui_story_5088_50881000_17_dialog_content = "¿Aquiles, eres tú?",
  ui_story_5088_50881000_18_dialog_content = "... ¿Puedes oírme?",
  ui_story_5088_50881000_19_dialog_content = "Puedes controlar remotamente tu nuevo cuerpo... Es un milagro...",
  ui_story_5088_50881000_20_dialog_content = "Yo... no puedo... sostenerlo...",
  ui_story_5088_50881000_21_dialog_content = "Me he estrellado... No podemos seguir volando...",
  ui_story_5088_50881000_22_dialog_content = "Intentaré repararme con las luciérnagas, pero antes de eso... ¿puedes usar tu magia para crear una ilusión?",
  ui_story_5088_50881000_23_dialog_content = "... Lo... intentaré...",
  ui_story_5088_50881000_24_dialog_content = "Pero, mis reparaciones fallaron.",
  ui_story_5088_50881000_25_dialog_content = "Hice que las luciérnagas utilizaran los materiales cercanos disponibles para crear este <color=#FFB400>Obelisco del Retorno</color> para poder dejar un mensaje.",
  ui_story_5088_50881000_26_dialog_content = "Quería incluir la información genética del clan Longinus en el sistema de identificación, pero no había nadie de la familia Longinus de quien recogerla.",
  ui_story_5088_50881000_27_dialog_content = "Entonces, extraje la información racial de los Celestitas de mi propio cadáver como la única clave.",
  ui_story_5088_50881000_28_dialog_content = "Antes de que se agotara la energía, presencié cómo el clan Longinus encontró este lugar.",
  ui_story_5088_50881000_29_dialog_content = "Pero no parecían entender lo que había sucedido, y quizás debido al dispositivo generador de Eclipsites, no se atrevieron a informar a Eraveil.",
  ui_story_5088_50881000_30_dialog_content = "Todo lo que pude hacer fue esperar... esperar tu llegada... una vez que me apague, mi conciencia desaparecerá... así que te dejé estas palabras...",
  ui_story_5088_50881000_31_dialog_content = "Ludweiss y Aquiles están en la cima de esta torre, y el nuevo cuerpo todavía está en la cápsula de hibernación del Colossus.",
  ui_story_5088_50881000_32_dialog_content = "Por favor, sube y ve a verlos primero...",
  ui_story_5088_50881000_33_dialog_content = "... Parece que tu clan estaba preocupado por que las cosas volvieran a ir mal, así que se aferraron firmemente a su deber.",
  ui_story_5088_50881000_34_dialog_content = "Y durante dos mil años, tu gente eligió permanecer oculta, observando silenciosamente esos diarios, esperando la profecía...",
  ui_story_5088_50881000_35_dialog_content = "Sí.",
  ui_story_5088_50881000_36_dialog_content = "El escudo que sostengo, imbuido con el poder del Señor Aquiles, permite a cada cabeza de familia agregar una parte de sus recuerdos y voluntad a él.",
  ui_story_5088_50881000_37_dialog_content = "He presenciado los esfuerzos de mis antepasados: crearon un ecosistema dentro de esta formación mágica y mantuvieron el Colossus.",
  ui_story_5088_50881000_38_dialog_content = "Esperaban que este lugar se convirtiera en un lugar de descanso digno.",
  ui_story_5088_50881000_39_dialog_content = "Más tarde, el Coloso fue reparado y se restauró su suministro de energía, pero nadie se atrevió a tocarlo. En mi generación, ni siquiera sabíamos su ubicación exacta.",
  ui_story_5088_50881000_40_dialog_content = " Czerny, espérame allí...",
  ui_story_5088_50881000_41_dialog_content = "Ya he pasado por esto antes, una vez encontré parte de la conciencia de un amigo en un Coloso de Guerra.",
  ui_story_5088_50881000_42_dialog_content = "Incluso después de escuchar todo esto, todavía no entendemos algunas cosas.",
  ui_story_5088_50881000_43_dialog_content = "Una vez que esto termine, por favor cuéntanos todo lo que sabes.",
  ui_story_5088_50881000_44_dialog_content = "Quizás, el mismo Aquiles pueda decírtelo.",
  ui_story_5088_50881000_45_dialog_content = "Estás bastante seguro de todo esto, ¿no es así? ¡Bien! Pondré mi fe en esa esperanza radiante que brilla en tus ojos!",
  ui_story_5088_50881000_46_dialog_content = "Porque la última vez, realmente logramos el final perfecto que buscábamos...",
  ui_story_5088_50881000_47_dialog_content = "¡Entonces hagámoslo de nuevo!",
  ui_story_5088_50881000_48_dialog_content = "¡Sí... un final perfecto... una vez más!",
  ui_story_5088_50881102_1_dialog_content = "Aquí es donde reside ahora la conciencia de Aquiles...",
  ui_story_5088_50881102_2_dialog_content = "Solo tú puedes fusionar la conciencia del Señor Aquiles con su cuerpo.",
  ui_story_5088_50881102_3_dialog_content = "Lo haré lo mejor que pueda.",
  ui_story_5088_50881102_4_dialog_content = "...",
  ui_story_5088_50881102_5_dialog_content = "Estás... aquí...",
  ui_story_5088_50881102_6_dialog_content = "¿Mmm?",
  ui_story_5088_50881102_7_dialog_content = "...",
  ui_story_5088_50881102_8_dialog_content = "Gracias por sacarnos de dos mil años de oscuridad.",
  ui_story_5088_50881102_9_dialog_content = "Es hora de que la llevemos de regreso.",
  ui_story_5088_50881102_10_dialog_content = "Ludweiss...",
  ui_story_5088_50881102_11_dialog_content = "Finalmente, estamos reunidos.",
  ui_story_5088_50881102_12_dialog_content = "PlayerName, nos gustaría quedarnos aquí un poco más.",
  ui_story_5088_50881102_13_dialog_content = "Tú ve primero al Coloso.",
  ui_story_5088_50881102_14_dialog_content = "Seguro...",
  ui_story_5088_50881102_15_dialog_content = "Vamos. Yo te protegeré.",
  ui_story_5088_50881102_16_dialog_content = "¿Será esta vez como un sueño para el Señor Aquiles?",
  ui_story_5088_50881102_17_dialog_content = "Para él, esta pérdida dura tanto tiempo.",
  ui_story_5088_50881102_18_dialog_content = "Pero creo que aún sonreirá.",
  ui_story_5088_50881102_19_dialog_content = "Porque el Aquiles que conozco es un pionero, alguien que siempre avanza sin miedo.",
  ui_story_5088_50881102_20_dialog_content = "Lo sé... definitivamente seguirá adelante.",
  ui_story_5088_50881102_21_dialog_content = "¿Es esta... la filosofía de Windelion?",
  ui_story_5088_50881102_22_dialog_content = "Sí...",
  ui_story_5088_50881102_23_dialog_content = "Recuerda a los fallecidos y envíales tus pensamientos, pero al mismo tiempo, sigue avanzando.",
  ui_story_5088_50881102_24_dialog_content = "...",
  ui_story_5088_50881102_25_dialog_content = "Ya estamos acá.",
  ui_story_5088_50881102_26_dialog_content = "<color=#e8d9bb>En las profundidades del Colossus averiado se encuentra un panel de control similar a un piano, uno que el Caelestite conoce muy bien.</color>",
  ui_story_5088_50881102_27_dialog_content = "<color=#e8d9bb>Y esperando en ese asiento, hay un esqueleto.</color>",
  ui_story_5088_50881102_28_dialog_content = "Señor Czerny...",
  ui_story_5088_50881102_29_dialog_content = "...",
  ui_story_5088_50881102_30_dialog_content = "...",
  ui_story_5088_50881102_31_dialog_content = "El cuerpo de Aquiles descansa aquí.",
  ui_story_5088_50881102_32_dialog_content = "Tiempo de comenzar mi trabajo.",
  ui_story_5088_50881102_33_dialog_content = "<color=#e8d9bb>Cuidadosamente muevo al Sr. Czerny, entregándolo a Mithra, y luego, con gran respeto... presiono las teclas.</color>",
  ui_story_5088_50881102_34_dialog_content = "El Coloso ha sido despertado de nuevo. Parece que ha llegado el momento.",
  ui_story_5088_50881102_35_dialog_content = "Si estás escuchando este mensaje, significa que el programa de autoverificación se ha ejecutado con éxito y el cuerpo de Aquiles finalmente es estable.",
  ui_story_5088_50881102_36_dialog_content = "A continuación, debes elegir si completar esta gran hazaña.",
  ui_story_5088_50881102_37_dialog_content = "Pero esta es una tarea extremadamente peligrosa, una que podría costarte la vida. Si eliges rechazarla, no te culparemos.",
  ui_story_5088_50881102_38_dialog_content = "Pero si realmente eres lo suficientemente valiente para aceptar esta responsabilidad, te ofrezco mi más profunda gratitud.",
  ui_story_5088_50881102_39_dialog_content = "Escucha bien: el poder incoloro es la esencia de Lumina.",
  ui_story_5088_50881102_40_dialog_content = "Según mi investigación, esta es la esquiva \"sustancia N\". Desafortunadamente, ya no tengo tiempo para investigar su conexión con la \"sustancia X\".",
  ui_story_5088_50881102_41_dialog_content = "La esencia del poder incoloro y la Lumina coloreada es fundamentalmente la misma, pero nuestra naturaleza innata hace que nos resulte difícil reconocer la esencia de la variedad incolora.",
  ui_story_5088_50881102_42_dialog_content = "Afortunadamente, el cuerpo de Aquiles ya no está enredado en el poder oscuro, reduciendo el peligro.",
  ui_story_5088_50881102_43_dialog_content = "Sin embargo, aún enfrentarás grandes riesgos al guiar su conciencia a través de la barrera incolora.",
  ui_story_5088_50881102_44_dialog_content = "Si estás listo, coloca la plantilla de eco aquí y comienza el proceso de orientación.",
  ui_story_5088_50881102_45_dialog_content = "Finalizó la grabación del sistema—",
  ui_story_5088_50881102_46_dialog_content = "Estoy listo, Sr. Czerny.",
  ui_story_5088_50881102_47_dialog_content = "Mithra, mientras estoy usando mis habilidades psíquicas, contaré contigo para encargarte de todo lo demás.",
  ui_story_5088_50881102_48_dialog_content = "Te protegeré. Lo juro.",
  ui_story_5088_50881102_49_option_content = "El último escaneo psíquico",
  ui_story_5088_50881102_50_dialog_content = "Aquiles, tu largo sueño finalmente puede llegar a su fin.",
  ui_story_5088_50881102_51_dialog_content = "Por favor, vuelve conmigo a...",
  ui_story_5088_50881102_52_dialog_content = "...",
  ui_story_5088_50881102_53_dialog_content = "Realmente es peligroso aquí. No puedo ver nada...",
  ui_story_5088_50881102_54_dialog_content = "Aquí, por aquí, por aquí, por aquí...",
  ui_story_5088_50881102_55_dialog_content = "¿Qué es eso? Esta voz suena tan familiar...",
  ui_story_5088_50881102_56_dialog_content = "... Otro \"traidor.\"",
  ui_story_5088_50881102_57_dialog_content = "Gracias a que me reiniciaste, finalmente seré revivido.",
  ui_story_5088_50881102_58_dialog_content = "¿Eres... este Coloso?",
  ui_story_5088_50881102_59_dialog_content = "Pero el Sr. Czerny no encontró una conciencia dentro de ti...",
  ui_story_5088_50881102_60_dialog_content = "¡Tonto! Me escondí cuando ustedes, traidores, me atraparon. ¿Por qué me mostraría tan imprudentemente?",
  ui_story_5088_50881102_61_dialog_content = "Gracias por devolverme a mi cuerpo.",
  ui_story_5088_50881102_62_dialog_content = "Ya veo... no almacenaste tu conciencia en los componentes de la máquina... ¡la transferiste a una plantilla de respaldo!",
  ui_story_5088_50881102_63_dialog_content = "Eres bastante ingenioso.",
  ui_story_5088_50881102_64_dialog_content = "Sí. Este traidor y yo compartimos la misma plantilla de eco.",
  ui_story_5088_50881102_65_dialog_content = "¡Ahora, tú deberás ayudarme a revivir!",
  ui_story_5088_50881102_66_dialog_content = "(Mi cabeza... duele tanto...)",
  ui_story_5088_50881102_67_dialog_content = "(¿Está infiltrándose en mi mente? ¿Cómo puede la conciencia de un Colossus hacer algo así?)",
  ui_story_5088_50881102_68_dialog_content = "No olvides, estás conectado a mi sistema operativo.",
  ui_story_5088_50881102_69_dialog_content = "(No, no puedo permitirlo...)",
  ui_story_5088_50881102_70_dialog_content = "¡Ahora eres mío!",
  ui_story_5088_50881102_71_dialog_content = "Urghhh...",
  ui_story_5088_50881102_72_dialog_content = "<size=45>¡Aniquilación!</size>",
  ui_story_5088_50881102_73_dialog_content = "¡Aaaahhhhh!",
  ui_story_5088_50881102_74_dialog_content = "<color=#e8d9bb>El cuerpo dormido de Claymore de repente despierta, desatando una poderosa ráfaga de energía de espada hacia el suelo.</color>",
  ui_story_5088_50881102_75_dialog_content = "<color=#e8d9bb>Con solo un golpe, Fortez es partido por la mitad.</color>",
  ui_story_5088_50881102_76_dialog_content = "<color=#e8d9bb>Desde el dispositivo generador de Eclipsites hasta su cuerpo, desde sus amenazantes alas rotas hasta sus ambiciones, todo es aniquilado de un solo golpe.</color>",
  ui_story_5088_50881102_77_dialog_content = "¡PlayerName!",
  ui_story_5088_50881102_78_dialog_content = "Mi conexión fue cortada... Aquiles me salvó.",
  ui_story_5088_50881102_79_dialog_content = "¡No! Pero, ¿y tú, Aquiles?!",
  ui_story_5088_50881102_80_dialog_content = "El Coloso se está derrumbando. Está arruinado.",
  ui_story_5088_50881102_81_dialog_content = "¡No! ¡Necesito completar la fusión antes de que se descomponga completamente!",
  ui_story_5088_50881102_82_option_content = "¡Potencia de fuerza!",
  ui_story_5088_50881102_83_dialog_content = "¡Tonto! Después de escapar por poco, ¿todavía te atreves a volver aquí?",
  ui_story_5088_50881102_84_dialog_content = "¿Qué más esperabas?",
  ui_story_5088_50881102_85_dialog_content = "Prometí a todos que traería a Aquiles de vuelta.",
  ui_story_5088_50881102_86_dialog_content = "Entonces, le diré que la primavera ha llegado.",
  ui_story_5088_50881102_87_dialog_content = "Lo llevaré a él, al Señor Czerny, y a Lady Ludweiss a Eraveil...",
  ui_story_5088_50881102_88_dialog_content = "¡Para ver las linternas de diente de león y las coloridas muñecas Windelion con todos!",
  ui_story_5088_50881102_89_dialog_content = "¡Nunca permitiré que Aquiles se convierta solo en un recuerdo!",
  ui_story_5088_50881201_1_dialog_content = "¡Salgan, mis defensores!",
  ui_story_5088_50881201_2_dialog_content = "¿Monstruos? No, ¿están siendo creados por ese dispositivo de generación?",
  ui_story_5088_50881201_3_dialog_content = "¡No te dejaré lastimar a PlayerName!",
  ui_story_5088_50881201_4_dialog_content = "(Rápido, necesito atravesar esta tormenta incolora...)",
  ui_story_5088_50881201_5_dialog_content = "Aquiles, ¿dónde estás?",
  ui_story_5088_50881201_6_dialog_content = "¡Permíteme ser tu faro! ¡Ven conmigo y regresa a tu cuerpo!",
  ui_story_5088_50881201_7_dialog_content = "¡Piénsalo de nuevo! Mi cuerpo ya se ha ido... ¡ahora su cuerpo será mío!",
  ui_story_5088_50881201_8_dialog_content = "Urgh...",
  ui_story_5088_50881201_9_dialog_content = "¡Un Coloso caído que se inclina ante el Eclipse nunca derrotará las habilidades psíquicas de un Caelestita!",
  ui_story_5088_50881201_10_dialog_content = "je^&c—",
  ui_story_5088_50881201_11_dialog_content = "¿De dónde has sacado este poder?",
  ui_story_5088_50881201_12_dialog_content = "¡He luchado contra innumerables enemigos más duros que tú! ¡Nunca me derribarás!",
  ui_story_5088_50881201_13_dialog_content = "... ¡Seguramente no puedes manejar este poder! ¡Tu cuerpo no puede soportar tal tensión!",
  ui_story_5088_50881201_14_dialog_content = "Mira, el campo de energía está fuera de control. Nunca encontrarás a la persona que deseas ayudar en esta tormenta.",
  ui_story_5088_50881201_15_dialog_content = "¡Es una existencia incolora! ¿Cómo discernirás su aura? ¿Con esos ojos tuyos que solo se sienten atraídos por la luz?",
  ui_story_5088_50881201_16_dialog_content = "¡¡¡Yo... Yo he terminado de escuchar tus tonterías!!!",
  ui_story_5088_50881201_17_dialog_content = "<size=45>¡Hyaaaa!</size>",
  ui_story_5088_50881201_18_dialog_content = "No...",
  ui_story_5088_50881201_19_dialog_content = "(Todo el cansancio de estos últimos días me está alcanzando... Mi cabeza se siente como si fuera a explotar... como si me estuvieran arrastrando hacia abajo...)",
  ui_story_5088_50881201_20_dialog_content = "(No puedo caer ahora... No puedo rendirme...)",
  ui_story_5088_50881201_21_dialog_content = "(Pero... Estoy tan cansado... y este dolor... Siento que estoy en mi límite...)",
  ui_story_5088_50881201_22_dialog_content = "Aquiles... ¿Dónde estás...?",
  ui_story_5088_50881201_23_dialog_content = "Cuando el trabajo duro no puede hacer el trabajo, tienes que confiar en tu suerte e intuición.",
  ui_story_5088_50881201_24_dialog_content = "(¿Por qué eso apareció de repente en mi cabeza...?)",
  ui_story_5088_50881201_25_dialog_content = "(¡Argh! ¿De dónde vino este fuego en este mar de caos... ¿Eh?)",
  ui_story_5088_50881201_26_dialog_content = "<color=#e8d9bb>En mis últimos momentos de confusión, de repente soy despertado por las llamas.</color>",
  ui_story_5088_50881201_27_dialog_content = "<color=#e8d9bb>La fuente del fuego son las dos Crestas de Estrella que Casta me ayudó a encontrar.</color>",
  ui_story_5088_50881201_28_dialog_content = "Este es de Ludweiss, y el otro debería ser... ¿Eh?",
  ui_story_5088_50881201_29_dialog_content = "Mira hacia el cielo, y las estrellas brillarán en respuesta.",
  ui_story_5088_50881201_30_dialog_content = "El calor de su luz sigue siendo el mismo, incluso después de dos mil años.",
  ui_story_5088_50881201_31_dialog_content = "¡Esta vez, déjanos ayudarte!",
  ui_story_5088_50881201_32_dialog_content = "¿Lady Ludweiss? ¿Señor Czerny?",
  ui_story_5088_50881201_33_dialog_content = "¿Podría ser que dentro de los escudos también se encuentre tu...?",
  ui_story_5088_50881201_34_dialog_content = "<color=#FFB400>¡Nuestras esperanzas y pensamientos!</color>",
  ui_story_5088_50881201_35_dialog_content = "¡¿De dónde vienes?! ¿Qué estás tratando de hacer?",
  ui_story_5088_50881201_36_dialog_content = "¿Nosotros? ¡Ja! Hemos atravesado dos milenios—",
  ui_story_5088_50881201_37_dialog_content = "Transmitido a través de los siglos—",
  ui_story_5088_50881201_38_dialog_content = "¡Un milagro nacido de las conexiones más profundas!",
  ui_story_5088_50881201_39_dialog_content = "Alguien como tú, que solo incita conflictos e impide lazos sinceros...",
  ui_story_5088_50881201_40_dialog_content = "¡¿Cómo podrías entenderlo alguna vez?!",
  ui_story_5088_50881201_41_dialog_content = "¡Aquiles! ¡Has dormido suficiente! ¡Despierta!!!",
  ui_story_5088_50881201_42_dialog_content = "... ¿Ludweiss?",
  ui_story_5088_50881201_43_dialog_content = "¡No, no! ¡Ese es mi cuerpo!!!",
  ui_story_5088_50881201_44_dialog_content = "¡Cuidado, está a punto de atacar!",
  ui_story_5088_50881201_45_dialog_content = "¡Déjame cubrir la defensa!",
  ui_story_5088_50881201_46_dialog_content = "Joven traidor, ¿crees que realmente pueden protegerte? Eres demasiado débil...",
  ui_story_5088_50881201_47_dialog_content = "¡Hermanito del futuro!",
  ui_story_5088_50881201_48_dialog_content = "Una vez me dijiste que crees que los recuerdos son una maldición.",
  ui_story_5088_50881201_49_dialog_content = "Pero habiendo vivido mi vida, tengo algo que compartir contigo.",
  ui_story_5088_50881201_50_dialog_content = "Para mí, <color=#FFB400>los recuerdos son regalos</color>! Has recibido muchos regalos, y has honrado esos innumerables pensamientos. Eso es algo verdaderamente notable.",
  ui_story_5088_50881201_51_dialog_content = "Es correcto.",
  ui_story_5088_50881201_52_dialog_content = "Has heredado nuestros recuerdos y voluntad, y has llegado hasta aquí. Eso solo es increíble.",
  ui_story_5088_50881201_53_dialog_content = "Tus acciones demuestran que la antorcha del heroísmo puede pasar de una era a la siguiente.",
  ui_story_5088_50881201_54_dialog_content = "Ahora, es el momento para que los héroes de antaño realicen su alegría.",
  ui_story_5088_50881201_55_dialog_content = "Entonces, no tengas miedo, y no te confundas...",
  ui_story_5088_50881201_56_dialog_content = "Mantente erguido y da el golpe final.",
  ui_story_5088_50881201_57_dialog_content = "¡Está bien!",
  ui_story_5088_50881201_58_dialog_content = "¡Cazadores Silenciosos!",
  ui_story_5088_50881201_59_dialog_content = "<color=#FFB400>¡En marcha!</color>",
  ui_story_5088_50881201_60_dialog_content = "¿Qué es esto...? Enemigos más problemáticos...",
  ui_story_5088_50881201_61_dialog_content = "Fortez... no te atrevas a mirar a otro lado... todavía tienes que...",
  ui_story_5088_50881201_62_dialog_content = "Pequeño mocoso...",
  ui_story_5088_50881201_63_dialog_content = "Obtener...",
  ui_story_5088_50881201_64_dialog_content = "... ¡fuera de este mundo!",
  ui_story_5088_50881201_65_dialog_content = "¡No, no, no, no!",
  ui_story_5088_50881201_66_dialog_content = "<size=45>Lo veo, longitud de onda sin color!</size>",
  ui_story_5088_50881201_67_dialog_content = "¡Aquiles!",
  ui_story_5088_50881202_1_dialog_content = "¡PlayerName está sangrando mucho! Necesitamos encontrar una forma de detenerlo...",
  ui_story_5088_50881202_2_dialog_content = "No, déjame encargarme de eso esta vez.",
  ui_story_5088_50881202_3_dialog_content = "No podemos molestarlo ahora. Todo lo que podemos hacer es usar magia para detener la hemorragia.",
  ui_story_5088_50881202_4_dialog_content = "La conciencia de Fortez se ha ido, y la conciencia de Aquiles ha regresado con éxito... Ludweiss, lo logramos...",
  ui_story_5088_50881202_5_dialog_content = "Parece que realmente ha llegado el momento de decir adiós.",
  ui_story_5088_50881202_6_dialog_content = "Pero...",
  ui_story_5088_50881202_7_dialog_content = "Finalmente pude verlos a todos ustedes...",
  ui_story_5088_50881202_8_dialog_content = "Cierto.",
  ui_story_5088_50881202_9_dialog_content = "Bueno, hace tiempo que decidí que lo correcto sería darte un regalo, por todo tu duro trabajo, por supuesto.",
  ui_story_5088_50881202_10_dialog_content = "Espero que te guste.",
  ui_story_5088_50881202_11_dialog_content = "Esto es lo último que puedo lograr con la energía restante...",
  ui_story_5088_50881202_12_dialog_content = "Ah, por cierto, ¿podrías decirnos tu nombre?",
  ui_story_5088_50881202_13_dialog_content = "Mi nombre es PlayerName... Soy... un Caelestita. Trabajo con mis amigos en logística.",
  ui_story_5088_50881202_14_dialog_content = "Eres un alma muy amable y notable, un verdadero héroe glorioso de tu época.",
  ui_story_5088_50881202_15_dialog_content = "Gracias.",
  ui_story_5088_50881202_16_dialog_content = "yo... eh... yo...",
  ui_story_5088_50881202_17_dialog_content = "Por favor, llévanos de regreso a Eraveil.",
  ui_story_5088_50881202_18_dialog_content = "Límpiate las lágrimas y regala una sonrisa para Windelion.",
  ui_story_5088_50881202_19_dialog_content = "Tus pensamientos ya nos han alcanzado... en el río donde nos reunimos.",
  ui_story_5088_50881202_20_dialog_content = "Nunca estarás solo.",
  ui_story_5088_50881202_21_dialog_content = "Adiós.",
  ui_story_5088_50881202_22_dialog_content = "Despierta... Despierta...",
  ui_story_5088_50881202_23_dialog_content = "Yo... ¿Dónde están...? ¿Qué pasó...?",
  ui_story_5088_50881202_24_dialog_content = "Después de que la formación mágica exterior desapareció, algunos niños curiosos de un pueblo cercano se adentraron.",
  ui_story_5088_50881202_25_dialog_content = "Los Guerreros Estrella partieron para mantenerlos a salvo.",
  ui_story_5088_50881202_26_dialog_content = "Pero... Creo que podrían estar inseguros de cómo acercarse al Señor Aquiles.",
  ui_story_5088_50881202_27_dialog_content = "Esto es... la Plantilla de Eco...",
  ui_story_5088_50881202_28_dialog_content = "Oh, otro está roto.",
  ui_story_5088_50881202_29_dialog_content = "Pero por suerte, logré salvar la conciencia dentro de esta vez...",
  ui_story_5088_50881202_30_dialog_content = "... Salgamos por ahora. Las cosas podrían ponerse incómodas si lo primero que ve Aquiles al despertar es a un total desconocido.",
  ui_story_5088_50881202_31_dialog_content = "Vamos, déjame ayudarte a salir de aquí.",
  ui_story_5088_50881202_32_dialog_content = "Es tan hermoso...",
  ui_story_5088_50881202_33_dialog_content = "Lamentablemente, una vez que se levante la formación mágica del Lord Aquiles, este lugar puede volver pronto a las salvajes normalidades de Northland.",
  ui_story_5088_50881202_34_dialog_content = "Pero está bien... Muchas cosas se conservan mejor en los recuerdos.",
  ui_story_5088_50881202_35_dialog_content = "...",
  ui_story_5088_50881202_36_dialog_content = "Por favor, toma esto.",
  ui_story_5088_50881202_37_dialog_content = "¿Qué es esto?",
  ui_story_5088_50881202_38_dialog_content = "Es la última entrada en mi diario, un símbolo de la gratitud del clan Longinus, otorgado solo a aquellos que completan la verdadera jornada de un héroe.",
  ui_story_5088_50881202_39_dialog_content = "... ¿Ah?",
  ui_story_5088_50881202_40_dialog_content = "<color=#e8d9bb>Un viento se levanta bajo la distante Torre Blanca, ascendiendo al cielo.</color>",
  ui_story_5088_50881202_41_dialog_content = "<color=#e8d9bb>Una melodía suave y melodiosa comienza a sonar junto a la brisa.</color>",
  ui_story_5088_50881202_42_dialog_content = "<color=#e8d9bb>La Torre Blanca, diseñada por el maestro musical Czerny, es en sí misma un instrumento.</color>",
  ui_story_5088_50881202_43_dialog_content = "<color=#e8d9bb>Y toca una canción de cuna que una vez fue conocida en todo Eraveil.</color>",
  ui_story_5088_50881202_44_dialog_content = "<color=#e8d9bb>Compuesto por Czerny bajo la guía de Ludweiss—</color><color=#FFB400>Día de Windelion: Una canción de cuna para viajeros.</color>",
  ui_story_5088_50881202_45_dialog_content = "Es simplemente divino.",
  ui_story_5088_50881202_46_dialog_content = "Este es el <color=#FFB400>regalo</color>...",
  ui_story_5088_50881202_47_dialog_content = "Gracias. Gracias a los dos...",
  ui_story_5088_50881202_48_dialog_content = "<color=#e8d9bb>A medida que este diario llega a su conclusión, ¿qué final sería el más adecuado?</color>",
  ui_story_5088_50881202_49_dialog_content = "<color=#e8d9bb>Ah, sí, debería ir para ti, el que se esforzó tanto para llegar a este punto.</color>",
  ui_story_5088_50881202_50_dialog_content = "<color=#e8d9bb>Gracias por hacer posible este milagro.</color>",
  ui_story_5088_50881202_51_dialog_content = "<color=#e8d9bb>Sé que este viaje ha sido arduo y, al final, parece que tu única recompensa es presenciar la alegría de otros al reunirse.</color>",
  ui_story_5088_50881202_52_dialog_content = "<color=#e8d9bb>Pero tú, que has luchado tan valientemente por los demás, ¿qué razón hay para no reconocer tu grandeza?</color>",
  ui_story_5088_50881202_53_dialog_content = "<color=#e8d9bb>May tú, que has llegado tan lejos, también te reúnas con aquellos que son importantes para ti y encuentres tu propia alegría.</color>",
  ui_story_5088_50881202_54_dialog_content = "<color=#e8d9bb>Deseamos tu felicidad desde lo más profundo de nuestros corazones, nuestra luz de estrella.</color>",
  ui_story_5088_50881300_1_dialog_content = "<color=#e8d9bb>Este es un reino que duerme en la nieve blanca, un paraíso sereno y pacífico más allá del alcance del mundo.</color>",
  ui_story_5088_50881300_2_dialog_content = "<color=#e8d9bb>Los héroes bendecidos han soñado en esta tierra congelada durante años, acompañados por los pensamientos más cálidos.</color>",
  ui_story_5088_50881300_3_dialog_content = "<color=#e8d9bb>Debajo de este mundo puro se entierra demasiado del pasado, y lo único que se puede ver son flores creciendo de las tumbas de los sacrificados, custodiando un reino de cuento de hadas.</color>",
  ui_story_5088_50881300_4_dialog_content = "<color=#e8d9bb>Bethlehem cierra el libro, mirando la barrera que se derrite a lo lejos, dentro del reino de Northland, largo tiempo congelado, florece un campo de flores de primavera.</color>",
  ui_story_5088_50881300_5_dialog_content = "<color=#e8d9bb>La historia de Northland comienza con el reino que primero lo unificó. La leyenda habla de un rey que se sentó solo en un trono helado, trayendo paz a esta tierra.</color>",
  ui_story_5088_50881300_6_dialog_content = "<color=#e8d9bb>Muchos años después, los descendientes del rey se enfrentaron entre sí en una búsqueda de poder, sumiendo una vez más a Northland en el caos.</color>",
  ui_story_5088_50881300_7_dialog_content = "<color=#e8d9bb>Cuando una chica de las tierras fronterizas presenció este mundo devastado, juró restaurar su pureza.</color>",
  ui_story_5088_50881300_8_dialog_content = "<color=#e8d9bb>Así, la chica lideró al pueblo, convirtiéndose eventualmente en reina.</color>",
  ui_story_5088_50881300_9_dialog_content = "<color=#e8d9bb>En los antiguos tomos sellados por el viejo rey, la reina lee la historia de las \"estrellas\".</color>",
  ui_story_5088_50881300_10_dialog_content = "<color=#e8d9bb>Así, cada Bethlehem comenzó a desear el futuro de las \"estrellas\".</color>",
  ui_story_5088_50881300_11_dialog_content = "Héroes, ahora, es primavera.",
  ui_story_5088_50881300_12_dialog_content = "...",
  ui_story_5088_50881300_13_dialog_content = "¿Dónde estamos...?",
  ui_story_5088_50881300_14_dialog_content = "Adras, creo que el pan casi está listo.",
  ui_story_5088_50881300_15_dialog_content = "¡Friegson, baja la calefacción!",
  ui_story_5088_50881300_16_dialog_content = "... Alguien ha estado dando mordiscos furtivos.",
  ui_story_5088_50881300_17_dialog_content = "Vaya, huele tan bien...",
  ui_story_5088_50881300_18_dialog_content = "¿Qué pasó con tu noble comportamiento?",
  ui_story_5088_50881300_19_dialog_content = "¿A quién le importa eso cuando hay buena comida para comer?",
  ui_story_5088_50881300_20_dialog_content = "¡Puedo ayudar!",
  ui_story_5088_50881300_21_dialog_content = "¡Ey! Solo estás tratando de tomar un bocado descarado mientras finges ayudar, ¿verdad? ¡No lo creo!",
  ui_story_5088_50881300_22_dialog_content = "¡Eso es una mentira! No puedes intimidarme... ¡Ludweiss, ayuda!",
  ui_story_5088_50881300_23_dialog_content = "¿Quién va por ahí discutiendo con niños?! Lady Marcela, ¡debes enseñarle una lección!",
  ui_story_5088_50881300_24_dialog_content = "¿Eh? No, no, no, solo estaba bromeando...",
  ui_story_5088_50881300_25_dialog_content = "<color=#FFB400>Una ilusión</color>...",
  ui_story_5088_50881300_26_dialog_content = "Sí, esta es la escena que más anhelas.",
  ui_story_5088_50881300_27_dialog_content = "Ludweiss...",
  ui_story_5088_50881300_28_dialog_content = "En este sueño dichoso, tu presencia es lo único que falta.",
  ui_story_5088_50881300_29_dialog_content = "Y eso es suficiente.",
  ui_story_5088_50881300_30_dialog_content = "Aquiles, eres lo suficientemente fuerte para reconocer que esto es una mera ilusión, pero débil por el miedo de que puedas romper esta felicidad.",
  ui_story_5088_50881300_31_dialog_content = "... No me impedirás irme, ¿verdad?",
  ui_story_5088_50881300_32_dialog_content = "Sí.",
  ui_story_5088_50881300_33_dialog_content = "Como esta es tu fantasía, debería decirte que te quedes.",
  ui_story_5088_50881300_34_dialog_content = "Pero aún deseo que explores el nuevo mundo por mí y me ayudes a escribir nuevas historias de tus viajes.",
  ui_story_5088_50881300_35_dialog_content = "¿Está realmente bien para nosotros volver al mundo de esta manera?",
  ui_story_5088_50881300_36_dialog_content = "¿Crees que tal cosa sea simple?",
  ui_story_5088_50881300_37_dialog_content = "Este no es un juego donde la victoria conduce a la resurrección.",
  ui_story_5088_50881300_38_dialog_content = "Pero aún así, ¿quién no querría reunirse a tu alrededor para una reunión de primavera? Por lo tanto, todos reunieron su fuerza para su héroe.",
  ui_story_5088_50881300_39_dialog_content = "Y prometiste encontrar una forma de reunirnos.",
  ui_story_5088_50881300_40_dialog_content = "Tienes razón...",
  ui_story_5088_50881300_41_dialog_content = "Adiós, Ludweiss.",
  ui_story_5088_50881300_42_dialog_content = "Espera.",
  ui_story_5088_50881300_43_dialog_content = "¡¿?!",
  ui_story_5088_50881300_44_dialog_content = "Buen viaje.",
  ui_story_5088_50881300_45_dialog_content = "¡Por favor, cuida de Adras por mí!",
  ui_story_5088_50881300_46_dialog_content = "Je...",
  ui_story_5088_50881300_47_dialog_content = "Adiós.",
  ui_story_5088_50881300_48_dialog_content = "... Despedida.",
  ui_story_5088_50881300_49_dialog_content = "<color=#e8d9bb>Northland nunca ha carecido de paisajes impresionantes y hermosas flores, pero la gente de aquí nunca ha visto una luz de primavera tan gloriosa como esta.</color>",
  ui_story_5088_50881300_50_dialog_content = "<color=#e8d9bb>En este pequeño rincón del mundo, donde el hielo y la nieve finalmente se han derretido, los dientes de león bailan en el aire y los campos de flores florecen brillantemente.</color>",
  ui_story_5088_50881300_51_dialog_content = "<color=#e8d9bb>Un arco iris se apoya contra el Obelisco del Retorno, escuchando su canción suave y melodiosa.</color>",
  ui_story_5088_50881300_52_dialog_content = "<color=#e8d9bb>Todos cercanos están profundamente cautivados por ello.</color>",
  ui_story_5088_50881300_53_dialog_content = "Después de dos mil años, el deseo de nuestro clan finalmente se ha hecho realidad...",
  ui_story_5088_50881300_54_dialog_content = "Gracias por ser parte de este mundo.",
  ui_story_5088_50881300_55_dialog_content = "Me halagas demasiado...",
  ui_story_5088_50881300_56_dialog_content = "Una vez estuve completamente perdido, pero ahora entiendo la grandeza de aquellos que vinieron antes que yo.",
  ui_story_5088_50881300_57_dialog_content = "A partir de ahora, seguiré el camino de la justicia, al igual que mis antepasados, el camino de los Guerreros Estrella.",
  ui_story_5088_50881300_58_dialog_content = "Creo que eres bastante impresionante, Mithra... especialmente cuando me salvaste esa noche.",
  ui_story_5088_50881300_59_dialog_content = "A pesar de tu confusión, nunca te rendiste.",
  ui_story_5088_50881300_60_dialog_content = "Fue gracias a ti que pude despertar a Aquiles. En cada situación que enfrentamos, siempre tomaste la iniciativa. Has hecho tanto.",
  ui_story_5088_50881300_61_dialog_content = "... Jeje.",
  ui_story_5088_50881300_62_dialog_content = "Quizás tienes un punto.",
  ui_story_5088_50881300_63_dialog_content = "¡Entonces vamos!",
  ui_story_5088_50881300_64_dialog_content = "¿Ah?",
  ui_story_5088_50881300_65_dialog_content = "Para reunirme con todos...",
  ui_story_5088_50881300_66_dialog_content = "¡Vaya, es tan bonito! Nunca había visto un lugar así antes.",
  ui_story_5088_50881300_67_dialog_content = "Y estas flores...",
  ui_story_5088_50881300_68_dialog_content = "... ¿Niños?",
  ui_story_5088_50881300_69_dialog_content = "Deja de correr, pequeña niña, o acabarás arañándote con todas las plantas aquí. Ven, te mostraré las flores más bonitas.",
  ui_story_5088_50881300_70_dialog_content = "¡Oye, dama! ¡Eres tan alta!",
  ui_story_5088_50881300_71_dialog_content = "¿Te gustaría ser alto también?",
  ui_story_5088_50881300_72_dialog_content = "¿Con esto bastará?",
  ui_story_5088_50881300_73_dialog_content = "¡Guau! ¡Me estás levantando! ¡Ahora soy más alto que todos!",
  ui_story_5088_50881300_74_dialog_content = "... Si sales corriendo así, tus padres comenzarán a preocuparse.",
  ui_story_5088_50881300_75_dialog_content = "Está bien, señor, mi papá está allá con mi mamá mirando las flores!",
  ui_story_5088_50881300_76_dialog_content = "Señorita, esto... es para ti...",
  ui_story_5088_50881300_77_dialog_content = "Gracias.",
  ui_story_5088_50881300_78_dialog_content = "...",
  ui_story_5088_50881300_79_dialog_content = "Oye, señor, ¿no vas a venir?",
  ui_story_5088_50881300_80_dialog_content = "Gracias, pero me quedaré aquí y miraré por ahora.",
  ui_story_5088_50881300_81_dialog_content = "¡No! ¡Vamos, señor!",
  ui_story_5088_50881300_82_dialog_content = "¡Esa dama de la cola de caballo dijo que me dará muchos dulces deliciosos si te llevo!",
  ui_story_5088_50881300_83_dialog_content = "... ¿Freya?",
  ui_story_5088_50881300_84_dialog_content = "Je.",
  ui_story_5088_50881300_85_dialog_content = "¡Señor, estás sonriendo!",
  ui_story_5088_50881300_86_dialog_content = "Tienes una sonrisa realmente amigable.",
  ui_story_5088_50881300_87_dialog_content = "Vamos, vamos a conseguirte ese delicioso dulce.",
  ui_story_5088_50881300_88_dialog_content = "<color=#e8d9bb>Y así, las estrellas encontraron su hogar.</color>",
  ui_story_5088_50881300_89_dialog_content = "<color=#e8d9bb>La historia del reino y sus guerreros podría terminar aquí...</color>",
  ui_story_5088_50881300_90_dialog_content = "<color=#e8d9bb>Pero comenzará un nuevo capítulo.</color>",
  ui_story_5088_50881300_91_dialog_content = "<color=#e8d9bb>En medio de la alegría del reencuentro, nacerá un nuevo cuento de hadas...</color>",
  ui_story_5088_50881300_92_dialog_content = "<color=#e8d9bb>Y puedo asegurarte—tendrá un final feliz.</color>"
}
return config
